public abstract class GameView extends View implements Choreographer.FrameCallback {

    /* ---------- 主题色 ---------- */
    public static final int BG = 0xFF08090C;
    public static final int ACCENT = 0xFF4ADE80;
    public static final int TEXT = 0xFFF2F4F8;
    public static final int DIM = 0xFF8A93A6;
    public static final int DANGER = 0xFFF87171;

    /* ---------- 画布几何 ---------- */
