    protected float w, h;
    /** 屏幕圆心。 */
    protected float cx, cy;
    /** 显示屏半径。 */
    protected float R;
    /** 内切正方形半边长 —— 游戏内容的硬边界。 */
    protected float safe;

    /* ---------- 画笔 ---------- */
    protected final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
    protected final Paint tp = new Paint(Paint.ANTI_ALIAS_FLAG);
    protected final RectF tmpRect = new RectF();

    /* ---------- 状态 ---------- */
    private long lastNs;
    private boolean looping;
    private long lastTapAt;
    private long lastDownAt;

    /** 是否已暂停。 */
    protected boolean paused;
    /** 是否已结束。 */
    protected boolean over;
    /** 本局得分。 */
    protected int score;
    /** 历史最高分。 */
    protected int best;

    protected GameView(Context context) {
        super(context);
        setFocusable(true);
        setFocusableInTouchMode(true);
        setKeepScreenOn(true);
        tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        tp.setTextAlign(Paint.Align.CENTER);
    }

    /* =========================================================
     *  生命周期与帧循环
     * ========================================================= */

    @Override
    protected void onAttachedToWindow() {
        super.onAttachedToWindow();
        best = Prefs.best(getContext(), id());
        resetGame();
        startLoop();
    }

    @Override
    protected void onDetachedFromWindow() {
        stopLoop();
        super.onDetachedFromWindow();
    }

    /** 开始帧循环。 */
    public void startLoop() {
        if (looping) {
            return;
        }
        looping = true;
        lastNs = 0L;
        Choreographer.getInstance().postFrameCallback(this);
    }

    /** 停止帧循环。 */
    public void stopLoop() {
        looping = false;
        Choreographer.getInstance().removeFrameCallback(this);
    }

    @Override
    public void doFrame(long frameTimeNanos) {
        if (!looping) {
            return;
        }
        if (lastNs == 0L) {
            lastNs = frameTimeNanos;
        }
        float dt = (frameTimeNanos - lastNs) / 1_000_000_000f;
        lastNs = frameTimeNanos;
        if (dt > 0.05f) {
            dt = 0.05f; // 切后台回来时不要一次跳太多
        }
        if (!paused && !over) {
            update(dt);
        }
        invalidate();
        Choreographer.getInstance().postFrameCallback(this);
    }

    @Override
    protected void onSizeChanged(int nw, int nh, int ow, int oh) {
        super.onSizeChanged(nw, nh, ow, oh);
        w = nw;
        h = nh;
        cx = nw / 2f;
        cy = nh / 2f;
        R = Math.min(nw, nh) / 2f;
        // 内切正方形半边长 = R / √2，再乘 0.96 留一点视觉余量
        safe = R * 0.7071f * 0.96f;
        onLayoutReady();
    }

    /** 尺寸确定后回调，子类在这里按 safe 布置战场。 */
    protected void onLayoutReady() {
    }

    /* =========================================================
     *  子类需要实现的游戏逻辑
     * ========================================================= */

    /** 游戏唯一标识，用于存最高分。 */
    protected abstract String id();

    /** 每帧逻辑更新，dt 单位秒。 */
    protected abstract void update(float dt);

    /** 绘制游戏内容（背景与 HUD 由基类负责）。 */
    protected abstract void drawGame(Canvas c);

    /** 重置一局的全部状态。 */
    protected abstract void resetGame();

    /** 游戏内触摸事件（已排除「结束」与「暂停」状态）。 */
    protected boolean onGameTouch(MotionEvent e) {
        return true;
    }

    /** 给子类覆盖：游戏名，用于结束遮罩。 */
    protected String title() {
        return "";
    }

    /* =========================================================
     *  绘制
     * ========================================================= */

    @Override
    protected void onDraw(Canvas c) {
        c.drawColor(BG);
        c.save();
        // 把画布原点挪到圆心，子类用相对坐标作图更直观
        drawGame(c);
        c.restore();
        drawHud(c);
    }

    /** 顶部分数 + 圆形外圈。 */
    private void drawHud(Canvas c) {
        // 圆形装饰边框（贴着真实显示边界）
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(R * 0.012f);
        p.setColor(0x26FFFFFF);
        c.drawCircle(cx, cy, R * 0.965f, p);
        p.setStyle(Paint.Style.FILL);

        // 分数：放顶部圆弧内侧，用 safe 保证不被裁
        tp.setColor(over ? DIM : TEXT);
        tp.setTextSize(R * 0.13f);
        c.drawText(String.valueOf(score), cx, cy - safe * 0.90f, tp);

        if (paused && !over) {
            drawMask(c);
            tp.setColor(TEXT);
            tp.setTextSize(R * 0.16f);
            c.drawText("已暂停", cx, cy - R * 0.02f, tp);
            tp.setColor(DIM);
            tp.setTextSize(R * 0.095f);
            c.drawText("点击继续", cx, cy + R * 0.16f, tp);
        } else if (over) {
            drawMask(c);
            tp.setColor(ACCENT);
            tp.setTextSize(R * 0.185f);
            c.drawText("本局 " + score, cx, cy - R * 0.10f, tp);
            tp.setColor(TEXT);
            tp.setTextSize(R * 0.125f);
            c.drawText("最高 " + best, cx, cy + R * 0.08f, tp);
            tp.setColor(DIM);
            tp.setTextSize(R * 0.095f);
            c.drawText("点击重新开始", cx, cy + R * 0.30f, tp);
        }
    }

    private void drawMask(Canvas c) {
        p.setColor(0xD9080A0E);
        c.drawCircle(cx, cy, R, p);
    }

    /* =========================================================
     *  通用交互
     * ========================================================= */

    @Override
    public final boolean onTouchEvent(MotionEvent e) {
        int action = e.getActionMasked();

        if (over) {
            if (action == MotionEvent.ACTION_UP) {
                restart();
            }
            return true;
        }

        if (paused) {
            if (action == MotionEvent.ACTION_UP) {
                lastTapAt = 0L;
                setPaused(false);
            }
            return true;
        }

        if (action == MotionEvent.ACTION_DOWN) {
            lastDownAt = System.currentTimeMillis();
        } else if (action == MotionEvent.ACTION_UP) {
            long now = System.currentTimeMillis();
            // 短促的双击 = 暂停；否则交给游戏处理
            if (now - lastTapAt < 230L && now - lastDownAt < 230L) {
                lastTapAt = 0L;
                performClick();
                setPaused(true);
                return true;
            }
            lastTapAt = now;
        }

        return onGameTouch(e);
    }

    @Override
    public boolean performClick() {
        return super.performClick();
    }

    /* =========================================================
     *  工具方法
     * ========================================================= */

    public void setPaused(boolean value) {
        paused = value;
        lastNs = 0L;
        invalidate();
    }

    public boolean isPaused() {
        return paused;
    }

    /** 重新开始一局。 */
    public void restart() {
        over = false;
        paused = false;
        score = 0;
        lastNs = 0L;
        resetGame();
        invalidate();
    }

    /** 加分。 */
    protected void addScore(int delta) {
        score += delta;
    }

    /** 结束本局并刷新最高分。 */
    protected void finish() {
        over = true;
        if (score > best) {
            best = score;
            Prefs.setBest(getContext(), id(), best);
        }
        invalidate();
    }

    /** 在画布上画一个圆角矩形（相对圆心坐标）。 */
    protected void roundRect(Canvas c, float l, float t, float r, float b, float radius, int color) {
        p.setColor(color);
        tmpRect.set(l, t, r, b);
        c.drawRoundRect(tmpRect, radius, radius, p);
    }

    /** 依圆心画一个圆。 */
    protected void dot(Canvas c, float x, float y, float radius, int color) {
        p.setColor(color);
        c.drawCircle(x, y, radius, p);
    }

    protected static float clamp(float v, float lo, float hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }

    protected static int clampI(int v, int lo, int hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }
}
