private void step() {
    dirX = pendingDirX; dirY = pendingDirY;
    int nx = bx[0] + dirX;
    int ny = by[0] + dirY;
    if (nx < 0 || ny < 0 || nx >= N || ny >= N) { finish(); return; }
    for (int i = 0; i < len - 1; i++) {
        if (bx[i] == nx && by[i] == ny) { finish(); return; }
    }
    boolean eat = (nx == foodX && ny == foodY);
    int newLen = eat ? len + 1 : len;
    System.arraycopy(bx, 0, bx, 1, len);
    System.arraycopy(by, 0, by, 1, len);
    bx[0] = nx; by[0] = ny;
    len = newLen;
    if (eat) {
        addScore(1);
        stepTime = Math.max(0.075f, stepTime * 0.94f);
        spawnFood();
    }
}
```

