@Override
protected boolean onGameTouch(MotionEvent e) {
    switch (e.getActionMasked()) {
        case MotionEvent.ACTION_DOWN:
            downX = e.getX(); downY = e.getY(); swiping = true; break;
        case MotionEvent.ACTION_MOVE:
            if (!swiping) break;
            float dx = e.getX() - downX, dy = e.getY() - downY;
            float th = R * 0.16f;
            if (Math.abs(dx) > th || Math.abs(dy) > th) {
                if (Math.abs(dx) > Math.abs(dy)) setDir(dx > 0 ? 1 : -1, 0);
                else setDir(0, dy > 0 ? 1 : -1);
                downX = e.getX(); downY = e.getY();
            }
            break;
        case MotionEvent.ACTION_UP:
        case MotionEvent.ACTION_CANCEL:
            swiping = false; break;
        default: break;
    }
    return true;
}

private void setDir(int dx, int dy) {
    if (dx == -dirX && dy == -dirY) return;   // 不能 180° 掉头
    if (dx == dirX && dy == dirY) return;
    pendingDirX = dx; pendingDirY = dy;
}
