private void spawnFood() {
    int free = N*N - len;
    if (free <= 0) { finish(); return; }
    // 随机试，最多 200 次
    for (int t = 0; t < 300; t++) {
        int x = rnd.nextInt(N), y = rnd.nextInt(N);
        boolean hit = false;
        for (int i = 0; i < len; i++) if (bx[i]==x && by[i]==y) { hit = true; break; }
