package com.watcharcade.game;

import android.content.Context;
import android.graphics.Canvas;
import android.view.MotionEvent;

import java.util.Random;

/**
 * 贪吃蛇（圆形表盘版）。
 *
 * <p>整个战场就是圆的内切正方形，{@value #N}x{@value #N} 网格，所以蛇在任何位置都不会跑到圆角外面去。
 * 操作只用滑动——手表屏幕太小，塞方向键只会挡住视线。
 */
public class SnakeGame extends GameView {

    private static final int N = 11;
    private static final int START_LEN = 3;

    private final int[] bx = new int[N * N + 4];
    private final int[] by = new int[N * N + 4];
    private final Random rnd = new Random();

    private int len;
    private float cell;
    private float originX, originY;

    private int dirX = 1, dirY = 0;
    private int pendingX = 1, pendingY = 0;

    private int foodX, foodY;
    private float stepTime = 0.30f;
    private float acc;
    private float pulse;

    private float downX, downY;
    private boolean swiping;

    public SnakeGame(Context context) {
        super(context);
    }

    @Override
    protected String id() {
        return "snake";
    }

    @Override
    protected String title() {
        return "贪吃蛇";
    }

    @Override
    protected void onLayoutReady() {
        cell = (safe * 2f) / N;
        originX = cx - safe;
        originY = cy - safe;
    }

    @Override
    protected void resetGame() {
        len = START_LEN;
        dirX = 1;
        dirY = 0;
        pendingX = 1;
        pendingY = 0;
        stepTime = 0.30f;
        acc = 0f;
        pulse = 0f;
        swiping = false;
        int y = N / 2;
        for (int i = 0; i < len; i++) {
            bx[i] = N / 2 - i;
            by[i] = y;
        }
        spawnFood();
    }

    @Override
    protected void update(float dt) {
        pulse += dt * 5f;
        acc += dt;
        int guard = 0;
        while (acc >= stepTime && guard++ < 8) {
            acc -= stepTime;
            step();
            if (over) {
                acc = 0f;
                return;
            }
        }
    }

    private void step() {
        dirX = pendingX;
        dirY = pendingY;

        int nx = bx[0] + dirX;
        int ny = by[0] + dirY;

        if (nx < 0 || ny < 0 || nx >= N || ny >= N) {
            finish();
            return;
        }
        // 尾巴这一格马上会空出来，所以撞到最后一节不算死
        for (int i = 0; i < len - 1; i++) {
            if (bx[i] == nx && by[i] == ny) {
                finish();
                return;
            }
        }

        boolean eat = (nx == foodX && ny == foodY);
        System.arraycopy(bx, 0, bx, 1, len);
        System.arraycopy(by, 0, by, 1, len);
        bx[0] = nx;
        by[0] = ny;
        if (eat) {
            len++;
            addScore(1);
            stepTime = Math.max(0.075f, stepTime * 0.93f);
            spawnFood();
        }
    }

    private void spawnFood() {
        if (len >= N * N) {
            finish();
            return;
        }
        for (int attempt = 0; attempt < 400; attempt++) {
            int x = rnd.nextInt(N);
            int y = rnd.nextInt(N);
            if (!occupied(x, y)) {
                foodX = x;
                foodY = y;
                return;
            }
        }
        for (int y = 0; y < N; y++) {
            for (int x = 0; x < N; x++) {
                if (!occupied(x, y)) {
                    foodX = x;
                    foodY = y;
                    return;
                }
            }
        }
    }

    private boolean occupied(int x, int y) {
        for (int i = 0; i < len; i++) {
            if (bx[i] == x && by[i] == y) {
                return true;
            }
        }
        return false;
    }

    /* ---------------- 绘制 ---------------- */

    @Override
    protected void drawGame(Canvas c) {
        float gap = cell * 0.08f;

        // 网格底纹，给玩家一点空间参照
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, cell * 0.03f));
        p.setColor(0x12FFFFFF);
        for (int i = 0; i <= N; i++) {
            float gx = originX + i * cell;
            float gy = originY + i * cell;
            c.drawLine(gx, originY, gx, originY + N * cell, p);
            c.drawLine(originX, gy, originX + N * cell, gy, p);
        }
        p.setStyle(Paint.Style.FILL);

        // 内切正方形边框，让"战场"更明确
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(2f, cell * 0.09f));
        p.setColor(0x33FFFFFF);
        float pad = cell * 0.06f;
        c.drawRoundRect(new android.graphics.RectF(
                        originX - pad, originY - pad,
                        originX + N * cell + pad, originY + N * cell + pad),
                cell * 0.35f, cell * 0.35f, p);
        p.setStyle(Paint.Style.FILL);

        // 食物：带呼吸感的红点
        float fr = cell * (0.32f + 0.06f * (float) Math.sin(pulse));
        dot(c, originX + (foodX + 0.5f) * cell, originY + (foodY + 0.5f) * cell, fr, 0xFFF87171);
        dot(c, originX + (foodX + 0.5f) * cell, originY + (foodY + 0.5f) * cell, fr * 0.45f, 0xFFFECACA);

        // 蛇身：从尾到头做颜色渐变，头部最亮
        for (int i = len - 1; i >= 0; i--) {
            float t = len <= 1 ? 1f : 1f - (float) i / (float) (len - 1);
            int color = lerpColor(0xFF1B6B45, ACCENT, 0.25f + 0.75f * t);
            if (i == 0) {
                color = 0xFFA7F3D0;
            }
            float gx = originX + bx[i] * cell;
            float gy = originY + by[i] * cell;
            roundRect(c, gx + gap, gy + gap, gx + cell - gap, gy + cell - gap, cell * 0.30f, color);
        }

        // 蛇眼：让它看得到方向
        if (len > 0 && !over) {
            float hx = originX + (bx[0] + 0.5f) * cell;
            float hy = originY + (by[0] + 0.5f) * cell;
            float ex = dirY != 0 ? cell * 0.20f : 0f;
            float ey = dirX != 0 ? cell * 0.20f : 0f;
            float ox = dirX * cell * 0.13f;
            float oy = dirY * cell * 0.13f;
            dot(c, hx + ox - ex, hy + oy - ey, cell * 0.075f, 0xFF10131A);
            dot(c, hx + ox + ex, hy + oy + ey, cell * 0.075f, 0xFF10131A);
        }
    }

    /* ---------------- 输入 ---------------- */

    @Override
    protected boolean onGameTouch(MotionEvent e) {
        int action = e.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) {
            downX = e.getX();
            downY = e.getY();
            swiping = true;
        } else if (action == MotionEvent.ACTION_MOVE && swiping) {
            float dx = e.getX() - downX;
            float dy = e.getY() - downY;
            float threshold = R * 0.17f;
            if (Math.abs(dx) > threshold || Math.abs(dy) > threshold) {
                if (Math.abs(dx) > Math.abs(dy)) {
                    turn(dx > 0 ? 1 : -1, 0);
                } else {
                    turn(0, dy > 0 ? 1 : -1);
                }
                downX = e.getX();
                downY = e.getY();
            }
        } else if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
            swiping = false;
        }
        return true;
    }

    private void turn(int dx, int dy) {
        // 180° 掉头等于自杀，直接忽略
        if (dx == -dirX && dy == -dirY) {
            return;
        }
        if (dx == dirX && dy == dirY) {
            return;
        }
        pendingX = dx;
        pendingY = dy;
    }
}

