import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.view.MotionEvent;

/**
 * 打砖块（环形布局版）。
 *
 * <p>这是四个游戏里最"圆"的一个：砖块是若干圈<b>同心圆弧</b>，挡板是一段可以绕圆心 360° 旋转的圆弧，
 * 球从圆心附近出发、打在外圈砖块上再弹回来。
 * 传统打砖块的"上方砖块 + 底部挡板"在圆表上会浪费掉两侧一大片区域，环形布局能把整块圆形屏幕吃满。
 */
public class BreakoutGame extends GameView {

    private static final int ROWS = 3;
    /** 每行的砖块数量：外圈弧长大，所以分得更细。 */
    private static final int[] PER_ROW = {16, 14, 12};
    /** 砖块之间的角度缝隙（度）。 */
    private static final float GAP_DEG = 2.4f;
    private static final int MAX_LIVES = 3;

    private static final int[] ROW_COLOR = {0xFF4ADE80, 0xFF38BDF8, 0xFFA78BFA};

    private final boolean[][] alive = new boolean[ROWS][];
    private final float[] rIn = new float[ROWS];
    private final float[] rOut = new float[ROWS];
    private final RectF arcRect = new RectF();

    /* 球：位置与方向都相对圆心，方向是单位向量 */
    private float ballX, ballY;
    private float dirX, dirY;
    private float ballR;
    private float speedMul;

    /* 挡板 */
    private float paddleR, paddleThick, paddleHalfDeg, paddleAngleDeg;

    /** 球越过了这个半径就丢一条命。 */
    private float deadR;

    private int lives;
    private int level;
    private boolean waiting;
    private float waitTimer;
    private float hitFlash;

    public BreakoutGame(Context context) {
        super(context);
        for (int row = 0; row < ROWS; row++) {
            alive[row] = new boolean[PER_ROW[row]];
        }
    }

    @Override
    protected String id() {
        return "breakout";
    }

    @Override
    protected String title() {
        return "打砖块";
    }

    @Override
    protected void onLayoutReady() {
        ballR = R * 0.038f;
        paddleR = R * 0.45f;
        paddleThick = R * 0.058f;
        paddleHalfDeg = 27f;
        deadR = R * 0.24f;
        for (int row = 0; row < ROWS; row++) {
            rOut[row] = R * (0.905f - row * 0.09f);
            rIn[row] = rOut[row] - R * 0.082f;
        }
        // 布局变化时把球拉回圆心附近，避免留在非法位置
        if (waiting) {
            snapBallToPaddle();
        }
    }

    @Override
    protected void resetGame() {
        level = 1;
        lives = MAX_LIVES;
        speedMul = 1.0f;
        paddleAngleDeg = -90f;
        buildBricks();
        waiting = true;
        waitTimer = 0.9f;
        hitFlash = 0f;
        snapBallToPaddle();
    }

    private void buildBricks() {
        for (int row = 0; row < ROWS; row++) {
            for (int i = 0; i < PER_ROW[row]; i++) {
                alive[row][i] = true;
            }
        }
    }

    private void snapBallToPaddle() {
        double a = Math.toRadians(paddleAngleDeg);
        ballX = (float) Math.cos(a) * paddleR;
        ballY = (float) Math.sin(a) * paddleR;
        dirX = (float) Math.cos(a);
        dirY = (float) Math.sin(a);
    }

    private float speed() {
        return R * 1.02f * speedMul;
    }

    /* ---------------- 逻辑 ---------------- */

    @Override
    protected void update(float dt) {
        if (hitFlash > 0f) {
            hitFlash -= dt;
        }

        if (waiting) {
            // 发射前球黏在挡板上，跟着挡板转
            snapBallToPaddle();
            waitTimer -= dt;
            if (waitTimer <= 0f) {
                waiting = false;
            }
            return;
        }

        int sub = 4;
        float h = dt / sub;
        for (int i = 0; i < sub; i++) {
            if (over || waiting) {
                return;
            }
            step(h);
        }
    }

    private void step(float h) {
        float v = speed();
        ballX += dirX * v * h;
        ballY += dirY * v * h;

        float d = (float) Math.hypot(ballX, ballY);
        if (d < 0.0001f) {
            d = 0.0001f;
        }

        // 1) 外圈：球撞到最外层砖块之外的圆壁就弹回来
        float outer = rOut[0] + ballR;
        if (d > outer) {
            float s = outer / d;
            ballX *= s;
            ballY *= s;
            reflectRadial(ballX, ballY, d);
            d = outer;
        }

        // 2) 砖块
        if (hitBricks(d)) {
            return;
        }

        // 3) 挡板
        float angDeg = normDeg((float) Math.toDegrees(Math.atan2(ballY, ballX)));
        float diff = diffDeg(angDeg, paddleAngleDeg);
        float innerBound = paddleR - paddleThick * 0.5f - ballR;
        float outerBound = paddleR + paddleThick * 0.5f + ballR;
        if (d >= innerBound && d <= outerBound && Math.abs(diff) <= paddleHalfDeg) {
            float nx = ballX / d;
            float ny = ballY / d;
            float dot = dirX * nx + dirY * ny;
            if (dot < 0f) { // 只有朝圆心飞来的球才被挡
                reflectRadial(nx, ny, 1f);
                // 撞击点偏离挡板中心越多，出球角度越斜 —— 这就是玩家的"瞄准"手段
                float off = diff / paddleHalfDeg;
                float tx = -ny;
                float ty = nx;
                dirX += tx * off * 0.75f;
                dirY += ty * off * 0.75f;
                normalizeDir();
                float push = outerBound + R * 0.01f;
                float s = push / d;
                ballX *= s;
                ballY *= s;
            }
        }

        // 4) 掉进中心算丢命
        float dNow = (float) Math.hypot(ballX, ballY);
        if (dNow < deadR) {
            loseLife();
        }
    }

    /** 以圆心为原点、经过 (px,py) 的径向方向做镜面反射。 */
    private void reflectRadial(float px, float py, float len) {
        float nx = px / len;
        float ny = py / len;
        float dot = dirX * nx + dirY * ny;
        dirX -= 2f * dot * nx;
        dirY -= 2f * dot * ny;
        normalizeDir();
    }

    private void normalizeDir() {
        float m = (float) Math.hypot(dirX, dirY);
        if (m < 0.0001f) {
            dirX = 0f;
            dirY = -1f;
            return;
        }
        dirX /= m;
        dirY /= m;
    }

    private boolean hitBricks(float d) {
        float ang = normDeg((float) Math.toDegrees(Math.atan2(ballY, ballX)));
        for (int row = 0; row < ROWS; row++) {
            if (d < rIn[row] - ballR || d > rOut[row] + ballR) {
                continue;
            }
            int count = PER_ROW[row];
            float per = 360f / count;
            int idx = clampI((int) (ang / per), 0, count - 1);
            if (!alive[row][idx]) {
                continue;
            }
            float start = idx * per + GAP_DEG * 0.5f;
            float end = (idx + 1) * per - GAP_DEG * 0.5f;
            if (ang < start || ang > end) {
                continue; // 从砖块缝隙里穿过去了
            }

            alive[row][idx] = false;
            addScore(1);
            hitFlash = 0.12f;

            // 从内侧撞就弹回内侧，从外侧撞就弹向外侧
            float mid = (rIn[row] + rOut[row]) * 0.5f;
            float push = d < mid ? (rIn[row] - ballR - 1f) : (rOut[row] + ballR + 1f);
            push = Math.max(push, R * 0.08f);
            reflectRadial(ballX, ballY, d);
            float s = push / d;
            ballX *= s;
            ballY *= s;

            checkCleared();
            return true;
        }
        return false;
    }

    private void checkCleared() {
        for (int row = 0; row < ROWS; row++) {
            for (int i = 0; i < PER_ROW[row]; i++) {
                if (alive[row][i]) {
                    return;
                }
            }
        }
        // 全清：加难度再来一轮
        level++;
        addScore(5);
        speedMul *= 1.12f;
        buildBricks();
        waiting = true;
        waitTimer = 0.9f;
        snapBallToPaddle();
    }

    private void loseLife() {
        lives--;
        if (lives <= 0) {
            finish();
            return;
        }
        waiting = true;
        waitTimer = 0.9f;
        snapBallToPaddle();
    }

    /* ---------------- 绘制 ---------------- */

    @Override
    protected void drawGame(Canvas c) {
        // 内部死亡区提示圈
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(R * 0.006f);
        p.setColor(0x1AFFFFFF);
        c.drawCircle(cx, cy, deadR, p);
        c.drawCircle(cx, cy, R * 0.32f, p);

        // 砖块
        for (int row = 0; row < ROWS; row++) {
            float mid = (rIn[row] + rOut[row]) * 0.5f;
            float thick = rOut[row] - rIn[row];
            arcRect.set(cx - mid, cy - mid, cx + mid, cy + mid);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(thick);
            p.setStrokeCap(Paint.Cap.BUTT);
            int base = ROW_COLOR[row];
            for (int i = 0; i < PER_ROW[row]; i++) {
                if (!alive[row][i]) {
                    continue;
                }
                float per = 360f / PER_ROW[row];
                p.setColor(base);
                c.drawArc(arcRect, i * per + GAP_DEG * 0.5f, per - GAP_DEG, false, p);
            }
        }
        p.setStyle(Paint.Style.FILL);

        // 挡板
        arcRect.set(cx - paddleR, cy - paddleR, cx + paddleR, cy + paddleR);
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(paddleThick);
        p.setStrokeCap(Paint.Cap.ROUND);
        p.setColor(0xFFE2E8F0);
        c.drawArc(arcRect, paddleAngleDeg - paddleHalfDeg, paddleHalfDeg * 2f, false, p);
        p.setStrokeCap(Paint.Cap.BUTT);
        p.setStyle(Paint.Style.FILL);

        // 球
        int ballColor = hitFlash > 0f ? 0xFFFFFFFF : 0xFFFDE68A;
        c.drawCircle(cx + ballX, cy + ballY, ballR, p);
        dot(c, cx + ballX, cy + ballY, ballR, ballColor);
        dot(c, cx + ballX, cy + ballY, ballR * 0.45f, 0xFFFFFFFF);

        // 剩余生命：圆心下方的小点
        for (int i = 0; i < lives; i++) {
            float lx = cx + (i - (MAX_LIVES - 1) / 2f) * R * 0.075f;
            dot(c, lx, cy + R * 0.115f, R * 0.018f, 0xFF4ADE80);
        }

        // 关卡
        tp.setColor(DIM);
        tp.setTextSize(R * 0.075f);
        c.drawText("LV " + level, cx, cy - R * 0.115f, tp);
    }

    @Override
    protected float scoreAnchorY() {
        return cy - R * 0.005f;
    }

    @Override
    protected float scoreTextSize() {
        return R * 0.115f;
    }

    /* ---------------- 输入 ---------------- */

    @Override
    protected boolean onGameTouch(MotionEvent e) {
        int action = e.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN || action == MotionEvent.ACTION_MOVE) {
            float dx = e.getX() - cx;
            float dy = e.getY() - cy;
            // 手指太靠近圆心时角度会乱跳，直接忽略
            if (Math.hypot(dx, dy) > R * 0.22f) {
                paddleAngleDeg = (float) Math.toDegrees(Math.atan2(dy, dx));
            }
        }
        return true;
    }

    /* ---------------- 角度工具 ---------------- */

    private static float normDeg(float a) {
        a %= 360f;
        if (a < 0f) {
            a += 360f;
        }
        return a;
    }

    private static float diffDeg(float a, float b) {
        float d = normDeg(a - b);
        if (d > 180f) {
            d -= 360f;
        }
        return d;
    }
}
"}

