    private boolean collide(int[][] shape, int ox, int oy) {
        for (int y = 0; y < N; y++) {
            for (int x = 0; x < N; x++) {
                if (shape[y][x] == 0) {
                    continue;
                }
                int fx = ox + x;
                int fy = oy + y;
                if (fx < 0 || fx >= COLS || fy >= ROWS) {
                    return true;
                }
                if (fy < 0) {
                    continue;
                }
                if (field[fy][fx] != 0) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean tryMove(int dx) {
        if (!collide(cur, curX + dx, curY)) {
            curX += dx;
            return true;
        }
        return false;
