    private void rotate() {
        int[][] next = rotateCW(cur);
        int[] kicks = {0, -1, 1, -2, 2};
        for (int k : kicks) {
            if (!collide(next, curX + k, curY)) {
                cur = next;
                curX += k;
                return;
            }
        }
