    private static int[][] rotateCW(int[][] m) {
        int n = m.length;
        int[][] r = new int[n][n];
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                r[x][n - 1 - y] = m[y][x];
            }
        }
        return r;
    }

    private float fallInterval() {
        return Math.max(0.09f, 0.62f - cleared * 0.024f);
    }

    @Override
    protected void update(float dt) {
        float iv = fallInterval();
        fallAcc += dt * (fastDrop ? 9f : 1f);
        int guard = 0;
        while (fallAcc >= iv && guard++ < 24) {
            fallAcc -= iv;
            if (!collide(cur, curX, curY + 1)) {
                curY++;
            } else {
                lock();
                if (over) {
                    return;
                }
            }
        }
    }

    private void lock() {
        boolean spilledOverTop = false;
        for (int y = 0; y < N; y++) {
            for (int x = 0; x < N; x++) {
                if (cur[y][x] == 0) {
                    continue;
                }
                int fx = curX + x;
                int fy = curY + y;
                if (fy < 0) {
                    spilledOverTop = true;
                    continue;
                }
                field[fy][fx] = curColor;
            }
        }
        if (spilledOverTop) {
            finish();
            return;
        }

        int lines = clearLines();
        if (lines > 0) {
            cleared += lines;
            addScore(lines * (lines + 1) / 2);
        }

        spawn();
        if (collide(cur, curX, curY)) {
            finish();
        }
