    private int clearLines() {
        int lines = 0;
        for (int y = ROWS - 1; y >= 0; y--) {
            boolean full = true;
            for (int x = 0; x < COLS; x++) {
                if (field[y][x] == 0) {
                    full = false;
                    break;
                }
            }
            if (!full) {
                continue;
            }
            lines++;
            for (int yy = y; yy > 0; yy--) {
                System.arraycopy(field[yy - 1], 0, field[yy], 0, COLS);
