                    if (cur[y][x] != 0 && curY + y >= 0) {
                        drawCell(c, curX + x, curY + y, curColor, 1f);
                    }
                }
            }
        }
    }

    private void drawCell(Canvas c, int gx, int gy, int colorIdx, float alpha) {
        float x = boardLeft + gx * cellPx;
        float y = boardTop + gy * cellPx;
        float pad = cellPx * 0.07f;
        int base = COLORS[colorIdx - 1];
        int color = alpha >= 1f
                ? base
                : lerpColor(base, 0x00000000, 0f) & 0x00FFFFFF | 0xFF000000;
        if (alpha < 1f) {
            // 幽灵块：只留描边，颜色压暗
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(Math.max(1.5f, cellPx * 0.09f));
            p.setColor(0x66FFFFFF);
            tmpRect.set(x + pad, y + pad, x + cellPx - pad, y + cellPx - pad);
            c.drawRoundRect(tmpRect, cellPx * 0.22f, cellPx * 0.22f, p);
            p.setStyle(Paint.Style.FILL);
            return;
        }
        roundRect(c, x + pad, y + pad, x + cellPx - pad, y + cellPx - pad, cellPx * 0.22f, color);
        roundRect(c, x + pad * 2.4f, y + pad * 2.4f,
                x + cellPx - pad * 2.4f, y + cellPx - pad * 4.2f,
                cellPx * 0.16f, lerpColor(color, 0xFFFFFFFF, 0.34f));
    }

