    @Override
    protected boolean onGameTouch(MotionEvent e) {
        switch (e.getActionMasked()) {
            case MotionEvent.ACTION_DOWN:
                downX = e.getX();
                downY = e.getY();
                lastMoveX = e.getX();
                moved = false;
                fastDrop = false;
                break;
            case MotionEvent.ACTION_MOVE: {
                if (e.getY() - downY > R * 0.22f) {
                    fastDrop = true;
                }
                float threshold = Math.max(1f, cellPx * 0.80f);
                while (Math.abs(e.getX() - lastMoveX) >= threshold) {
                    if (e.getX() > lastMoveX) {
                        tryMove(1);
                        lastMoveX += threshold;
                    } else {
                        tryMove(-1);
                        lastMoveX -= threshold;
                    }
                    moved = true;
                }
                if (Math.abs(e.getX() - downX) > R * 0.10f) {
                    moved = true;
                }
                break;
            }
            case MotionEvent.ACTION_UP:
            case MotionEvent.ACTION_CANCEL:
                if (!moved && !fastDrop) {
                    rotate();
                }
                fastDrop = false;
                break;
            default:
                break;
        }
        return true;
    }
}
