            float pr = clamp(jumpT / jumpDur, 0f, 1f);
            charX = jumpFromX + (jumpToX - jumpFromX) * pr;
            charY = platformTop - charH - 4f * jumpHeight * pr * (1f - pr);
            if (pr >= 1f) {
