{"file_path": "C:/Users/MuQiu/WorkBuddy/2026-10-16-17-52-04/WatchArcade/app/src/main/java/com/watcharcade/game/RingMenuView.java", "content": "package com.watcharcade.game;

import android.content.Context;
import android.content.Intent;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;
import android.view.MotionEvent;
import android.view.View;

/**
 * 圆环主菜单：四个游戏沿圆环分布，点哪块进哪个。
 *
 * <p>方形列表在圆表上左右两侧会被裁掉，所以这里直接用环形分区，
 * 命中判定也按「半径 + 角度」来算。
 */
public class RingMenuView extends View {

    private static final String[] KEYS = {"snake", "breakout", "tetris", "jump"};
    private static final String[] LABELS = {"贪吃蛇", "打砖块", "俄罗斯", "跳一跳"};
    private static final int[] COLORS = {0xFF4ADE80, 0xFF38BDF8, 0xFFA78BFA, 0xFFFBBF24};

    private static final float GAP_DEG = 6f;
    private static final float CENTER_X = 0f;
    private static final float CENTER_Y = 90f;
    private static final float CENTER_LEFT = 180f;
    private static final float CENTER_TOP = 270f;
    private static final float[] CENTERS = {CENTER_X, CENTER_Y, CENTER_LEFT, CENTER_TOP};

    private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint tp = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final RectF arc = new RectF();

    private float cx, cy, R, rIn, rOut, rMid;

    private int pressed = -1;
    private float pressScale;
    private float t;

    public RingMenuView(Context context) {
        super(context);
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeCap(Paint.Cap.BUTT);
        tp.setTextAlign(Paint.Align.CENTER);
        tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        setFocusable(true);
        setKeepScreenOn(true);
    }

    @Override
    protected void onSizeChanged(int w, int h, int ow, int oh) {
        super.onSizeChanged(w, h, ow, oh);
        cx = w / 2f;
        cy = h / 2f;
        R = Math.min(w, h) / 2f;
        rOut = R * 0.92f;
        rIn = R * 0.50f;
        rMid = (rIn + rOut) * 0.5f;
    }

    @Override
    protected void onDraw(Canvas c) {
        c.drawColor(GameView.BG);
        t += 0.03f;

        // 装饰外圈
        p.setStrokeWidth(R * 0.012f);
        p.setColor(0x1FFFFFFF);
        c.drawCircle(cx, cy, R * 0.965f, p);
        c.drawCircle(cx, cy, R * 0.44f, p);

        for (int i = 0; i < KEYS.length; i++) {
            float center = CENTERS[i];
            boolean active = pressed == i;
            float grow = active ? R * 0.03f : 0f;

            arc.set(cx - (rMid + grow), cy - (rMid + grow), cx + (rMid + grow), cy + (rMid + grow));
            p.setStrokeWidth(rOut - rIn + grow * 2f);
            p.setColor(active ? brighten(COLORS[i]) : COLORS[i]);
            c.drawArc(arc, center - 45f + GAP_DEG, 90f - GAP_DEG * 2f, false, p);
        }

        // 每个扇区里的名字
        tp.setColor(0xFF0B0E13);
        tp.setTextSize(R * 0.115f);
        for (int i = 0; i < KEYS.length; i++) {
            double a = Math.toRadians(CENTERS[i]);
            float tx = cx + (float) Math.cos(a) * rMid;
            float ty = cy + (float) Math.sin(a) * rMid;
            c.drawText(LABELS[i], tx, ty + R * 0.04f, tp);
        }

        // 圆心标题 + 最高分
        tp.setColor(0xFFF2F4F8);
        tp.setTextSize(R * 0.115f);
        c.drawText("腕上游戏厅", cx, cy - R * 0.05f, tp);
        tp.setColor(0xFF8A93A6);
        tp.setTextSize(R * 0.085f);
        c.drawText("选一个开玩", cx, cy + R * 0.10f, tp);
    }

    private static int brighten(int color) {
        return GameView.lerpColor(color, 0xFFFFFFFF, 0.28f);
    }

    @Override
    public boolean onTouchEvent(MotionEvent e) {
        int action = e.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) {
            pressed = hit(e.getX(), e.getY());
            invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            int now = hit(e.getX(), e.getY());
            if (now != pressed) {
                pressed = now;
                invalidate();
            }
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            int target = hit(e.getX(), e.getY());
            if (target >= 0 && target == pressed) {
                launch(target);
            }
            pressed = -1;
            invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_CANCEL) {
            pressed = -1;
            invalidate();
            return true;
        }
        return super.onTouchEvent(e);
    }

    private void launch(int index) {
        Context ctx = getContext();
        Intent intent = new Intent(ctx, GameActivity.class);
        intent.putExtra(GameActivity.EXTRA_GAME, KEYS[index]);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        ctx.startActivity(intent);
    }

    /** 按半径 + 角度判断点中了哪个扇区，没命中返回 -1。 */
    private int hit(float x, float y) {
        float dx = x - cx;
        float dy = y - cy;
        float d = (float) Math.hypot(dx, dy);
        if (d < rIn || d > rOut) {
            return -1;
        }
        float ang = (float) Math.toDegrees(Math.atan2(dy, dx)); // -180..180
        for (int i = 0; i < CENTERS.length; i++) {
            float diff = ang - CENTERS[i];
            while (diff > 180f) {
                diff -= 360f;
            }
            while (diff < -180f) {
                diff += 360f;
            }
            if (Math.abs(diff) <= 45f - GAP_DEG) {
                return i;
            }
        }
        return -1;
    }
}
