 44→    protected final Paint tp = new Paint(Paint.ANTI_ALIAS_FLAG);
 45→    protected final RectF tmpRect = new RectF();
 46→
 47→    /* ---------- 状态 ---------- */
 48→    private long lastNs;
 49→    private boolean looping;
 50→    private long lastTapAt;
 51→    private long lastDownAt;
 52→
 53→    /** 是否已暂停。 */
 54→    protected boolean paused;
 55→    /** 是否已结束。 */
 56→    protected boolean over;
 57→    /** 本局得分。 */
 58→    protected int score;
 59→    /** 历史最高分。 */
 60→    protected int best;
 61→
 62→    protected GameView(Context context) {
 63→        super(context);
 64→        setFocusable(true);
 65→        setFocusableInTouchMode(true);
 66→        setKeepScreenOn(true);
 67→        tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
 68→        tp.setTextAlign(Paint.Align.CENTER);
 69→    }
 70→
 71→    /* =========================================================
 72→     *  生命周期与帧循环
 73→     * ========================================================= */
 74→
 75→    @Override
 76→    protected void onAttachedToWindow() {
 77→        super.onAttachedToWindow();
 78→        best = Prefs.best(getContext(), id());
