 92→            return;
 93→        }
 94→        looping = true;
 95→        lastNs = 0L;
 96→        Choreographer.getInstance().postFrameCallback(this);
 97→    }
 98→
 99→    /** 停止帧循环。 */
100→    public void stopLoop() {
101→        looping = false;
102→        Choreographer.getInstance().removeFrameCallback(this);
103→    }
104→
105→    @Override
106→    public void doFrame(long frameTimeNanos) {
107→        if (!looping) {
108→            return;
109→        }
110→        if (lastNs == 0L) {
111→            lastNs = frameTimeNanos;
112→        }
113→        float dt = (frameTimeNanos - lastNs) / 1_000_000_000f;
114→        lastNs = frameTimeNanos;
115→        if (dt > 0.05f) {
116→            dt = 0.05f; // 切后台回来时不要一次跳太多
117→        }
118→        if (!paused && !over) {
119→            update(dt);
120→        }
121→        invalidate();
122→        Choreographer.getInstance().postFrameCallback(this);
123→    }
124→
125→    @Override
126→    protected void onSizeChanged(int nw, int nh, int ow, int oh) {
127→        super.onSizeChanged(nw, nh, ow, oh);
128→        w = nw;
129→        h = nh;
