149→    /** 每帧逻辑更新，dt 单位秒。 */
150→    protected abstract void update(float dt);
151→
152→    /** 绘制游戏内容（背景与 HUD 由基类负责）。 */
153→    protected abstract void drawGame(Canvas c);
154→
155→    /** 重置一局的全部状态。 */
156→    protected abstract void resetGame();
157→
158→    /** 游戏内触摸事件（已排除「结束」与「暂停」状态）。 */
159→    protected boolean onGameTouch(MotionEvent e) {
160→        return true;
161→    }
162→
163→    /** 给子类覆盖：游戏名，用于结束遮罩。 */
164→    protected String title() {
