174→        c.drawColor(BG);
175→        c.save();
176→        // 把画布原点挪到圆心，子类用相对坐标作图更直观
177→        drawGame(c);
178→        c.restore();
179→        drawHud(c);
180→    }
181→
182→    /** 顶部分数 + 圆形外圈。 */
183→    private void drawHud(Canvas c) {
184→        // 圆形装饰边框（贴着真实显示边界）
185→        p.setStyle(Paint.Style.STROKE);
186→        p.setStrokeWidth(R * 0.012f);
187→        p.setColor(0x26FFFFFF);
188→        c.drawCircle(cx, cy, R * 0.965f, p);
189→        p.setStyle(Paint.Style.FILL);
190→
191→        // 分数：默认贴顶部安全区；打砖块这类环形布局的游戏可以覆盖锚点，改到圆心附近
192→        tp.setColor(over ? DIM : TEXT);
193→        tp.setTextSize(scoreTextSize());
194→        c.drawText(String.valueOf(score), cx, scoreAnchorY(), tp);
195→
196→        if (paused && !over) {
197→            drawMask(c);
198→            tp.setColor(TEXT);
199→            tp.setTextSize(R * 0.16f);
200→            c.drawText("已暂停", cx, cy - R * 0.02f, tp);
201→            tp.setColor(DIM);
202→            tp.setTextSize(R * 0.095f);
203→            c.drawText("点击继续", cx, cy + R * 0.16f, tp);
204→        } else if (over) {
205→            drawMask(c);
206→            tp.setColor(ACCENT);
207→            tp.setTextSize(R * 0.185f);
208→            c.drawText("本局 " + score, cx, cy - R * 0.10f, tp);
209→            tp.setColor(TEXT);
210→            tp.setTextSize(R * 0.125f);
211→            c.drawText("最高 " + best, cx, cy + R * 0.08f, tp);
212→            tp.setColor(DIM);
213→            tp.setTextSize(R * 0.095f);
214→            c.drawText("点击重新开始", cx, cy + R * 0.30f, tp);
215→        }
216→    }
217→
218→    /** 子类可以覆盖：分数文字的基线 y。 */
219→    protected float scoreAnchorY() {
220→        return cy - safe * 0.90f;
221→    }
222→
223→    /** 子类可以覆盖：分数文字大小。 */
224→    protected float scoreTextSize() {
225→        return R * 0.13f;
226→    }
227→
228→    private void drawMask(Canvas c) {
229→        p.setColor(0xD9080A0E);
230→        c.drawCircle(cx, cy, R, p);
231→    }
232→
233→    /* =========================================================
234→     *  通用交互
235→     * ========================================================= */
236→
237→    @Override
238→    public final boolean onTouchEvent(MotionEvent e) {
239→        int action = e.getActionMasked();
240→
241→        if (over) {
242→            if (action == MotionEvent.ACTION_UP) {
243→                restart();
244→            }
245→            return true;
246→        }
247→
248→        if (paused) {
249→            if (action == MotionEvent.ACTION_UP) {
250→                lastTapAt = 0L;
251→                setPaused(false);
252→            }
253→            return true;
254→        }
255→
256→        if (action == MotionEvent.ACTION_DOWN) {
257→            lastDownAt = System.currentTimeMillis();
258→        } else if (action == MotionEvent.ACTION_UP) {
259→            long now = System.currentTimeMillis();
260→            // 短促的双击 = 暂停；否则交给游戏处理
261→            if (now - lastTapAt < 230L && now - lastDownAt < 230L) {
262→                lastTapAt = 0L;
263→                performClick();
264→                setPaused(true);
265→                return true;
266→            }
267→            lastTapAt = now;
268→        }
269→
270→        return onGameTouch(e);
271→    }
272→
273→    @Override
274→    public boolean performClick() {
275→        return super.performClick();
276→    }
277→
278→    /* =========================================================
279→     *  工具方法
280→     * ========================================================= */
281→
282→    public void setPaused(boolean value) {
283→        paused = value;
284→        lastNs = 0L;
285→        invalidate();
286→    }
287→
288→    public boolean isPaused() {
289→        return paused;
290→    }
291→
292→    /** 重新开始一局。 */
293→    public void restart() {
294→        over = false;
295→        paused = false;
296→        score = 0;
297→        lastNs = 0L;
298→        resetGame();
299→        invalidate();
300→    }
301→
302→    /** 加分。 */
303→    protected void addScore(int delta) {
304→        score += delta;
305→    }
306→
307→    /** 结束本局并刷新最高分。 */
308→    protected void finish() {
309→        over = true;
