324→    /** 依圆心画一个圆。 */
325→    protected void dot(Canvas c, float x, float y, float radius, int color) {
326→        p.setColor(color);
327→        c.drawCircle(x, y, radius, p);
328→    }
329→
330→    protected static float clamp(float v, float lo, float hi) {
331→        return v < lo ? lo : (v > hi ? hi : v);
332→    }
333→
334→    protected static int clampI(int v, int lo, int hi) {
335→        return v < lo ? lo : (v > hi ? hi : v);
336→    }
337→
338→    /** 两个 ARGB 颜色之间线性插值，t 取 [0,1]。 */
339→    protected static int lerpColor(int from, int to, float t) {
340→        t = clamp(t, 0f, 1f);
341→        int a0 = (from >>> 24) & 0xFF, a1 = (to >>> 24) & 0xFF;
342→        int r0 = (from >>> 16) & 0xFF, r1 = (to >>> 16) & 0xFF;
343→        int g0 = (from >>> 8) & 0xFF, g1 = (to >>> 8) & 0xFF;
344→        int b0 = from & 0xFF, b1 = to & 0xFF;
345→        int a = (int) (a0 + (a1 - a0) * t);
346→        int r = (int) (r0 + (r1 - r0) * t);
347→        int g = (int) (g0 + (g1 - g0) * t);
348→        int b = (int) (b0 + (b1 - b0) * t);
349→        return (a << 24) | (r << 16) | (g << 8) | b;
350→    }
351→}
