    private static final int BTN_PRIMARY = 0;
    private static final int BTN_MENU = 1;

    /** 连击计分处多少次唤出暂停。 */
    private static final int TAP_COUNT_FOR_PAUSE = 3;
    /** 连击的有效时间窗口（毫秒）。 */
    private static final long TAP_WINDOW_MS = 1600L;

    /* ---------- 画布几何 ---------- */
    protected float w, h;
    protected float cx, cy;
    /** 显示屏半径。 */
    protected float R;
    /** 内切正方形半边长 —— 游戏内容的硬边界。 */
