        tp.setColor(primary ? 0xFF0B0E13 : TEXT);
        tp.setTextSize((r[3] - r[1]) * 0.42f);
        c.drawText(label, (r[0] + r[2]) * 0.5f, r[3] - (r[3] - r[1]) * 0.33f, tp);
