    }

    /* =========================================================
     *  交互
     * ========================================================= */

    @Override
    public final boolean onTouchEvent(MotionEvent e) {
        int action = e.getActionMasked();

        if (over) {
            if (action == MotionEvent.ACTION_UP) {
                int btn = hitButton(e.getX(), e.getY());
                if (btn == BTN_PRIMARY) {
                    performClick();
                    restart();
                } else if (btn == BTN_MENU) {
                    performClick();
                    backToMenu();
                }
            }
            return true;
        }

        if (paused) {
            if (action == MotionEvent.ACTION_UP) {
                int btn = hitButton(e.getX(), e.getY());
                if (btn == BTN_PRIMARY) {
                    performClick();
                    setPaused(false);
                } else if (btn == BTN_MENU) {
                    performClick();
                    backToMenu();
                }
            }
            return true;
        }

        if (action == MotionEvent.ACTION_DOWN) {
            downX = e.getX();
            downY = e.getY();
            moved = false;
        } else if (action == MotionEvent.ACTION_MOVE) {
            if (Math.hypot(e.getX() - downX, e.getY() - downY) > R * 0.075f) {
                moved = true;
            }
        } else if (action == MotionEvent.ACTION_UP) {
            if (!moved && inScoreZone(e.getX(), e.getY()) && registerScoreTap()) {
                performClick();
                setPaused(true);
                return true;
            }
        }

        return onGameTouch(e);
    }

    private boolean inScoreZone(float x, float y) {
        float[] z = scoreZone();
        return x >= z[0] && x <= z[2] && y >= z[1] && y <= z[3];
    }

    /** 记录一次「点击计分处」，够三次就返回 true。 */
    private boolean registerScoreTap() {
        long now = System.currentTimeMillis();
        if (scoreTaps == 0 || now - firstTapAt > TAP_WINDOW_MS) {
            scoreTaps = 1;
            firstTapAt = now;
        } else {
            scoreTaps++;
        }
        if (scoreTaps >= TAP_COUNT_FOR_PAUSE) {
            scoreTaps = 0;
            return true;
        }
        return false;
    }

    @Override
    public boolean performClick() {
        return super.performClick();
    }

    /* =========================================================
     *  对外操作
     * ========================================================= */

    public void setPaused(boolean value) {
        paused = value;
        lastNs = 0L;
        scoreTaps = 0;
        tempDirIgnore();
        invalidate();
    }

    /** 暂停切换时清掉子类可能残留的半截输入。 */
    private void tempDirIgnore() {
        onPauseToggled();
    }

    /** 子类可覆盖：暂停状态变化时清理输入（例如取消正在蓄力的手势）。 */
    protected void onPauseToggled() {
    }

    public boolean isPaused() {
        return paused;
    }

    /** 重新开始一局。 */
    public void restart() {
        over = false;
        paused = false;
        score = 0;
        lastNs = 0L;
        hintTimer = 3.5f;
        resetGame();
        invalidate();
    }

    /** 把这个游戏当前的进度写进存档。游戏已结束时清空存档。 */
    public void saveProgress() {
        Context ctx = getContext();
        if (ctx == null) {
            return;
        }
        if (over) {
            Prefs.clearState(ctx, id());
            return;
        }
        if (!ready) {
            return;
        }
        try {
            String data = dumpState();
            if (data == null || data.isEmpty()) {
                Prefs.clearState(ctx, id());
            } else {
                Prefs.setState(ctx, id(), data);
            }
        } catch (RuntimeException ignored) {
            // 存档失败不影响游戏本身
        }
    }

    /** 保存进度并回到主菜单。 */
    protected void backToMenu() {
        saveProgress();
        Context ctx = getContext();
        if (ctx instanceof Activity) {
            ((Activity) ctx).finish();
        }
    }

    /* =========================================================
     *  工具
     * ========================================================= */

    protected void addScore(int delta) {
        score += delta;
    }

    protected void finish() {
        over = true;
        paused = false;
        if (score > best) {
            best = score;
            Prefs.setBest(getContext(), id(), best);
        }
        Prefs.clearState(getContext(), id());
        invalidate();
    }

    protected void roundRect(Canvas c, float l, float t, float r, float b, float radius, int color) {
        p.setColor(color);
        tmpRect.set(l, t, r, b);
        c.drawRoundRect(tmpRect, radius, radius, p);
    }

    protected void dot(Canvas c, float x, float y, float radius, int color) {
        p.setColor(color);
        c.drawCircle(x, y, radius, p);
    }

    protected static float clamp(float v, float lo, float hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }

    protected static int clampI(int v, int lo, int hi) {
        return v < lo ? lo : (v > hi ? hi : v);
    }

    /** 给颜色套一个透明度倍数，alpha ∈ [0,1]。 */
    protected static int withAlpha(int color, float alpha) {
        int a = (int) (((color >>> 24) & 0xFF) * clamp(alpha, 0f, 1f));
        return (a << 24) | (color & 0x00FFFFFF);
    }

    /** 两个 ARGB 颜色之间线性插值，t 取 [0,1]。 */
    protected static int lerpColor(int from, int to, float t) {
        t = clamp(t, 0f, 1f);
        int a0 = (from >>> 24) & 0xFF, a1 = (to >>> 24) & 0xFF;
        int r0 = (from >>> 16) & 0xFF, r1 = (to >>> 16) & 0xFF;
        int g0 = (from >>> 8) & 0xFF, g1 = (to >>> 8) & 0xFF;
        int b0 = from & 0xFF, b1 = to & 0xFF;
        int a = (int) (a0 + (a1 - a0) * t);
        int r = (int) (r0 + (r1 - r0) * t);
        int g = (int) (g0 + (g1 - g0) * t);
        int b = (int) (b0 + (b1 - b0) * t);
        return (a << 24) | (r << 16) | (g << 8) | b;
    }
}
"}

