    Platform cp = platforms.get(currentIdx);
    float margin = charW * 0.55f;
    charX = clamp(charX, cp.x + margin, cp.x + cp.w - margin);
    charY = platformTop - charH;
    while (platforms.size() < currentIdx + AHEAD + 1) addPlatformAhead();
    camX = camTarget();
}
