{"content":"package com.watchhr;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Context;
import android.content.Intent;
import android.hardware.Sensor;
import android.hardware.SensorEvent;
import android.hardware.SensorEventListener;
import android.hardware.SensorManager;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.PowerManager;
import android.os.SystemClock;

import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;

/** 前台服务：读心率传感器 + HTTP 服务器 + UDP 局域网广播。 */
public class HrService extends Service implements SensorEventListener {

    private static final String CH_ID = "watchhr";
    private static final int HTTP_PORT = 8088;
    private static final int UDP_PORT = 45654;
    /** 两次 UDP 广播之间的最小间隔（毫秒），心率本身约 1 秒一跳。 */
    private static final long UDP_MIN_INTERVAL_MS = 1500L;

    private SensorManager sensorManager;
    private PowerManager.WakeLock wakeLock;
    private HrServer httpServer;
    private Thread serverThread;
    private DatagramSocket udpSocket;
    private long lastUdpSent = 0L;
    private final Handler handler = new Handler(Looper.getMainLooper());

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    @Override
    public void onCreate() {
        super.onCreate();
        startForegroundWithNotice();

        sensorManager = (SensorManager) getSystemService(Context.SENSOR_SERVICE);
        Sensor hr = sensorManager.getDefaultSensor(Sensor.TYPE_HEART_RATE);
        if (hr != null) {
            HrState.sensorAvailable = true;
            // UI 频率足够（心率约 1Hz），低功耗采样
            sensorManager.registerListener(this, hr, SensorManager.SENSOR_DELAY_UI);
        } else {
            HrState.sensorAvailable = false;
        }

        // 心率采样依赖 SoC 唤醒，持锁保证息屏时也持续读数
        PowerManager pm = (PowerManager) getSystemService(Context.POWER_SERVICE);
        wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "watchhr:hr");
        wakeLock.setReferenceCounted(false);
        wakeLock.acquire();

        startHttpServer();
        openUdp();

        HrState.serviceRunning = true;
        HrState.startedAt = SystemClock.elapsedRealtime();
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        return START_STICKY;
    }

    @Override
    public void onDestroy() {
        HrState.serviceRunning = false;
        if (sensorManager != null) {
            sensorManager.unregisterListener(this);
        }
        if (httpServer != null) {
            httpServer.shutdown();
        }
        if (serverThread != null) {
            serverThread.interrupt();
        }
        if (udpSocket != null && !udpSocket.isClosed()) {
            udpSocket.close();
        }
        if (wakeLock != null && wakeLock.isHeld()) {
            wakeLock.release();
        }
        super.onDestroy();
    }

    private void startForegroundWithNotice() {
        NotificationManager nm = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
        NotificationChannel ch = new NotificationChannel(
                CH_ID, "心率广播", NotificationManager.IMPORTANCE_LOW);
        nm.createNotificationChannel(ch);
        Notification n = new Notification.Builder(this, CH_ID)
                .setSmallIcon(R.drawable.ic_launcher)
                .setContentTitle("腕上心率广播")
                .setContentText("正在采集心率并对外广播")
                .setOngoing(true)
                .build();
        startForeground(1, n);
    }

    private void startHttpServer() {
        httpServer = new HrServer(HTTP_PORT);
        serverThread = new Thread(httpServer, "hr-http");
        serverThread.setDaemon(true);
        serverThread.start();
    }

    private void openUdp() {
        try {
            udpSocket = new DatagramSocket();
            udpSocket.setBroadcast(true);
            HrState.udpStatus = "广播中 :" + UDP_PORT;
        } catch (Exception e) {
            udpSocket = null;
            HrState.udpStatus = "失败: " + e.getClass().getSimpleName();
        }
    }

    // ---------------- 传感器回调 ----------------

    @Override
    public void onSensorChanged(SensorEvent event) {
        if (event.sensor.getType() != Sensor.TYPE_HEART_RATE) {
            return;
        }
        HrState.accuracy = event.accuracy;
        if (event.values != null && event.values.length > 0) {
            float v = event.values[0];
            // values[0] = BPM；-1 或 <=0 表示无有效值
            if (v > 0f) {
                HrState.bpm = v;
                HrState.bpmTs = SystemClock.elapsedRealtime();
                maybeUdpBroadcast();
            }
        }
        handler.post(uiPoke);
    }

    @Override
    public void onAccuracyChanged(Sensor sensor, int accuracy) {
        if (sensor.getType() == Sensor.TYPE_HEART_RATE) {
            HrState.accuracy = accuracy;
            handler.post(uiPoke);
        }
    }

    private final Runnable uiPoke = new Runnable() {
        @Override
        public void run() {
            HrActivityPoke.poke();
        }
    };

    /** 有新数据时通过 UDP 广播 JSON（限频）。 */
    private void maybeUdpBroadcast() {
        if (udpSocket == null || udpSocket.isClosed()) {
            return;
        }
        long now = SystemClock.elapsedRealtime();
        if (now - lastUdpSent < UDP_MIN_INTERVAL_MS) {
            return;
        }
        lastUdpSent = now;
        try {
            String json = "{\"type\":\"heart_rate\",\"bpm\":" + HrState.bpm
                    + ",\"ts\":" + System.currentTimeMillis()
                    + ",\"accuracy\":" + HrState.accuracy + "}";
            byte[] data = json.getBytes("UTF-8");
            DatagramPacket pkt = new DatagramPacket(
                    data, data.length, InetAddress.getByName("255.255.255.255"), UDP_PORT);
            udpSocket.send(pkt);
            HrState.udpSent++;
        } catch (Exception ignored) {
            // 广播失败（如 WiFi 未开）不影响采集，状态由 UI 提示
        }
    }
}
