                .setOngoing(true)
                .build();
        startForeground(1, n);
    }

    private void startHttpServer() {
        httpServer = new HrServer(HTTP_PORT);
        serverThread = new Thread(httpServer, "hr-http");
        serverThread.setDaemon(true);
        serverThread.start();
    }

    private void openUdp() {
        try {
            udpSocket = new DatagramSocket();
            udpSocket.setBroadcast(true);
            HrState.udpStatus = "广播中 :" + UDP_PORT;
        } catch (Exception e) {
            udpSocket = null;
            HrState.udpStatus = "失败: " + e.getClass().getSimpleName();
        }
    }

    // ---------------- 传感器回调 ----------------

    @Override
    public void onSensorChanged(SensorEvent event) {
        if (event.sensor.getType() != Sensor.TYPE_HEART_RATE) {
            return;
        }
        HrState.accuracy = event.accuracy;
        if (event.values != null && event.values.length > 0) {
            float v = event.values[0];
            // values[0] = BPM；-1 或 <=0 表示无有效值
            if (v > 0f) {
                HrState.bpm = v;
                HrState.bpmTs = SystemClock.elapsedRealtime();
                maybeUdpBroadcast();
            }
        }
        handler.post(uiPoke);
    }

    @Override
    public void onAccuracyChanged(Sensor sensor, int accuracy) {
        if (sensor.getType() == Sensor.TYPE_HEART_RATE) {
            HrState.accuracy = accuracy;
            handler.post(uiPoke);
        }
    }

    private final Runnable uiPoke = new Runnable() {
        @Override
        public void run() {
            HrActivityPoke.poke();
        }
    };

    /** 有新数据时通过 UDP 广播 JSON（限频）。 */
    private void maybeUdpBroadcast() {
        if (udpSocket == null || udpSocket.isClosed()) {
            return;
        }
        long now = SystemClock.elapsedRealtime();
        if (now - lastUdpSent < UDP_MIN_INTERVAL_MS) {
            return;
        }
        lastUdpSent = now;
        try {
            String json = "{\"type\":\"heart_rate\",\"bpm\":" + HrState.bpm
                    + ",\"ts\":" + System.currentTimeMillis()
                    + ",\"accuracy\":" + HrState.accuracy + "}";
            byte[] data = json.getBytes("UTF-8");
            DatagramPacket pkt = new DatagramPacket(
                    data, data.length, InetAddress.getByName("255.255.255.255"), UDP_PORT);
            udpSocket.send(pkt);
            HrState.udpSent++;
        } catch (Exception ignored) {
            // 广播失败（如 WiFi 未开）不影响采集，状态由 UI 提示
        }
    }
}

