{"content":"package com.watchhr;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

/**
 * 极简 HTTP 服务器（仅 GET），端口 8088，绑定 0.0.0.0。
 * 路由：
 *   GET /hr        -> 最新心率（纯文本，如 "72"）
 *   GET /hr.json   -> {"type":"heart_rate","bpm":72,"valid":true,"ts":...,"accuracy":3,"uptimeS":...}
 *   GET /          -> 端点说明
 * 其它一律 404。
 */
final class HrServer implements Runnable {

    private final int port;
    private volatile ServerSocket serverSocket;

    HrServer(int port) {
        this.port = port;
    }

    void shutdown() {
        try {
            if (serverSocket != null && !serverSocket.isClosed()) {
                serverSocket.close();
            }
        } catch (Exception ignored) {
        }
        HrState.serverStatus = "已停止";
    }

    @Override
    public void run() {
        try {
            serverSocket = new ServerSocket();
            serverSocket.setReuseAddress(true);
            serverSocket.bind(new InetSocketAddress(port));
            HrState.serverStatus = "HTTP :" + port + " 就绪";
            while (!serverSocket.isClosed()) {
                Socket sock = serverSocket.accept();
                try {
                    handle(sock);
                } catch (Exception ignored) {
                } finally {
                    try { sock.close(); } catch (Exception ignored) {}
                }
            }
        } catch (Exception e) {
            HrState.serverStatus = "失败: " + e.getClass().getSimpleName();
        }
    }

    private void handle(Socket sock) throws Exception {
        sock.setSoTimeout(3000);
        BufferedReader in = new BufferedReader(
                new InputStreamReader(sock.getInputStream(), StandardCharsets.US_ASCII));
        String line = in.readLine();
        if (line == null) {
            return;
        }
        // 读完请求头（忽略内容），防止客户端等响应超时
        String s;
        int guard = 0;
        while ((s = in.readLine()) != null && !s.isEmpty() && guard++ < 64) {
            // drain
        }

        String path = "/";
        String[] parts = line.split(" ");
        if (parts.length >= 2) {
            path = parts[1];
        }
        int q = path.indexOf('?');
        if (q >= 0) {
            path = path.substring(0, q);
        }

        HrState.httpHits++;

        String body;
        String mime = "text/plain; charset=utf-8";
        if ("/hr".equals(path)) {
            float bpm = HrState.bpm;
            body = bpm > 0f ? String.valueOf(Math.round(bpm)) : "-1";
        } else if ("/hr.json".equals(path)) {
            mime = "application/json; charset=utf-8";
            float bpm = HrState.bpm;
            boolean valid = bpm > 0f;
            long now = System.currentTimeMillis();
            long uptime = HrState.startedAt > 0
                    ? (android.os.SystemClock.elapsedRealtime() - HrState.startedAt) / 1000L : 0L;
            body = "{\"type\":\"heart_rate\",\"bpm\":" + (valid ? Math.round(bpm) : -1)
                    + ",\"valid\":" + valid
                    + ",\"accuracy\":" + HrState.accuracy
                    + ",\"ts\":" + now
                    + ",\"uptimeS\":" + uptime
                    + ",\"udpSent\":" + HrState.udpSent + "}";
        } else if ("/".equals(path)) {
            body = "WatchHR 心率广播\n\n"
                    + "GET /hr       最新心率(纯文本, 无效时-1)\n"
                    + "GET /hr.json  心率JSON\n"
                    + "UDP :" + 45654 + " 局域网广播(同上JSON)\n";
        } else {
            respond(sock, 404, "text/plain", "not found");
            return;
        }
        respond(sock, 200, mime, body);
    }

    private void respond(Socket sock, int code, String mime, String body) throws Exception {
        byte[] data = body.getBytes(StandardCharsets.UTF_8);
        OutputStream out = sock.getOutputStream();
        String head = "HTTP/1.0 " + code + " OK\r\n"
                + "Content-Type: " + mime + "\r\n"
                + "Content-Length: " + data.length + "\r\n"
                + "Access-Control-Allow-Origin: *\r\n"
                + "Connection: close\r\n\r\n";
        out.write(head.getBytes(StandardCharsets.US_ASCII));
        out.write(data);
        out.flush();
    }
}
