{"content":"package com.watchhr;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.MotionEvent;
import android.view.View;
import android.view.WindowManager;

import java.net.InetAddress;
import java.net.NetworkInterface;
import java.util.Enumeration;

/** 圆屏主界面：中央大字心率 + 服务状态 + 点击启停。 */
public class MainActivity extends Activity {

    private static final int REQ_BODY_SENSORS = 1;

    private HrView view;
    private final Handler handler = new Handler(Looper.getMainLooper());

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);

        view = new HrView(this);
        setContentView(view);

        HrState.uiPoke = new Runnable() {
            @Override
            public void run() {
                handler.post(new Runnable() {
                    @Override
                    public void run() {
                        view.invalidate();
                    }
                });
            }
        };

        if (checkSelfPermission(Manifest.permission.BODY_SENSORS)
                != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.BODY_SENSORS}, REQ_BODY_SENSORS);
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] results) {
        super.onRequestPermissionsResult(requestCode, permissions, results);
        if (requestCode == REQ_BODY_SENSORS) {
            view.invalidate();
        }
    }

    @Override
    protected void onDestroy() {
        HrState.uiPoke = null;
        super.onDestroy();
    }

    // ---------------- 圆屏绘制 ----------------

    private final class HrView extends View {
        private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final RectF arc = new RectF();

        HrView(android.content.Context c) {
            super(c);
            setOnClickListener(new OnClickListener() {
                @Override
                public void onClick(View v) {
                    toggleService();
                }
            });
        }

        @Override
        protected void onDraw(Canvas c) {
            int w = getWidth();
            int h = getHeight();
            float cx = w / 2f;
            float cy = h / 2f;
            float R = Math.min(w, h) / 2f;
            float safe = R * 0.72f; // 内切安全区

            c.drawColor(Color.BLACK);

            boolean granted = checkSelfPermission(Manifest.permission.BODY_SENSORS)
                    == PackageManager.PERMISSION_GRANTED;
            boolean running = HrState.serviceRunning;
            float bpm = HrState.bpm;
            boolean hasBpm = bpm > 0f;
            boolean stale = System.currentTimeMillis() - HrState.bpmTs > 30_000L;

            // 顶部标题
            p.setColor(0xFF8AB8A5);
            p.setTextSize(R * 0.075f);
            p.setTextAlign(Paint.Align.CENTER);
            p.setTypeface(Typeface.DEFAULT_BOLD);
            c.drawString("腕上心率广播", cx, cy - safe * 0.82f, p);

            // 中央大字
            p.setTypeface(Typeface.DEFAULT_BOLD);
            if (!granted) {
                p.setColor(0xFFE0B04B);
                p.setTextSize(R * 0.14f);
                c.drawText("未授权", cx, cy, p);
                p.setTextSize(R * 0.075f);
                p.setColor(0xFFBBBBBB);
                p.setTypeface(Typeface.DEFAULT);
                c.drawText("点击后请允许身体传感器权限", cx, cy + safe * 0.35f, p);
            } else if (hasBpm) {
                p.setColor(stale ? 0xFF9E9E9E : 0xFFFF5A5F);
                p.setTextSize(R * 0.42f);
                c.drawText(String.valueOf(Math.round(bpm)), cx, cy + R * 0.13f, p);
                p.setTextSize(R * 0.075f);
                p.setColor(0xFFBBBBBB);
                p.setTypeface(Typeface.DEFAULT);
                c.drawText(stale ? "BPM（数据较旧）" : "BPM", cx, cy + safe * 0.55f, p);
            } else if (!HrState.sensorAvailable) {
                p.setColor(0xFFE0B04B);
                p.setTextSize(R * 0.12f);
                c.drawText("无心率传感器", cx, cy, p);
            } else {
                p.setColor(0xFF9E9E9E);
                p.setTextSize(R * 0.13f);
                c.drawText("--", cx, cy, p);
                p.setTextSize(R * 0.07f);
                p.setTypeface(Typeface.DEFAULT);
                c.drawText(running ? "测量中…请佩戴好手表" : "服务未运行", cx, cy + safe * 0.4f, p);
            }

            // 底部状态行
            p.setTypeface(Typeface.DEFAULT);
            p.setTextSize(R * 0.058f);
            p.setColor(running ? 0xFF6FCF97 : 0xFF777777);
            String[] ips = localIps();
            String ipTxt = ips.length > 0 ? ips[0] : "无网络";
            c.drawText(running ? "● 运行中  " + ipTxt : "○ 已停止 · 点击屏幕启动",
                    cx, cy + safe * 0.80f, p);

            p.setTextSize(R * 0.052f);
            p.setColor(0xFF999999);
            c.drawText(HrState.serverStatus + " · " + HrState.udpStatus
                            + " · " + HrState.httpHits + "/" + HrState.udpSent,
                    cx, cy + safe * 0.95f, p);

            // 外圈运行指示
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(R * 0.02f);
            p.setColor(running ? 0xFF6FCF97 : 0xFF333333);
            arc.set(cx - safe * 1.08f, cy - safe * 1.08f,
                    cx + safe * 1.08f, cy + safe * 1.08f);
            c.drawArc(arc, 0f, 360f, false, p);
            p.setStyle(Paint.Style.FILL);
        }
    }

    private void toggleService() {
        if (HrState.serviceRunning) {
            stopService(new Intent(this, HrService.class));
            HrState.serverStatus = "未启动";
            HrState.udpStatus = "未启动";
        } else {
            Intent it = new Intent(this, HrService.class);
            if (Build.VERSION.SDK_INT >= 26) {
                startForegroundService(it);
            } else {
                startService(it);
            }
        }
        view.invalidate();
    }

    /** 枚举本机 IPv4（wlan0 优先），供 UI 展示访问地址。 */
    private static String[] localIps() {
        try {
            java.util.List<String> out = new java.util.ArrayList<>();
            Enumeration<NetworkInterface> nis = NetworkInterface.getNetworkInterfaces();
            while (nis.hasMoreElements()) {
                NetworkInterface ni = nis.nextElement();
                if (!ni.isUp() || ni.isLoopback()) {
                    continue;
                }
                Enumeration<InetAddress> addrs = ni.getInetAddresses();
                while (addrs.hasMoreElements()) {
                    InetAddress a = addrs.nextElement();
                    if (!a.isLoopbackAddress() && a.getAddress().length == 4) {
                        out.add(a.getHostAddress());
                    }
                }
            }
            return out.toArray(new String[0]);
        } catch (Exception e) {
            return new String[0];
        }
    }
}
