{"content": "package com.voiceclips;

import android.content.Context;
import android.content.SharedPreferences;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** 语音条目与分类。数据来自 assets/clips.json（构建时生成）。 */
public final class ClipStore {

    public static final class Clip {
        public final String file;      // assets 内文件名，如 c0012.mp3
        public final String label;     // 显示名
        public final String cat;       // 分类 key
        public final int durMs;        // 时长（毫秒），未知为 0
        public final String hash;

        Clip(String file, String label, String cat, int durMs, String hash) {
            this.file = file;
            this.label = label;
            this.cat = cat;
            this.durMs = durMs;
            this.hash = hash;
        }
    }

    public static final class Category {
        public final String key;
        public final String name;
        public final List<Clip> clips = new ArrayList<>();

        Category(String key, String name) {
            this.key = key;
            this.name = name;
        }
    }

    private static ClipStore instance;

    public final List<Category> categories = new ArrayList<>();
    public final Map<String, Category> byKey = new LinkedHashMap<>();
    public final List<Clip> all = new ArrayList<>();

    public static synchronized ClipStore get(Context ctx) {
        if (instance == null) {
            instance = new ClipStore();
            instance.load(ctx);
        }
        return instance;
    }

    private void load(Context ctx) {
        try {
            String json = readAsset(ctx, "clips.json");
            JSONArray arr = new JSONArray(json);
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                String file = o.getString("f");
                String label = o.optString("t", "");
                String cat = o.getString("c");
                String catName = o.optString("cn", cat);
                int dur = o.optInt("d", 0);
                String hash = o.optString("h", "");

                Category c = byKey.get(cat);
                if (c == null) {
                    c = new Category(cat, catName);
                    byKey.put(cat, c);
                    categories.add(c);
                }
                if (label.isEmpty()) {
                    label = file.replaceAll("\\.[a-z0-9]+$", "");
                }
                Clip clip = new Clip(file, label, cat, dur, hash);
                c.clips.add(clip);
                all.add(clip);
            }
        } catch (Exception e) {
            // 资源缺失时保持空列表，界面显示提示，不崩溃
        }
    }

    private static String readAsset(Context ctx, String name) throws Exception {
        InputStream in = ctx.getAssets().open(name);
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        int n;
        while ((n = in.read(buf)) > 0) {
            bos.write(buf, 0, n);
        }
        in.close();
        return new String(bos.toByteArray(), "UTF-8");
    }

    public int totalCount() {
        return all.size();
    }

    public Clip find(String file) {
        for (Clip c : all) {
            if (c.file.equals(file)) {
                return c;
            }
        }
        return null;
    }

    // ---------------- 收藏 ----------------

    private static SharedPreferences prefs(Context ctx) {
        return ctx.getSharedPreferences("voiceclips", Context.MODE_PRIVATE);
    }

    public static boolean isFav(Context ctx, String file) {
        return prefs(ctx).getBoolean("fav_" + file, false);
    }

    public static void toggleFav(Context ctx, String file) {
        SharedPreferences p = prefs(ctx);
        p.edit().putBoolean("fav_" + file, !p.getBoolean("fav_" + file, false)).apply();
    }

    public static String lastPlayed(Context ctx) {
        return prefs(ctx).getString("last", "");
    }

    public static void setLastPlayed(Context ctx, String file) {
        prefs(ctx).edit().putString("last", file).apply();
    }
}
