{"content": "package com.voiceclips;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import android.graphics.Typeface;
import android.media.AudioManager;
import android.media.MediaPlayer;
import android.os.Handler;
import android.os.Looper;
import android.view.MotionEvent;
import android.view.View;

import java.util.ArrayList;
import java.util.List;

/**
 * 圆屏语音包界面：分类宫格 -> 条目列表 -> 播放。
 * 单一 View 自绘，保证所有元素落在 466x466 圆内。
 */
public class VoiceView extends View {

    private static final int PANEL_BG = 0xFF11151C;
    private static final int TEXT = 0xFFF2F4F8;
    private static final int DIM = 0xFF8A94A6;
    private static final int ACCENT = 0xFF4FD1C5;
    private static final int ACCENT_2 = 0xFFFFB74D;
    private static final int[] TILE = {
            0xFF3E7BFA, 0xFFE05B4B, 0xFF7B5BE0, 0xFF2FA36B, 0xFFD9793A,
            0xFF3AA8C9, 0xFFC64A8B, 0xFF5B8C3A, 0xFF8A6C3E
    };

    private enum Screen {CATS, LIST}

    private final ClipStore store;
    private final Paint p = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint tp = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final RectF tmp = new RectF();

    private float W, H, cx, cy, R;

    private Screen screen = Screen.CATS;
    private int activeCat = -1;
    private int scroll = 0;

    private MediaPlayer player;
    private String playingFile;
    private final Handler handler = new Handler(Looper.getMainLooper());
    private final Runnable tick = new Runnable() {
        @Override
        public void run() {
            invalidate();
            if (player != null && player.isPlaying()) {
                handler.postDelayed(this, 120);
            }
        }
    };

    private float downX, downY;
    private long downT;
    private boolean moved;

    public VoiceView(Context ctx) {
        super(ctx);
        store = ClipStore.get(ctx);
        setBackgroundColor(PANEL_BG);
        tp.setTextAlign(Paint.Align.CENTER);
        p.setTextAlign(Paint.Align.CENTER);
    }

    @Override
    protected void onSizeChanged(int w, int h, int ow, int oh) {
        W = w;
        H = h;
        cx = w / 2f;
        cy = h / 2f;
        R = Math.min(w, h) / 2f;
    }

    @Override
    protected void onDetachedFromWindow() {
        handler.removeCallbacks(tick);
        releasePlayer();
        super.onDetachedFromWindow();
    }

    // ---------------- 绘制 ----------------

    @Override
    protected void onDraw(Canvas c) {
        if (R <= 0) {
            return;
        }
        if (screen == Screen.CATS) {
            drawCats(c);
        } else {
            drawList(c);
        }
    }

    private void drawCats(Canvas c) {
        tp.setColor(TEXT);
        tp.setTextSize(R * 0.115f);
        tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        c.drawText("语音包", cx, cy - R * 0.60f, tp);

        tp.setColor(DIM);
        tp.setTextSize(R * 0.072f);
        tp.setTypeface(Typeface.DEFAULT);
        c.drawText(store.totalCount() + " 条 · " + store.categories.size() + " 类", cx, cy - R * 0.44f, tp);

        int n = store.categories.size();
        if (n == 0) {
            tp.setColor(DIM);
            tp.setTextSize(R * 0.09f);
            c.drawText("没有找到语音", cx, cy, tp);
            return;
        }

        // 3 列宫格，圆内安全区
        int cols = 3;
        float gridW = R * 1.24f;
        float tile = gridW / cols;
        float gap = tile * 0.10f;
        int rows = (n + cols - 1) / cols;
        float gridH = rows * tile;
        float top = cy - gridH / 2f + R * 0.10f;

        for (int i = 0; i < n; i++) {
            int r = i / cols, col = i % cols;
            // 最后一行居中
            int inRow = Math.min(cols, n - r * cols);
            float rowW = inRow * tile;
            float left = cx - rowW / 2f + col * tile;
            float t = top + r * tile;

            tmp.set(left + gap / 2, t + gap / 2, left + tile - gap / 2, t + tile - gap / 2);
            p.setStyle(Paint.Style.FILL);
            p.setColor(TILE[i % TILE.length]);
            c.drawRoundRect(tmp, tile * 0.26f, tile * 0.26f, p);

            ClipStore.Category cat = store.categories.get(i);
            tp.setColor(0xFFFFFFFF);
            tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
            tp.setTextSize(tile * 0.30f);
            String name = cat.name;
            if (name.length() > 3) {
                name = name.substring(0, 3);
            }
            c.drawText(name, left + tile / 2, t + tile * 0.52f, tp);

            tp.setTypeface(Typeface.DEFAULT);
            tp.setTextSize(tile * 0.22f);
            tp.setColor(0xCCFFFFFF);
            c.drawText(cat.clips.size() + "", left + tile / 2, t + tile * 0.76f, tp);
        }

        // 最近播放
        String last = ClipStore.lastPlayed(getContext());
        if (!last.isEmpty()) {
            ClipStore.Clip clip = store.find(last);
            if (clip != null) {
                tp.setColor(DIM);
                tp.setTextSize(R * 0.065f);
                tp.setTypeface(Typeface.DEFAULT);
                String s = "上次：" + trim(clip.label, 10);
                c.drawText(s, cx, cy + R * 0.80f, tp);
            }
        }
    }

    private void drawList(Canvas c) {
        ClipStore.Category cat = store.categories.get(activeCat);
        List<ClipStore.Clip> list = cat.clips;

        // 顶部分类名
        tp.setColor(TEXT);
        tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
        tp.setTextSize(R * 0.10f);
        c.drawText(cat.name, cx, cy - R * 0.66f, tp);

        tp.setColor(DIM);
        tp.setTypeface(Typeface.DEFAULT);
        tp.setTextSize(R * 0.062f);
        c.drawText(list.size() + " 条 · 上下滑动翻页", cx, cy - R * 0.52f, tp);

        // 列表区：中间横向长条，适配圆屏（上下留白多，左右留白少）
        int perPage = 5;
        float rowH = R * 0.175f;
        float listTop = cy - (perPage * rowH) / 2f + R * 0.03f;
        float sideInset = R * 0.20f;

        int start = scroll * perPage;
        for (int i = 0; i < perPage; i++) {
            int idx = start + i;
            if (idx >= list.size()) {
                break;
            }
            ClipStore.Clip clip = list.get(idx);
            float t = listTop + i * rowH;
            // 圆形裁切：越靠上下两端，左右收缩越多
            float norm = Math.abs((t + rowH / 2) - cy) / (R * 0.85f);
            float inset = sideInset * norm * norm;

            tmp.set(sideInset + inset, t + rowH * 0.14f,
                    W - sideInset - inset, t + rowH * 0.86f);

            boolean isPlaying = clip.file.equals(playingFile) && player != null && player.isPlaying();
            p.setStyle(Paint.Style.FILL);
            p.setColor(isPlaying ? 0xFF1F3B3A : 0xFF1B2029);
            c.drawRoundRect(tmp, rowH * 0.30f, rowH * 0.30f, p);

            if (isPlaying) {
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(Math.max(2f, R * 0.008f));
                p.setColor(ACCENT);
                c.drawRoundRect(tmp, rowH * 0.30f, rowH * 0.30f, p);
                p.setStyle(Paint.Style.FILL);
            }

            // 序号 / 播放图标
            tp.setTextAlign(Paint.Align.LEFT);
            tp.setColor(isPlaying ? ACCENT : DIM);
            tp.setTextSize(rowH * 0.30f);
            tp.setTypeface(Typeface.create(Typeface.DEFAULT, Typeface.BOLD));
            c.drawText(isPlaying ? "▶" : String.valueOf(idx + 1),
                    tmp.left + rowH * 0.22f, tmp.centerY() + rowH * 0.12f, tp);

            // 名称
            tp.setColor(isPlaying ? ACCENT : TEXT);
            tp.setTextSize(rowH * 0.34f);
            tp.setTypeface(Typeface.DEFAULT);
            float textX = tmp.left + rowH * 0.75f;
            float maxW = tmp.width() - rowH * 1.05f;
            String label = fit(clip.label, tp, maxW);
            c.drawText(label, textX, tmp.centerY() + rowH * 0.12f, tp);

            // 收藏标记
            if (ClipStore.isFav(getContext(), clip.file)) {
                tp.setTextAlign(Paint.Align.RIGHT);
                tp.setColor(ACCENT_2);
                tp.setTextSize(rowH * 0.34f);
                c.drawText("★", tmp.right - rowH * 0.22f, tmp.centerY() + rowH * 0.12f, tp);
                tp.setTextAlign(Paint.Align.LEFT);
            }
        }
        tp.setTextAlign(Paint.Align.CENTER);

        // 页码
        int pages = (list.size() + perPage - 1) / perPage;
        if (pages > 1) {
            String pg = (scroll + 1) + "/" + pages;
            tp.setColor(DIM);
            tp.setTextSize(R * 0.06f);
            c.drawText(pg, cx - R * 0.55f, cy, tp);
            // 右侧小箭头
            tp.setTextSize(R * 0.075f);
            tp.setColor(scroll > 0 ? 0xFFB8C0CC : 0x33FFFFFF);
            c.drawText("▲", cx + R * 0.55f, cy - R * 0.10f, tp);
            tp.setColor(scroll < pages - 1 ? 0xFFB8C0CC : 0x33FFFFFF);
            c.drawText("▼", cx + R * 0.55f, cy + R * 0.14f, tp);
        }
    }

    private String fit(String s, Paint paint, float maxW) {
        if (paint.measureText(s) <= maxW) {
            return s;
        }
        String out = s;
        while (out.length() > 1 && paint.measureText(out + "…") > maxW) {
            out = out.substring(0, out.length() - 1);
        }
        return out + "…";
    }

    private static String trim(String s, int n) {
        return s.length() <= n ? s : s.substring(0, n) + "…";
    }

    // ---------------- 触摸 ----------------

    @Override
    public boolean onTouchEvent(MotionEvent e) {
        int action = e.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) {
            downX = e.getX();
            downY = e.getY();
            downT = System.currentTimeMillis();
            moved = false;
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            if (Math.abs(e.getY() - downY) > R * 0.12f) {
                moved = true;
            }
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            float dx = e.getX() - downX;
            float dy = e.getY() - downY;
            long dt = System.currentTimeMillis() - downT;
            if (Math.abs(dy) > R * 0.14f && Math.abs(dy) > Math.abs(dx)) {
                if (screen == Screen.LIST) {
                    turnPage(dy < 0 ? 1 : -1);
                }
                return true;
            }
            if (!moved && dt < 900) {
                tap(e.getX(), e.getY());
            }
            return true;
        }
        return super.onTouchEvent(e);
    }

    private void turnPage(int dir) {
        ClipStore.Category cat = store.categories.get(activeCat);
        int pages = (cat.clips.size() + 4) / 5;
        int ns = scroll + dir;
        if (ns >= 0 && ns < pages) {
            scroll = ns;
            invalidate();
        }
    }

    private void tap(float x, float y) {
        if (screen == Screen.CATS) {
            if (y < cy - R * 0.40f) {
                return; // 标题区
            }
            int n = store.categories.size();
            int cols = 3;
            float gridW = R * 1.24f;
            float tile = gridW / cols;
            int rows = (n + cols - 1) / cols;
            float gridH = rows * tile;
            float top = cy - gridH / 2f + R * 0.10f;

            for (int i = 0; i < n; i++) {
                int r = i / cols, col = i % cols;
                int inRow = Math.min(cols, n - r * cols);
                float rowW = inRow * tile;
                float left = cx - rowW / 2f + col * tile;
                float t = top + r * tile;
                if (x >= left && x <= left + tile && y >= t && y <= t + tile) {
                    activeCat = i;
                    scroll = 0;
                    screen = Screen.LIST;
                    invalidate();
                    return;
                }
            }
        } else {
            if (y < cy - R * 0.45f) {
                screen = Screen.CATS;
                invalidate();
                return;
            }
            int perPage = 5;
            float rowH = R * 0.175f;
            float listTop = cy - (perPage * rowH) / 2f + R * 0.03f;
            int start = scroll * perPage;
            for (int i = 0; i < perPage; i++) {
                int idx = start + i;
                ClipStore.Category cat = store.categories.get(activeCat);
                if (idx >= cat.clips.size()) {
                    break;
                }
                float t = listTop + i * rowH;
                if (y >= t && y <= t + rowH) {
                    playOrStop(cat.clips.get(idx));
                    return;
                }
            }
        }
    }

    // ---------------- 播放 ----------------

    private void playOrStop(ClipStore.Clip clip) {
        if (clip.file.equals(playingFile) && player != null && player.isPlaying()) {
            player.pause();
            playingFile = null;
            handler.removeCallbacks(tick);
            invalidate();
            return;
        }
        releasePlayer();
        try {
            player = new MediaPlayer();
            player.setAudioStreamType(AudioManager.STREAM_MUSIC);
            android.content.res.AssetFileDescriptor afd =
                    getContext().getAssets().openFd("clips/" + clip.file);
            player.setDataSource(afd.getFileDescriptor(), afd.getStartOffset(), afd.getLength());
            afd.close();
            player.prepare();
            player.start();
            playingFile = clip.file;
            ClipStore.setLastPlayed(getContext(), clip.file);
            handler.removeCallbacks(tick);
            handler.post(tick);
            player.setOnCompletionListener(mp -> {
                playingFile = null;
                handler.removeCallbacks(tick);
                invalidate();
            });
            invalidate();
        } catch (Exception ex) {
            releasePlayer();
            playingFile = null;
            invalidate();
        }
    }

    private void releasePlayer() {
        if (player != null) {
            try {
                player.release();
            } catch (Exception ignored) {
            }
            player = null;
        }
    }

    @Override
    public boolean performClick() {
        super.performClick();
        return true;
    }

    /** 返回键：列表 -> 分类；分类页返回 false 交给 Activity 退出。 */
    public boolean goBack() {
        if (screen == Screen.LIST) {
            screen = Screen.CATS;
            invalidate();
            return true;
        }
        return false;
    }
}
