366→                float rowW = inRow * tile;
367→                float left = cx - rowW / 2f + col * tile;
368→                float t = top + r * tile;
369→                if (x >= left && x <= left + tile && y >= t && y <= t + tile) {
370→                    activeCat = i;
371→                    scroll = 0;
372→                    screen = Screen.LIST;
373→                    invalidate();
374→                    return;
375→                }
376→            }
