404→    private void playOrStop(ClipStore.Clip clip) {
405→        if (clip.file.equals(playingFile) && player != null && player.isPlaying()) {
406→            player.pause();
407→            playingFile = null;
408→            handler.removeCallbacks(tick);
409→            invalidate();
410→            return;
411→        }
412→        releasePlayer();
413→        try {
414→            player = new MediaPlayer();
415→            player.setAudioStreamType(AudioManager.STREAM_MUSIC);
416→            android.content.res.AssetFileDescriptor afd =
417→                    getContext().getAssets().openFd("clips/" + clip.file);
418→            player.setDataSource(afd.getFileDescriptor(), afd.getStartOffset(), afd.getLength());
419→            afd.close();
420→            player.prepare();
421→            player.start();
422→            playingFile = clip.file;
423→            ClipStore.setLastPlayed(getContext(), clip.file);
424→            handler.removeCallbacks(tick);
425→            handler.post(tick);
426→            player.setOnCompletionListener(mp -> {
427→                playingFile = null;
428→                handler.removeCallbacks(tick);
429→                invalidate();
430→            });
431→            invalidate();
432→        } catch (Exception ex) {
433→            releasePlayer();
434→            playingFile = null;
435→            invalidate();
436→        }
437→    }
