import zlib, struct

def read_png(p):
    d=open(p,'rb').read()
    pos=8; w=h=None; idat=b''; plte=None; trns=None
    while pos<len(d):
        ln=struct.unpack('>I', d[pos:pos+4])[0]; typ=d[pos+4:pos+8]; data=d[pos+8:pos+8+ln]; pos+=12+ln
        if typ==b'IHDR': w,h,bd,ct=struct.unpack('>IIBB', data[:10])
        elif typ==b'IDAT': idat+=data
        elif typ==b'PLTE': plte=data
        elif typ==b'tRNS': trns=data
        elif typ==b'IEND': break
    raw=zlib.decompress(idat)
    # 只处理 8-bit RGB/RGBA
    if ct==6: ch=4
    elif ct==2: ch=3
    else: raise Exception('ct=%d'%ct)
    stride=w*ch
    out=bytearray(w*h*4)
    prev=bytearray(stride)
    pos=0
    for y in range(h):
        f=raw[pos]; pos+=1
        line=bytearray(raw[pos:pos+stride]); pos+=stride
        if f==1:
            for i in range(ch,stride): line[i]=(line[i]+line[i-ch])&255
        elif f==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&255
        elif f==3:
            for i in range(stride):
                a=line[i-ch] if i>=ch else 0
                line[i]=(line[i]+((a+prev[i])>>1))&255
        elif f==4:
            for i in range(stride):
                a=line[i-ch] if i>=ch else 0
                b=prev[i]
                c=prev[i-ch] if i>=ch else 0
                p=a+b-c; pa=abs(p-a); pb=abs(p-b); pc=abs(p-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&255
        prev=line
        for x in range(w):
            o=(y*w+x)*4
            if ch==4:
                out[o:o+4]=line[x*4:x*4+4]
            else:
                out[o:o+3]=line[x*4:x*4+3]; out[o+3]=255
    return w,h,bytes(out)

def write_png(p,w,px):
    def chunk(t,d):
        c=struct.pack('>I',len(d))+t+d
        return c+struct.pack('>I', zlib.crc32(t+d)&0xffffffff)
    raw=b''.join(b'\x00'+px[y*w*4:(y+1)*w*4] for y in range(w))
    open(p,'wb').write(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,w,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw,6))+chunk(b'IEND',b''))

w,h,px=read_png('skisafari/s4.png')
print('loaded',w,h)
# 圆形掩码：圆心(233,233) 半径233；圆外涂黑，圆边略抗锯齿
import math
for y in range(h):
    for x in range(w):
        o=(y*w+x)*4
        dist=math.hypot(x-233,y-233)
        if dist>233:
            px[o:o+4]=b'\x00\x00\x00\x00'
write_png('skisafari/s4_round.png',w,px)
print('written s4_round.png')
