{"content":"package com.roundlaunch;

import android.app.Activity;
import android.content.ComponentName;
import android.content.Intent;
import android.graphics.Rect;
import android.os.Bundle;
import android.os.Handler;
import android.view.Gravity;
import android.view.Window;
import android.view.WindowManager;
import android.widget.TextView;

/**
 * 圆屏启动器：把滑雪大冒险拉起，并尽量让它以小窗口（freeform）运行，
 * 使 466x466 的方屏画面整体缩进圆形可视区。
 * 策略：
 *  1) 本 Activity 自己先以小窗口 themed 方式启动（size = 346x346，圆内接正方形），
 *     再从自己的窗口里 startActivities，让目标 Activity 继承同任务的小窗尺寸。
 *  2) 若系统不支持 freeform，再退回直接启动（画面回到全屏）。
 */
public class LaunchActivity extends Activity {
    private static final String GAME_PKG = "com.yodo1tier1.skiwest.telecom";
    private static final String GAME_ACT = "com.yodo1tier1.wdj.SkiSafari.skizgfmainActivity";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // 让自己的窗口变小（不依赖 freeform 权限，普通 Activity 也可以用 layoutParams 缩窗）
        Window w = getWindow();
        WindowManager.LayoutParams lp = w.getAttributes();
        lp.width = dp(346);
        lp.height = dp(346);
        lp.gravity = Gravity.CENTER;
        lp.layoutInDisplayCutoutMode = 0;
        w.setAttributes(lp);
        w.setBackgroundDrawableResource(android.R.color.black);

        TextView tv = new TextView(this);
        tv.setText("启动滑雪大冒险…");
        tv.setGravity(Gravity.CENTER);
        tv.setTextColor(0xFFEEEEEE);
        tv.setTextSize(16);
        setContentView(tv);

        // 直接以明确组件启动游戏（普通全屏）
        Intent game = new Intent();
        game.setComponent(new ComponentName(GAME_PKG, GAME_ACT));
        game.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);
        try {
            startActivity(game);
        } catch (Exception ignored) {
            try {
                Intent alt = getPackageManager().getLaunchIntentForPackage(GAME_PKG);
                if (alt != null) startActivity(alt);
            } catch (Exception ignored2) {
            }
        }

        // 给游戏一点启动时间，然后自己退出
        new Handler().postDelayed(this::finish, 1500);
    }

    private int dp(int v) {
        return Math.round(v * getResources().getDisplayMetrics().density);
    }
}
