    @Override
    public boolean touch(int action, float x, float y) {
        if (action == MotionEvent.ACTION_DOWN) {
            if (mode != 0) return overlayTouch(action, x, y);
            sc.begin(y);
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            if (mode != 0) return false;
            float before = sc.off;
            sc.move(y);
            if (sc.off != before) invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            if (mode != 0) return overlayTouch(action, x, y);
            sc.end();
            if (Math.abs(y - sc.lastY()) > 12f) return true; // 拖动不算点击
            if (hitBack(x, y)) {
                if (!goUp()) act.pop();
                return true;
            }
            if (y < TOP || y > BOT) return false;
            int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
            if (idx < 0 || idx >= items.size()) return false;
            File f = items.get(idx);
            if (x > R - 56f) {
                sheetIdx = idx;
                mode = 1;
                invalidate();
                return true;
            }
            open(f);
            return true;
        }
        return false;
    }

    private boolean overlayTouch(int action, float x, float y) {
        if (action != MotionEvent.ACTION_UP) return true;
        if (mode == 1) {
            float top = 200f, h = 60f;
            int i = (int) ((y - top) / h);
            File f = items.get(sheetIdx);
            if (x < 52f || x > 414f || i < 0 || i >= SHEET.length) {
                mode = 0;
                invalidate();
                return true;
            }
            mode = 0;
            switch (SHEET[i]) {
                case "打开": open(f); break;
                case "详情": mode = 2; break;
                case "分享":
                    act.toast(Openers.share(act, f) ? "已唤起分享" : "无法分享");
                    break;
                case "删除": mode = 3; break;
            }
            invalidate();
            return true;
        }
        if (mode == 2) {
            mode = 0;
            invalidate();
            return true;
        }
        if (mode == 3) {
            File f = items.get(sheetIdx);
            if (x >= 92f && x <= 228f && y >= 268f && y <= 312f) {
                final File target = f;
                final int idx = sheetIdx;
                mode = 0;
                act.toast("删除中…");
                act.bg(() -> {
                    Fs.delete(target);
                    act.ui(() -> {
                        act.toast("已删除");
                        load();
                    });
                });
            } else {
                mode = 0;
            }
            invalidate();
            return true;
        }
        return true;
    }

    private void open(File f) {
        if (f.isDirectory()) {
            go(f);
            return;
        }
        String name = f.getName().toLowerCase();
        if (name.endsWith(".apk")) {
            Openers.install(act, f);
            return;
        }
        String cat = Fs.cat(name);
        switch (cat) {
            case "视频":
                com.watchsuite.VideoPlayerActivity.play(act, f);
                break;
            case "音频":
                com.watchsuite.MusicService.playFile(act, f);
                act.push(new MusicScreen(act));
                break;
            case "图片":
                ArrayList<File> one = new ArrayList<>();
                one.add(f);
                act.push(new ViewerScreen(act, one, 0));
                break;
            default:
                if (!Openers.view(act, f)) act.toast("没有能打开此文件的应用");
                break;
        }
    }

    @Override
    public boolean back() {
        if (mode != 0) {
            mode = 0;
            invalidate();
            return true;
        }
        if (hist.size() > 1) {
            hist.remove(hist.size() - 1);
            dir = hist.get(hist.size() - 1);
            load();
            return true;
        }
        return false;
    }
}
