package com.watchsuite.core;

public final class ThumbCache {
    private static final Map<String, Bitmap> MAP = new ConcurrentHashMap<>();
    private static final Set<String> PENDING = ConcurrentHashMap.newKeySet();
    private static final ExecutorService POOL = Executors.newFixedThreadPool(2);

    public interface Loader { Bitmap load(); }

    public static Bitmap get(String key, Loader loader, MainActivity act) {
        Bitmap b = MAP.get(key);
        if (b != null) return b;
        if (PENDING.add(key)) {
            POOL.execute(() -> {
                Bitmap r = null;
                try { r = loader.load(); } catch (Throwable ignored) {}
                if (r != null) MAP.put(key, r);
                PENDING.remove(key);
                act.ui(act::invalidate);  // careful: act captured; fine
            });
        }
        return null;
    }

    public static void clear() { MAP.clear(); }
}
