package com.watchsuite.core;

import android.content.ContentUris;
import android.content.Context;
import android.database.Cursor;
import android.net.Uri;
import android.provider.MediaStore;

import java.util.ArrayList;

/** 从 MediaStore 扫描视频 / 音频 / 图片。 */
public final class MediaScan {

    public static final class Item {
        public Uri uri;
        public String path;
        public String name;
        public long size;
        public long duration; // ms，图片为 0
    }

    private MediaScan() {}

    public static ArrayList<Item> videos(Context c) {
        return query(c, MediaStore.Video.Media.EXTERNAL_CONTENT_URI, true);
    }

    public static ArrayList<Item> audios(Context c) {
        return query(c, MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, true);
    }

    public static ArrayList<Item> images(Context c) {
        return query(c, MediaStore.Images.Media.EXTERNAL_CONTENT_URI, false);
    }

    private static ArrayList<Item> query(Context c, Uri collection, boolean withDuration) {
        ArrayList<Item> out = new ArrayList<>();
        String[] proj = new String[]{
                MediaStore.MediaColumns._ID,
                MediaStore.MediaColumns.DATA,
                MediaStore.MediaColumns.DISPLAY_NAME,
                MediaStore.MediaColumns.SIZE,
                MediaStore.MediaColumns.DURATION};
        Cursor cur = null;
        try {
            cur = c.getContentResolver().query(collection, proj, null, null,
                    MediaStore.MediaColumns.DATE_ADDED + " DESC");
            if (cur != null) {
                while (cur.moveToNext()) {
                    Item it = new Item();
                    long id = cur.getLong(0);
                    it.uri = ContentUris.withAppendedId(collection, id);
                    it.path = cur.getString(1);
                    it.name = cur.getString(2);
                    it.size = cur.getLong(3);
                    it.duration = withDuration ? cur.getLong(4) : 0;
                    if (it.path != null && it.size > 0) out.add(it);
                }
            }
        } catch (Throwable ignored) {
        } finally {
            if (cur != null) cur.close();
        }
        return out;
    }

    public static String dur(long ms) {
        long s = ms / 1000;
        return String.format(java.util.Locale.US, "%d:%02d", s / 60, s % 60);
    }
}

