{"content":"package com.watchsuite.ui;

import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.RectF;
import android.media.ThumbnailUtils;
import android.provider.MediaStore;
import android.view.MotionEvent;

import com.watchsuite.MainActivity;
import com.watchsuite.Screen;
import com.watchsuite.Scroll;
import com.watchsuite.Ui;
import com.watchsuite.core.Fs;
import com.watchsuite.core.MediaScan;
import com.watchsuite.core.ThumbCache;

import java.io.File;
import java.util.ArrayList;

/** 视频列表（参考腕凉播放器的全宽条目风格）。 */
public class VideosScreen extends Screen {

    private static final float L = 40f, R = 426f, TOP = 118f, BOT = 424f;
    private static final float ROW_H = 84f, GAP = 8f;

    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
    private final Scroll sc = new Scroll();
    private boolean loading = true;

    public VideosScreen(MainActivity a) {
        super(a);
    }

    @Override
    public void onEnter() {
        act.bg(() -> {
            ArrayList<MediaScan.Item> v = MediaScan.videos(act);
            act.ui(() -> {
                items.clear();
                items.addAll(v);
                loading = false;
                sc.max = Math.max(0, items.size() * (ROW_H + GAP) - (BOT - TOP));
                sc.clamp();
                invalidate();
            });
        });
    }

    @Override
    public void draw(Canvas c) {
        header(c, "视频", items.size() + " 个");

        c.save();
        c.clipRect(L, TOP, R, BOT);
        c.translate(0, -sc.off);
        for (int i = 0; i < items.size(); i++) {
            MediaScan.Item it = items.get(i);
            float y = TOP + i * (ROW_H + GAP);
            if (y + ROW_H < TOP + sc.off || y > BOT + sc.off) continue;
            RectF r = new RectF(L, y, R, y + ROW_H);
            Ui.round(c, r, 18f, Ui.SURFACE);

            // 缩略图
            RectF th = new RectF(r.left + 10f, r.centerY() - 32f, r.left + 118f, r.centerY() + 32f);
            Bitmap bm = ThumbCache.get(act, it.path, () ->
                    ThumbnailUtils.createVideoThumbnail(it.path, MediaStore.Video.Thumbnails.MINI_KIND));
            if (bm != null) {
                RectF src = fitCenter(bm, th);
                c.drawBitmap(bm, src, th, null);
            } else {
                Ui.round(c, th, 12f, Ui.SURFACE2);
                Ui.textC(c, "▶", th.centerX(), th.centerY() + 8f, 22f, Ui.FAINT);
            }
            // 时长角标
            if (it.duration > 0) {
                String d = MediaScan.dur(it.duration);
                RectF tag = new RectF(th.right - 52f, th.bottom - 24f, th.right - 4f, th.bottom - 4f);
                Ui.round(c, tag, 6f, 0xAA000000);
                Ui.textC(c, d, tag.centerX(), tag.centerY() + 5f, 12f, 0xFFFFFFFF);
            }

            String name = Ui.ellipsize(it.name, 18f, 240f);
            Ui.textLBold(c, name, th.right + 12f, r.top + 38f, 18f, Ui.TEXT);
            Ui.textL(c, Fs.human(it.size), th.right + 12f, r.top + 62f, 13f, Ui.FAINT);
        }
        c.restore();

        if (loading) Ui.textC(c, "扫描视频中…", 233f, 280f, 20f, Ui.FAINT);
        if (!loading && items.isEmpty()) {
            Ui.textC(c, "没有找到视频", 233f, 270f, 20f, Ui.FAINT);
            Ui.textC(c, "可先用快传把视频传到手表", 233f, 300f, 15f, 0xFF3A4757);
        }
    }

    private static RectF fitCenter(Bitmap b, RectF dst) {
        float bw = b.getWidth(), bh = b.getHeight();
        float scale = Math.max(dst.width() / bw, dst.height() / bh);
        float w = bw * scale, h = bh * scale;
        float l = dst.centerX() - w / 2f, t = dst.centerY() - h / 2f;
        return new RectF(l, t, l + w, t + h);
    }

    @Override
    public boolean touch(int action, float x, float y) {
        if (action == MotionEvent.ACTION_DOWN) {
            sc.begin(y);
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            float before = sc.off;
            sc.move(y);
            if (sc.off != before) invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            sc.end();
            if (sc.dragDist() > 12f) return true;
            if (hitBack(x, y)) {
                act.pop();
                return true;
            }
            if (y < TOP || y > BOT) return false;
            int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
            if (idx < 0 || idx >= items.size()) return false;
            MediaScan.Item it = items.get(idx);
            File f = it.path != null ? new File(it.path) : null;
            if (f != null && f.exists()) {
                com.watchsuite.VideoPlayerActivity.play(act, f);
            } else {
                act.toast("文件不存在");
            }
            return true;
        }
        return false;
    }
}
