{"content":"package com.watchsuite.ui;

import android.graphics.Canvas;
import android.graphics.RectF;
import android.os.Handler;
import android.os.Looper;
import android.view.MotionEvent;

import com.watchsuite.MainActivity;
import com.watchsuite.MusicService;
import com.watchsuite.Screen;
import com.watchsuite.Scroll;
import com.watchsuite.Ui;
import com.watchsuite.core.Fs;
import com.watchsuite.core.MediaScan;

import java.util.ArrayList;

/** 音乐：列表 + 底部正在播放卡片，支持后台播放。 */
public class MusicScreen extends Screen {

    private static final float L = 44f, R = 422f;
    private static final float ROW_H = 56f, GAP = 6f;

    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
    private final Scroll sc = new Scroll();
    private final Handler h = new Handler(Looper.getMainLooper());
    private boolean loading = true;

    private final RectF bPrev = new RectF(96f, 372f, 152f, 424f);
    private final RectF bPlay = new RectF(197f, 362f, 269f, 430f);
    private final RectF bNext = new RectF(314f, 372f, 370f, 424f);

    private final Runnable tick = new Runnable() {
        @Override
        public void run() {
            invalidate();
            h.postDelayed(this, 500);
        }
    };

    public MusicScreen(MainActivity a) {
        super(a);
    }

    @Override
    public void onEnter() {
        h.post(tick);
        if (items.isEmpty()) {
            act.bg(() -> {
                ArrayList<MediaScan.Item> v = MediaScan.audios(act);
                act.ui(() -> {
                    items.clear();
                    items.addAll(v);
                    loading = false;
                    sc.max = Math.max(0, items.size() * (ROW_H + GAP) - (listBot() - 124f));
                    sc.clamp();
                    invalidate();
                });
            });
        }
    }

    @Override
    public void onLeave() {
        h.removeCallbacks(tick);
    }

    private float listBot() {
        return hasNow() ? 340f : 420f;
    }

    private boolean hasNow() {
        return MusicService.index >= 0;
    }

    @Override
    public void draw(Canvas c) {
        header(c, "音乐", items.size() + " 首");

        c.save();
        c.clipRect(L, 124f, R, listBot());
        c.translate(0, -sc.off);
        float top = 124f;
        for (int i = 0; i < items.size(); i++) {
            MediaScan.Item it = items.get(i);
            float y = top + i * (ROW_H + GAP);
            if (y + ROW_H < top + sc.off || y > listBot() + sc.off) continue;
            boolean cur = MusicService.index == i;
            RectF r = new RectF(L, y, R, y + ROW_H);
            Ui.round(c, r, 16f, cur ? Ui.alpha(Ui.ACCENT, 0x30) : Ui.SURFACE);
            RectF g = new RectF(r.left + 12f, r.centerY() - 16f, r.left + 44f, r.centerY() + 16f);
            Ui.glyph(c, g, "♪", cur ? Ui.ACCENT : 0xFF9B7BFF);
            String name = Ui.ellipsize(it.name, 17f, 250f);
            Ui.textLBold(c, name, r.left + 56f, r.top + 25f, 17f,
                    cur ? Ui.ACCENT : Ui.TEXT);
            String sub = Fs.humanMs(it.duration) + " · " + Fs.human(it.size);
            Ui.textL(c, sub, r.left + 56f, r.top + 45f, 13f, Ui.FAINT);
