{"content":"package com.watchsuite.ui;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.RectF;
import android.view.MotionEvent;

import com.watchsuite.MainActivity;
import com.watchsuite.Screen;
import com.watchsuite.Ui;

import java.io.File;
import java.util.ArrayList;

/** 图片全屏查看：左右分区点击翻页。 */
public class ViewerScreen extends Screen {

    private final ArrayList<File> files;
    private int index;
    private Bitmap cur;
    private String curPath;

    public ViewerScreen(MainActivity a, ArrayList<File> files, int start) {
        super(a);
        this.files = files;
        this.index = start;
    }

    private void ensureBitmap() {
        if (index < 0 || index >= files.size()) {
            cur = null;
            return;
        }
        String p = files.get(index).getAbsolutePath();
        if (p.equals(curPath) && cur != null) return;
        curPath = p;
        cur = null;
        final String pp = p;
        act.bg(() -> {
            Bitmap b = decode(pp);
            act.ui(() -> {
                cur = b;
                invalidate();
            });
        });
    }

    private static Bitmap decode(String path) {
        try {
            BitmapFactory.Options o = new BitmapFactory.Options();
            o.inJustDecodeBounds = true;
            BitmapFactory.decodeFile(path, o);
            int sample = 1;
            while (o.outWidth / sample > 900 || o.outHeight / sample > 900) sample *= 2;
            BitmapFactory.Options o2 = new BitmapFactory.Options();
            o2.inSampleSize = sample;
            return BitmapFactory.decodeFile(path, o2);
        } catch (Throwable t) {
            return null;
        }
    }

    @Override
    public void draw(Canvas c) {
        ensureBitmap();
        c.drawColor(0xFF05070A);

        Ui.circle(c, 70f, 66f, 24f, 0x66000000);
        Ui.textC(c, "‹", 70f, 76f, 32f, 0xFFFFFFFF);
        Ui.textC(c, (index + 1) + " / " + files.size(), 233f, 74f, 16f, 0xFFB9C6D2);

        if (cur != null) {
            RectF dst = fit(cur, 380f);
            c.drawBitmap(cur, null, dst, null);
        } else {
            Ui.textC(c, "加载中…", 233f, 240f, 20f, Ui.FAINT);
        }
    }

    private static RectF fit(Bitmap b, float box) {
        float bw = b.getWidth(), bh = b.getHeight();
        float s = Math.min(box / bw, box / bh);
        float w = bw * s, h = bh * s;
        return new RectF(233f - w / 2f, 233f - h / 2f, 233f + w / 2f, 233f + h / 2f);
    }

    @Override
    public boolean touch(int action, float x, float y) {
        if (action != MotionEvent.ACTION_UP) return false;
        if (hitBack(x, y)) {
            act.pop();
            return true;
        }
        if (x > 320f) {
            if (index < files.size() - 1) index++;
        } else if (x < 146f) {
            if (index > 0) index--;
        }
        curPath = null;
        invalidate();
        return true;
    }

    @Override
    public boolean back() {
        act.pop();
        return true;
    }
}
