{"content":"package com.watchsuite.ui;

import android.graphics.Canvas;
import android.graphics.RectF;
import android.view.MotionEvent;

import com.watchsuite.MainActivity;
import com.watchsuite.Screen;
import com.watchsuite.Scroll;
import com.watchsuite.Ui;
import com.watchsuite.core.Fs;

import java.io.File;
import java.util.ArrayList;

/** 空间清理：分类扫描垃圾文件，勾选后一键清理（OPPO 风格）。 */
public class CleanScreen extends Screen {

    private static class Cat {
        String name;
        String desc;
        long size;
        int count;
        boolean checked = true;
        boolean info;          // 仅展示，不可清理
        ArrayList<File> files = new ArrayList<>();

        Cat(String n, String d) {
            name = n;
            desc = d;
        }
    }

    private static final float L = 52f, R = 414f, TOP = 200f, BOT = 420f;
    private static final float ROW_H = 46f, GAP = 5f;

    private final ArrayList<Cat> cats = new ArrayList<>();
    private final Scroll sc = new Scroll();
    private boolean scanning = false;
    private int confirmMode = 0; // 0 无 1 确认

    private final RectF btnClean = new RectF(262f, 130f, 372f, 184f);

    public CleanScreen(MainActivity a) {
        super(a);
    }

    @Override
    public void onEnter() {
        scan();
    }

    private void scan() {
        scanning = true;
        cats.clear();
        sc.reset();
        invalidate();
        act.bg(() -> {
            ArrayList<Cat> out = new ArrayList<>();

            Cat cache = new Cat("应用缓存", "各应用产生的临时文件");
            File dataDir = new File(Fs.ROOT, "Android/data");
            File[] apps = dataDir.listFiles();
            if (apps != null) {
                for (File app : apps) {
                    for (String cd : new String[]{"cache", "code_cache"}) {
                        File cd1 = new File(app, cd);
                        collect(cd1, cache.files, 0);
                    }
                }
            }
            out.add(cache);

            Cat thumb = new Cat("缩略图缓存", "DCIM/.thumbnails");
            collect(new File(Fs.ROOT, "DCIM/.thumbnails"), thumb.files, 0);
            out.add(thumb);

            Cat logs = new Cat("日志文件", "存储里的 *.log");
            collectByExt(Fs.root(), "log", logs.files, 0, 6);
            out.add(logs);

            Cat apk = new Cat("安装包", "Download 里的 *.apk");
            collectByExt(new File(Fs.ROOT, "Download"), "apk", apk.files, 0, 5);
            out.add(apk);

            Cat big = new Cat("大文件", "超过 200MB，请自行确认");
            big.info = true;
            big.checked = false;
            try {
                for (File f : Fs.recent(Fs.root(), 400)) {
                    if (f.length() >= 200L * 1024 * 1024) big.files.add(f);
                }
            } catch (Throwable ignored) {
            }
            out.add(big);

            Cat empty = new Cat("空文件夹", "不占用空间，可顺手清掉");
            empty.checked = false;
            collectEmpty(Fs.root(), empty.files, 0, 6);
            out.add(empty);

            for (Cat ct : out) {
                ct.count = ct.files.size();
                for (File f : ct.files) ct.size += f.length();
            }

            act.ui(() -> {
                cats.clear();
                cats.addAll(out);
                scanning = false;
                sc.max = Math.max(0, cats.size() * (ROW_H + GAP) - (BOT - TOP));
                sc.clamp();
                invalidate();
            });
        });
    }

    private static void collect(File dir, ArrayList<File> out, int depth) {
        if (depth > 8) return;
        File[] kids = dir.listFiles();
        if (kids == null) return;
        for (File k : kids) {
            if (k.isDirectory()) collect(k, out, depth + 1);
            else out.add(k);
        }
    }

    private static void collectByExt(File dir, String ext, ArrayList<File> out,
                                     int depth, int maxDepth) {
        if (dir == null || depth > maxDepth) return;
        File[] kids = dir.listFiles();
        if (kids == null) return;
        for (File k : kids) {
            if (k.isDirectory()) {
                if (k.getName().startsWith(".")) continue;
                collectByExt(k, ext, out, depth + 1, maxDepth);
            } else if (Fs.ext(k.getName()).equals(ext)) {
                out.add(k);
            }
        }
    }

    private static void collectEmpty(File dir, ArrayList<File> out, int depth, int maxDepth) {
        if (dir == null || depth > maxDepth || !dir.isDirectory()) return;
        String n = dir.getName();
        if (n.equals("data") || n.equals("obb")) {
            File p = dir.getParentFile();
            if (p != null && "Android".equals(p.getName())) return;
        }
        File[] kids = dir.listFiles();
        if (kids == null || kids.length == 0) {
            out.add(dir);
            return;
        }
        for (File k : kids) collectEmpty(k, out, depth + 1, maxDepth);
    }

    private long checkedSize() {
        long s = 0;
        for (Cat ct : cats) if (ct.checked && !ct.info) s += ct.size;
        return s;
    }

    private int checkedCount() {
        int n = 0;
        for (Cat ct : cats) if (ct.checked && !ct.info) n += ct.count;
        return n;
    }

    @Override
    public void draw(Canvas c) {
        header(c, "空间清理", scanning ? "扫描中…" : null);

        // 汇总卡片
        Ui.round(c, 60f, 124f, 406f, 190f, 22f, Ui.SURFACE);
        Ui.textL(c, "可清理", 86f, 154f, 15f, Ui.DIM);
        Ui.textLBold(c, scanning ? "…" : Fs.human(checkedSize()), 86f, 182f, 26f, Ui.OK);
        Ui.textL(c, "已选 " + checkedCount() + " 项", 86f, 176f, 0f, 0); // 占位避免重叠
        if (!scanning) {
            Ui.round(c, btnClean, 27f, Ui.OK);
            Ui.textC(c, "清理", btnClean.centerX(), btnClean.centerY() + 8f, 20f, 0xFF06281A);
        }

        c.save();
        c.clipRect(L, TOP, R, BOT);
        c.translate(0, -sc.off);
        for (int i = 0; i < cats.size(); i++) {
            Cat ct = cats.get(i);
            float y = TOP + i * (ROW_H + GAP);
            if (y + ROW_H < TOP + sc.off || y > BOT + sc.off) continue;
            Ui.round(c, L, y, R, y + ROW_H, 14f, Ui.SURFACE);
            // 勾选圈
            float cx = L + 26f;
            if (ct.info) {
                Ui.circleStroke(c, cx, y + ROW_H / 2f, 11f, 2.5f, Ui.FAINT);
            } else if (ct.checked) {
                Ui.circle(c, cx, y + ROW_H / 2f, 11f, Ui.OK);
                Ui.textC(c, "✓", cx, y + ROW_H / 2f + 5f, 14f, 0xFF06281A);
            } else {
                Ui.circleStroke(c, cx, y + ROW_H / 2f, 11f, 2.5f, Ui.FAINT);
            }
            Ui.textLBold(c, ct.name, L + 48f, y + 20f, 16f, ct.info ? Ui.DIM : Ui.TEXT);
            Ui.textL(c, ct.desc, L + 48f, y + 38f, 12f, Ui.FAINT);
            String right = ct.count == 0 ? "—" : ct.count + " 项 · " + Fs.human(ct.size);
            Ui.textR(c, right, R - 14f, y + 28f, 13f, ct.info ? Ui.FAINT : Ui.DIM);
        }
        c.restore();

        if (scanning) Ui.textC(c, "正在扫描存储…", 233f, 300f, 18f, Ui.FAINT);

        if (confirmMode == 1) {
            Ui.fill(c, new RectF(0, 0, W, H), 0xB0000000);
            Ui.round(c, 62f, 180f, 404f, 320f, 22f, Ui.SURFACE2);
            Ui.textC(c, "确认清理所选内容？", 233f, 226f, 20f, Ui.TEXT);
            Ui.textC(c, "将删除 " + Fs.human(checkedSize()), 233f, 254f, 15f, Ui.WARN);
            Ui.round(c, 92f, 280f, 228f, 324f, 22f, Ui.DANGER);
            Ui.textC(c, "清理", 160f, 309f, 19f, 0xFFFFFFFF);
            Ui.round(c, 238f, 280f, 374f, 324f, 22f, Ui.SURFACE);
            Ui.textC(c, "取消", 306f, 309f, 19f, Ui.TEXT);
        }
    }

    @Override
    public boolean touch(int action, float x, float y) {
        if (action == MotionEvent.ACTION_DOWN) {
            if (confirmMode != 0) return true;
            sc.begin(y);
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            if (confirmMode != 0) return false;
            float before = sc.off;
            sc.move(y);
            if (sc.off != before) invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            if (confirmMode == 1) {
                if (x >= 92f && x <= 228f && y >= 280f && y <= 324f) {
                    confirmMode = 0;
                    doClean();
                } else {
                    confirmMode = 0;
                }
                invalidate();
                return true;
            }
            sc.end();
            if (sc.dragDist() > 12f) return true;
            if (hitBack(x, y)) {
                act.pop();
                return true;
            }
            if (btnClean.contains(x, y) && !scanning && checkedCount() > 0) {
                confirmMode = 1;
                invalidate();
                return true;
            }
            if (y >= TOP && y <= BOT) {
                int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
                if (idx >= 0 && idx < cats.size()) {
                    Cat ct = cats.get(idx);
                    if (!ct.info) {
                        ct.checked = !ct.checked;
                        invalidate();
                    }
                }
            }
            return true;
        }
        return false;
    }

    private void doClean() {
        ArrayList<File> doomed = new ArrayList<>();
        for (Cat ct : cats) {
            if (ct.checked && !ct.info) doomed.addAll(ct.files);
        }
        if (doomed.isEmpty()) return;
        final long before = checkedSize();
        act.toast("清理中…");
        act.bg(() -> {
            int ok = 0;
            for (File f : doomed) {
                if (Fs.delete(f)) ok++;
            }
            final int n = ok;
            act.ui(() -> {
                act.toast("已清理 " + n + " 项 · " + Fs.human(before));
                scan();
            });
        });
    }

    @Override
    public boolean back() {
        if (confirmMode != 0) {
            confirmMode = 0;
            invalidate();
            return true;
        }
        return false;
    }
}
