import java.io.File;
import java.util.ArrayList;
import java.util.Locale;

/** 存储分析：总览环形图 + 分类占比 + 大文件排行。 */
public class StorageScreen extends Screen {

    private static final float LIST_TOP = 258f, LIST_BOT = 422f;

    private final Scroll sc = new Scroll();
    private Fs.Stats stats;
    private long total = 0, avail = 0;
    private boolean scanning = true;
    private int visited = 0;

    public StorageScreen(MainActivity a) {
        super(a);
    }

    @Override
    public void onEnter() {
        scanning = true;
        act.bg(() -> {
            long[] s = Fs.space();
            total = s[0];
            avail = s[1];
            Fs.Stats st = Fs.scan(Fs.root(), v -> {
                visited = v;
                act.ui(this::invalidate);
                return true;
            });
            act.ui(() -> {
                stats = st;
                scanning = false;
                long used = stats.total;
                sc.max = Math.max(0, contentH() - (LIST_BOT - LIST_TOP));
                sc.clamp();
                invalidate();
            });
        });
    }

    private int catCount() {
        return Fs.CATS.length;
    }

    private float contentH() {
        return catCount() * 38f + 26f + 5 * 46f;
    }

    @Override
    public void draw(Canvas c) {
        header(c, "存储分析", null);

        float ratio = total > 0 && stats != null
                ? (float) Math.min(1.0, (double) stats.total / total) : 0f;
        Ui.ring(c, 233f, 176f, 62f, 14f, ratio, Ui.ACCENT, Ui.SURFACE2);
        Ui.textC(c, scanning ? "…" : Math.round(ratio * 100) + "%", 233f, 186f, 26f, Ui.TEXT);
        Ui.textC(c, scanning ? "扫描中 " + visited + " 文件"
                        : "已用 " + Fs.human(stats.total) + " · 剩 " + Fs.human(avail),
                233f, 236f, 14f, Ui.DIM);

        c.save();
        c.clipRect(56f, LIST_TOP, 410f, LIST_BOT);
        c.translate(0, -sc.off);

        // 分类占比
        long maxCat = 1;
        if (stats != null) for (long v : stats.byCat) maxCat = Math.max(maxCat, v);
        for (int i = 0; i < catCount(); i++) {
            float y = LIST_TOP + i * 38f;
            if (y + 38f < LIST_TOP + sc.off || y > LIST_BOT + sc.off) continue;
            long v = stats != null ? stats.byCat[i] : 0;
            int col = Fs.catColor(Fs.CATS[i]);
            Ui.circle(c, 70f, y + 13f, 5f, col);
            Ui.textLBold(c, Fs.CATS[i], 86f, y + 19f, 16f, Ui.TEXT);
            Ui.textR(c, Fs.human(v), 410f, y + 19f, 15f, Ui.DIM);
            RectF bar = new RectF(86f, y + 26f, 410f, y + 31f);
            Ui.bar(c, bar, v / (float) maxCat, col, Ui.SURFACE);
        }

        // 大文件排行
        float y0 = LIST_TOP + catCount() * 38f + 12f;
        Ui.textL(c, "大文件 TOP 5", 86f, y0, 15f, Ui.FAINT);
        if (stats != null) {
            ArrayList<File> top = topFiles(Fs.root(), 5);
            for (int i = 0; i < top.size(); i++) {
                File f = top.get(i);
                float y = y0 + 14f + i * 46f;
                Ui.round(c, 56f, y, 410f, y + 42f, 12f, Ui.SURFACE);
                Ui.textC(c, String.valueOf(i + 1), 76f, y + 27f, 16f, Ui.ACCENT);
                Ui.textLBold(c, Ui.ellipsize(f.getName(), 15f, 250f), 92f, y + 20f, 15f, Ui.TEXT);
                String sub = Fs.human(f.length()) + " · "
                        + f.getParent().replace(Fs.ROOT, "");
                Ui.textL(c, Ui.ellipsize(sub, 12f, 300f), 92f, y + 36f, 12f, Ui.FAINT);
            }
        }
        c.restore();
    }

    private static ArrayList<File> topFiles(File root, int n) {
        ArrayList<File> all = Fs.recent(root, 600);
        all.sort((a, b) -> Long.compare(b.length(), a.length()));
        while (all.size() > n) all.remove(all.size() - 1);
        return all;
    }

    @Override
    public boolean touch(int action, float x, float y) {
        if (action == MotionEvent.ACTION_DOWN) {
            sc.begin(y);
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            float before = sc.off;
            sc.move(y);
            if (sc.off != before) invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            sc.end();
            if (sc.dragDist() > 12f) return true;
            if (hitBack(x, y)) {
                act.pop();
                return true;
            }
            return true;
        }
        return false;
    }
}
