 19→import java.util.concurrent.Executors;
 20→
 21→public class MainActivity extends Activity {
 22→
 23→    public static MainActivity I;
 24→
 25→    public ShellView shell;
 26→
 27→    private final ExecutorService pool = Executors.newFixedThreadPool(3);
 28→    private boolean askedPerm = false;
 29→
 30→    @Override
 31→    protected void onCreate(Bundle b) {
 32→        super.onCreate(b);
 33→        I = this;
 34→        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
 35→        shell = new ShellView(this);
 36→        setContentView(shell);
 37→        shell.push(new HomeScreen(this), false);
 38→        hideSystemUi();
 39→    }
 40→
 41→    private void hideSystemUi() {
 42→        View d = getWindow().getDecorView();
 43→        d.setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE
 44→                | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
 45→                | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
 46→                | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
 47→                | View.SYSTEM_UI_FLAG_FULLSCREEN
 48→                | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);
 49→    }
 50→
 51→    @Override
 52→    protected void onResume() {
 53→        super.onResume();
 54→        hideSystemUi();
 55→        if (!Perm.has(this) && !askedPerm) {
 56→            askedPerm = true;
 57→            shell.push(new PermScreen(this), true);
 58→        }
 59→    }
 60→
 61→    public void bg(Runnable r) {
 62→        pool.execute(r);
 63→    }
 64→
 65→    public void ui(Runnable r) {
 66→        runOnUiThread(r);
 67→    }
 68→
 69→    public void push(Screen s) {
 70→        shell.push(s, true);
 71→    }
 72→
 73→    public void pop() {
 74→        shell.popTop();
 75→    }
 76→
 77→    public void toast(String s) {
 78→        shell.toast(s);
 79→    }
 80→
 81→    @Override
 82→    public void onBackPressed() {
 83→        if (!shell.popTop()) super.onBackPressed();
 84→    }
 85→
 86→    /** 页面栈 + 触摸分发 + 轻提示。 */
 87→    public static class ShellView extends View {
 88→
 89→        private final List<Screen> stack = new ArrayList<>();
 90→        private final Handler h = new Handler(Looper.getMainLooper());
 91→
 92→        private String toastMsg;
 93→        private long toastAt;
 94→
 95→        private float downX, downY;
 96→        private boolean edgeSwipe;
 97→
 98→        public ShellView(Context c) {
 99→            super(c);
100→            setBackgroundColor(Ui.BG);
101→        }
102→
103→        public void push(Screen s, boolean anim) {
104→            stack.add(s);
105→            s.onEnter();
106→            invalidate();
107→        }
108→
109→        public boolean popTop() {
110→            if (stack.size() <= 1) {
111→                if (!stack.isEmpty() && stack.get(0).back()) {
112→                    invalidate();
113→                    return true;
114→                }
115→                return false;
116→            }
117→            Screen s = stack.remove(stack.size() - 1);
118→            s.onLeave();
119→            invalidate();
120→            return true;
121→        }
122→
123→        public Screen top() {
124→            return stack.isEmpty() ? null : stack.get(stack.size() - 1);
125→        }
126→
127→        public void toast(String msg) {
128→            toastMsg = msg;
129→            toastAt = System.currentTimeMillis();
130→            invalidate();
131→            h.postDelayed(this::invalidate, 1900);
132→        }
133→
134→        @Override
135→        protected void onDraw(android.graphics.Canvas c) {
136→            super.onDraw(c);
137→            Screen s = top();
138→            if (s != null) s.draw(c);
139→
140→            if (toastMsg != null) {
141→                long dt = System.currentTimeMillis() - toastAt;
142→                if (dt < 1900) {
143→                    float a = dt < 1600 ? 1f : (1900 - dt) / 300f;
144→                    int col = ((int) (a * 235) << 24) | 0x0A0E13;
145→                    float w = Ui.measure(toastMsg, 18f) + 44f;
146→                    if (w > 400f) w = 400f;
147→                    float l = 233f - w / 2f, t = 372f, r = 233f + w / 2f, b = t + 46f;
148→                    Ui.round(c, l, t, r, b, 23f, col);
149→                    Ui.textC(c, Ui.ellipsize(toastMsg, 18f, w - 24f), 233f, t + 30f, 18f, 0xFFEAF1F8);
150→                } else {
151→                    toastMsg = null;
152→                }
153→            }
154→        }
155→
156→        @Override
157→        public boolean onTouchEvent(MotionEvent e) {
158→            Screen s = top();
159→            if (s == null) return true;
160→            float x = e.getX(), y = e.getY();
161→            switch (e.getActionMasked()) {
162→                case MotionEvent.ACTION_DOWN:
163→                    downX = x;
164→                    downY = y;
165→                    edgeSwipe = x < 62f;
166→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_DOWN, x, y);
167→                    return true;
168→                case MotionEvent.ACTION_MOVE:
169→                    if (edgeSwipe) {
170→                        if (x - downX > 60f) invalidate();
171→                    } else {
172→                        s.touch(MotionEvent.ACTION_MOVE, x, y);
173→                    }
174→                    return true;
175→                case MotionEvent.ACTION_UP:
176→                    if (edgeSwipe) {
177→                        if (x - downX > 90f && Math.abs(y - downY) < 80f) {
178→                            popTop();
179→                        } else if (Math.abs(x - downX) < 20f && Math.abs(y - downY) < 20f) {
180→                            s.touch(MotionEvent.ACTION_UP, x, y);
181→                        }
182→                    } else {
183→                        s.touch(MotionEvent.ACTION_UP, x, y);
184→                    }
185→                    return true;
186→                case MotionEvent.ACTION_CANCEL:
187→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_CANCEL, x, y);
188→                    return true;
189→            }
190→            return true;
191→        }
192→    }
193→}
