  9→import com.watchsuite.MainActivity;
 10→import com.watchsuite.Screen;
 11→import com.watchsuite.Ui;
 12→
 13→import java.io.File;
 14→import java.util.ArrayList;
 15→
 16→/** 图片全屏查看：左右分区点击翻页。 */
 17→public class ViewerScreen extends Screen {
 18→
 19→    private final ArrayList<File> files;
 20→    private int index;
 21→    private Bitmap cur;
 22→    private String curPath;
 23→
 24→    public ViewerScreen(MainActivity a, ArrayList<File> files, int start) {
 25→        super(a);
 26→        this.files = files;
 27→        this.index = start;
 28→    }
 29→
 30→    private void ensureBitmap() {
 31→        if (index < 0 || index >= files.size()) {
 32→            cur = null;
 33→            return;
 34→        }
 35→        String p = files.get(index).getAbsolutePath();
 36→        if (p.equals(curPath) && cur != null) return;
 37→        curPath = p;
 38→        cur = null;
 39→        final String pp = p;
 40→        act.bg(() -> {
 41→            Bitmap b = decode(pp);
 42→            act.ui(() -> {
 43→                cur = b;
 44→                invalidate();
 45→            });
 46→        });
 47→    }
 48→
 49→    private static Bitmap decode(String path) {
 50→        try {
 51→            BitmapFactory.Options o = new BitmapFactory.Options();
 52→            o.inJustDecodeBounds = true;
 53→            BitmapFactory.decodeFile(path, o);
 54→            int sample = 1;
 55→            while (o.outWidth / sample > 900 || o.outHeight / sample > 900) sample *= 2;
 56→            BitmapFactory.Options o2 = new BitmapFactory.Options();
 57→            o2.inSampleSize = sample;
 58→            return BitmapFactory.decodeFile(path, o2);
 59→        } catch (Throwable t) {
 60→            return null;
 61→        }
 62→    }
 63→
 64→    @Override
 65→    public void draw(Canvas c) {
 66→        ensureBitmap();
 67→        c.drawColor(0xFF05070A);
 68→
 69→        Ui.circle(c, 70f, 66f, 24f, 0x66000000);
 70→        Ui.textC(c, "‹", 70f, 76f, 32f, 0xFFFFFFFF);
 71→        Ui.textC(c, (index + 1) + " / " + files.size(), 233f, 74f, 16f, 0xFFB9C6D2);
 72→
 73→        if (cur != null) {
 74→            Ui.bitmap(c, cur, fit(cur, 380f));
 75→        } else {
 76→            Ui.textC(c, "加载中…", 233f, 240f, 20f, Ui.FAINT);
 77→        }
 78→    }
 79→
 80→    private static RectF fit(Bitmap b, float box) {
 81→        float bw = b.getWidth(), bh = b.getHeight();
 82→        float s = Math.min(box / bw, box / bh);
 83→        float w = bw * s, h = bh * s;
 84→        return new RectF(233f - w / 2f, 233f - h / 2f, 233f + w / 2f, 233f + h / 2f);
 85→    }
 86→
 87→    @Override
 88→    public boolean touch(int action, float x, float y) {
 89→        if (action != MotionEvent.ACTION_UP) return false;
 90→        if (hitBack(x, y)) {
 91→            act.pop();
 92→            return true;
 93→        }
 94→        if (x > 320f) {
 95→            if (index < files.size() - 1) index++;
 96→        } else if (x < 146f) {
 97→            if (index > 0) index--;
 98→        }
 99→        curPath = null;
100→        invalidate();
101→        return true;
102→    }
103→
104→    @Override
105→    public boolean back() {
106→        act.pop();
107→        return true;
108→    }
109→}
