 27→/** 视频播放页：黑底、比例适配、可隐藏控制层。 */
 28→public class VideoPlayerActivity extends Activity
 29→        implements SurfaceHolder.Callback, MediaPlayer.OnPreparedListener,
 30→        MediaPlayer.OnCompletionListener, MediaPlayer.OnErrorListener,
 31→        MediaPlayer.OnVideoSizeChangedListener {
 32→
 33→    private static final float W = 466f, H = 466f;
 34→
 35→    public static void play(Context c, File f) {
 36→        Intent i = new Intent(c, VideoPlayerActivity.class);
 37→        i.putExtra("path", f.getAbsolutePath());
 38→        c.startActivity(i);
 39→    }
 40→
 41→    private SurfaceView surface;
 42→    private Overlay overlay;
 43→    private MediaPlayer mp;
 44→    private String path;
 45→    private String title = "视频";
 46→    private boolean started = false;
 47→    private boolean prepared = false;
 48→    private final Handler h = new Handler(Looper.getMainLooper());
 49→    private final Runnable hider = () -> overlay.showUi(false);
 50→    private final Runnable ticker = new Runnable() {
 51→        @Override
 52→        public void run() {
 53→            overlay.invalidate();
 54→            h.postDelayed(this, 400);
 55→        }
 56→    };
 57→
 58→    @Override
 59→    protected void onCreate(Bundle b) {
 60→        super.onCreate(b);
 61→        path = getIntent().getStringExtra("path");
 62→        if (path != null) title = new File(path).getName();
 63→        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
 64→
 65→        FrameLayout root = new FrameLayout(this);
 66→        root.setBackgroundColor(0xFF000000);
 67→
 68→        surface = new SurfaceView(this);
 69→        FrameLayout.LayoutParams sp = new FrameLayout.LayoutParams(
 70→                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);
 71→        sp.gravity = Gravity.CENTER;
 72→        root.addView(surface, sp);
 73→
 74→        overlay = new Overlay(this);
 75→        root.addView(overlay, new FrameLayout.LayoutParams(
 76→                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
 77→
 78→        setContentView(root);
 79→        surface.getHolder().addCallback(this);
 80→        hideSystemUi();
 81→        wakeControls();
 82→    }
 83→
 84→    private void hideSystemUi() {
 85→        getWindow().getDecorView().setSystemUiVisibility(
 86→                android.view.View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
 87→                        | android.view.View.SYSTEM_UI_FLAG_FULLSCREEN
 88→                        | android.view.View.SYSTEM_UI_FLAG_HIDE_NAVIGATION);
 89→    }
 90→
 91→    private void wakeControls() {
 92→        overlay.showUi(true);
 93→        h.removeCallbacks(hider);
 94→        h.postDelayed(hider, 3500);
 95→    }
 96→
 97→    private void setupPlayer(SurfaceHolder holder) {
 98→        try {
 99→            mp = new MediaPlayer();
100→            mp.setDataSource(path);
101→            mp.setDisplay(holder);
102→            mp.setAudioStreamType(AudioManager.STREAM_MUSIC);
103→            mp.setOnPreparedListener(this);
104→            mp.setOnCompletionListener(this);
105→            mp.setOnErrorListener(this);
106→            mp.setOnVideoSizeChangedListener(this);
107→            mp.prepareAsync();
108→        } catch (Throwable t) {
109→            Toast.makeText(this, "无法播放该视频", Toast.LENGTH_SHORT).show();
110→            finish();
111→        }
112→    }
113→
114→    @Override
115→    public void surfaceCreated(SurfaceHolder holder) {
116→        if (!started) {
117→            started = true;
118→            setupPlayer(holder);
119→        } else if (mp != null) {
120→            mp.setDisplay(holder);
121→        }
122→    }
123→
124→    @Override
125→    public void surfaceChanged(SurfaceHolder holder, int f, int w, int hgt) {
126→    }
127→
128→    @Override
129→    public void surfaceDestroyed(SurfaceHolder holder) {
130→        if (mp != null) mp.setDisplay(null);
131→    }
132→
133→    @Override
134→    public void onPrepared(MediaPlayer m) {
135→        prepared = true;
136→        m.start();
137→        h.post(ticker);
138→    }
139→
140→    @Override
141→    public void onCompletion(MediaPlayer m) {
142→        finish();
143→    }
144→
145→    @Override
146→    public boolean onError(MediaPlayer m, int what, int extra) {
147→        Toast.makeText(this, "播放出错", Toast.LENGTH_SHORT).show();
148→        finish();
149→        return true;
150→    }
151→
152→    @Override
153→    public void onVideoSizeChanged(MediaPlayer m, int w, int hgt) {
154→        if (w <= 0 || hgt <= 0) return;
155→        float scale = Math.min(W / w, H / hgt);
156→        FrameLayout.LayoutParams p = (FrameLayout.LayoutParams) surface.getLayoutParams();
157→        p.width = Math.round(w * scale);
