177→    @Override
178→    protected void onDestroy() {
179→        super.onDestroy();
180→        h.removeCallbacksAndMessages(null);
181→        if (mp != null) {
182→            try {
183→                mp.stop();
184→            } catch (Throwable ignored) {
185→            }
186→            mp.release();
187→            mp = null;
188→        }
189→    }
190→
191→    @Override
192→    public void onBackPressed() {
193→        finish();
194→    }
