196→    /** 控制层：标题 / 关闭 / 播放暂停 / 进度条。 */
197→    private class Overlay extends android.view.View {
198→
199→        private boolean ui = true;
200→
201→        public Overlay(Context c) {
202→            super(c);
203→        }
204→
205→        void showUi(boolean s) {
206→            ui = s;
207→            invalidate();
208→        }
