211→        protected void onDraw(Canvas c) {
212→            if (!ui) return;
213→            // 顶部渐变 + 标题 + 关闭
214→            Ui.round(c, 44f, 40f, 96f, 92f, 26f, 0x66000000);
215→            Ui.textC(c, "‹", 70f, 78f, 34f, 0xFFFFFFFF);
216→            Ui.textC(c, Ui.ellipsize(title, 18f, 280f), 233f, 76f, 18f, 0xFFE8EEF4);
217→
218→            boolean playing = mp != null && prepared && mp.isPlaying();
219→            if (!playing) {
220→                Ui.circle(c, 233f, 233f, 40f, 0x66000000);
221→                Ui.textC(c, "▶", 233f, 247f, 40f, 0xFFFFFFFF);
222→            }
223→
224→            // 底部进度条
225→            long dur = mp != null && prepared ? mp.getDuration() : 0;
226→            long pos = mp != null ? mp.getCurrentPosition() : 0;
227→            float ratio = dur > 0 ? (float) pos / dur : 0f;
228→            RectF bar = new RectF(60f, 418f, 406f, 428f);
229→            Ui.bar(c, bar, ratio, Ui.ACCENT, 0x55FFFFFF);
230→            Ui.circle(c, bar.left + ratio * bar.width(), bar.centerY(), 9f, 0xFFFFFFFF);
231→            Ui.textL(c, Fs.humanMs(pos), 60f, 410f, 13f, 0xFFB9C6D2);
232→            Ui.textR(c, Fs.humanMs(dur), 406f, 410f, 13f, 0xFFB9C6D2);
233→        }
