  1→package com.watchsuite.core;
  2→
  3→import android.content.ContentUris;
  4→import android.content.Context;
  5→import android.database.Cursor;
  6→import android.net.Uri;
  7→import android.provider.MediaStore;
  8→
  9→import java.io.File;
 10→import java.util.ArrayList;
 11→
 12→/** 从 MediaStore 扫描视频 / 音频 / 图片。 */
 13→public final class MediaScan {
 14→
 15→    public static final class Item {
 16→        public Uri uri;
 17→        public String path;
 18→        public String name;
 19→        public long size;
 20→        public long duration; // ms，图片为 0
 21→        public long modified;
 22→    }
 23→
 24→    private MediaScan() {}
 25→
 26→    public static ArrayList<Item> videos(Context c) {
 27→        return query(c, MediaStore.Video.Media.EXTERNAL_CONTENT_URI, true);
 28→    }
 29→
 30→    public static ArrayList<Item> audios(Context c) {
 31→        return query(c, MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, true);
 32→    }
 33→
 34→    public static ArrayList<Item> images(Context c) {
 35→        return query(c, MediaStore.Images.Media.EXTERNAL_CONTENT_URI, false);
 36→    }
 37→
 38→    private static ArrayList<Item> query(Context c, Uri collection, boolean withDuration) {
 39→        ArrayList<Item> out = new ArrayList<>();
 40→        String[] proj = new String[]{
 41→                MediaStore.MediaColumns._ID,
 42→                MediaStore.MediaColumns.DATA,
 43→                MediaStore.MediaColumns.DISPLAY_NAME,
 44→                MediaStore.MediaColumns.SIZE,
 45→                MediaStore.MediaColumns.DURATION};
 46→        Cursor cur = null;
 47→        try {
 48→            cur = c.getContentResolver().query(collection, proj, null, null,
 49→                    MediaStore.MediaColumns.DATE_ADDED + " DESC");
 50→            if (cur != null) {
 51→                while (cur.moveToNext()) {
 52→                    Item it = new Item();
 53→                    long id = cur.getLong(0);
 54→                    it.uri = ContentUris.withAppendedId(collection, id);
 55→                    it.path = cur.getString(1);
 56→                    it.name = cur.getString(2);
 57→                    it.size = cur.getLong(3);
 58→                    it.duration = withDuration ? cur.getLong(4) : 0;
 59→                    if (it.path != null && it.size > 0) out.add(it);
 60→                }
 61→            }
 62→        } catch (Throwable ignored) {
 63→        } finally {
 64→            if (cur != null) cur.close();
 65→        }
 66→        return out;
 67→    }
 68→
 69→    public static String dur(long ms) {
 70→        long s = ms / 1000;
 71→        return String.format(java.util.Locale.US, "%d:%02d", s / 60, s % 60);
 72→    }
 73→
 74→    // ---------- 文件系统直扫（不依赖 MediaStore 索引） ----------
 75→
 76→    /** kind: 视频 / 图片 / 音频（与 Fs.cat 一致）。 */
 77→    public static ArrayList<Item> scanKind(String kind) {
 78→        ArrayList<Item> out = new ArrayList<>();
 79→        walk(Fs.root(), out, kind, 0);
 80→        out.sort((a, b) -> Long.compare(b.modified, a.modified));
 81→        return out;
 82→    }
 83→
 84→    private static void walk(File dir, ArrayList<Item> out, String kind, int depth) {
 85→        if (depth > 10) return;
 86→        File[] kids = dir.listFiles();
 87→        if (kids == null) return;
 88→        for (File f : kids) {
 89→            String n = f.getName();
 90→            if (f.isDirectory()) {
 91→                if (n.startsWith(".")) continue;
 92→                if (n.equals("data") || n.equals("obb")) {
 93→                    File p = f.getParentFile();
 94→                    if (p != null && "Android".equals(p.getName())) continue;
 95→                }
 96→                walk(f, out, kind, depth + 1);
 97→            } else if (f.length() > 0 && Fs.cat(n).equals(kind)) {
 98→                Item it = new Item();
 99→                it.path = f.getAbsolutePath();
100→                it.name = n;
101→                it.size = f.length();
102→                it.modified = f.lastModified();
103→                out.add(it);
104→            }
105→        }
106→    }
107→}
