 17→/** 存储分析：总览环形图 + 分类占比 + 大文件排行。 */
 18→public class StorageScreen extends Screen {
 19→
 20→    private static final float LIST_TOP = 258f, LIST_BOT = 422f;
 21→
 22→    private final Scroll sc = new Scroll();
 23→    private Fs.Stats stats;
 24→    private long total = 0, avail = 0;
 25→    private boolean scanning = true;
 26→    private int visited = 0;
 27→
 28→    public StorageScreen(MainActivity a) {
 29→        super(a);
 30→    }
 31→
 32→    @Override
 33→    public void onEnter() {
 34→        scanning = true;
 35→        act.bg(() -> {
 36→            long[] s = Fs.space();
 37→            total = s[0];
 38→            avail = s[1];
 39→            Fs.Stats st = Fs.scan(Fs.root(), v -> {
 40→                visited = v;
 41→                act.ui(this::invalidate);
 42→                return true;
 43→            });
 44→            act.ui(() -> {
 45→                stats = st;
 46→                scanning = false;
 47→                long used = stats.total;
 48→                sc.max = Math.max(0, contentH() - (LIST_BOT - LIST_TOP));
 49→                sc.clamp();
 50→                invalidate();
 51→            });
 52→        });
 53→    }
 54→
 55→    private int catCount() {
 56→        return Fs.CATS.length;
 57→    }
 58→
 59→    private float contentH() {
 60→        return catCount() * 38f + 26f + 5 * 46f;
 61→    }
 62→
 63→    @Override
 64→    public void draw(Canvas c) {
 65→        header(c, "存储分析", null);
 66→
 67→        float ratio = total > 0 && stats != null
 68→                ? (float) Math.min(1.0, (double) stats.total / total) : 0f;
 69→        Ui.ring(c, 233f, 176f, 62f, 14f, ratio, Ui.ACCENT, Ui.SURFACE2);
 70→        Ui.textC(c, scanning ? "…" : Math.round(ratio * 100) + "%", 233f, 186f, 26f, Ui.TEXT);
 71→        Ui.textC(c, scanning ? "扫描中 " + visited + " 文件"
 72→                        : "已用 " + Fs.human(stats.total) + " · 剩 " + Fs.human(avail),
 73→                233f, 236f, 14f, Ui.DIM);
 74→
 75→        c.save();
 76→        c.clipRect(56f, LIST_TOP, 410f, LIST_BOT);
 77→        c.translate(0, -sc.off);
 78→
