 83→            float y = LIST_TOP + i * 38f;
 84→            if (y + 38f < LIST_TOP + sc.off || y > LIST_BOT + sc.off) continue;
 85→            long v = stats != null ? stats.byCat[i] : 0;
 86→            int col = Fs.catColor(Fs.CATS[i]);
 87→            Ui.circle(c, 70f, y + 13f, 5f, col);
 88→            Ui.textLBold(c, Fs.CATS[i], 86f, y + 19f, 16f, Ui.TEXT);
 89→            Ui.textR(c, Fs.human(v), 410f, y + 19f, 15f, Ui.DIM);
 90→            RectF bar = new RectF(86f, y + 26f, 410f, y + 31f);
 91→            Ui.bar(c, bar, v / (float) maxCat, col, Ui.SURFACE);
 92→        }
 93→
 94→        // 大文件排行
 95→        float y0 = LIST_TOP + catCount() * 38f + 12f;
 96→        Ui.textL(c, "大文件 TOP 5", 86f, y0, 15f, Ui.FAINT);
 97→        if (stats != null) {
 98→            ArrayList<File> top = topFiles(Fs.root(), 5);
 99→            for (int i = 0; i < top.size(); i++) {
100→                File f = top.get(i);
