 16→/** 空间清理：分类扫描垃圾文件，勾选后一键清理（OPPO 风格）。 */
 17→public class CleanScreen extends Screen {
 18→
 19→    private static class Cat {
 20→        String name;
 21→        String desc;
 22→        long size;
 23→        int count;
 24→        boolean checked = true;
 25→        boolean info;          // 仅展示，不可清理
 26→        ArrayList<File> files = new ArrayList<>();
 27→
 28→        Cat(String n, String d) {
 29→            name = n;
 30→            desc = d;
 31→        }
 32→    }
 33→
 34→    private static final float L = 52f, R = 414f, TOP = 200f, BOT = 420f;
 35→    private static final float ROW_H = 46f, GAP = 5f;
 36→
 37→    private final ArrayList<Cat> cats = new ArrayList<>();
 38→    private final Scroll sc = new Scroll();
 39→    private boolean scanning = false;
 40→    private int confirmMode = 0; // 0 无 1 确认
 41→
 42→    private final RectF btnClean = new RectF(262f, 130f, 372f, 184f);
 43→
 44→    public CleanScreen(MainActivity a) {
 45→        super(a);
 46→    }
 47→
 48→    @Override
 49→    public void onEnter() {
 50→        scan();
 51→    }
 52→
 53→    private void scan() {
 54→        scanning = true;
 55→        cats.clear();
 56→        sc.reset();
 57→        invalidate();
 58→        act.bg(() -> {
 59→            ArrayList<Cat> out = new ArrayList<>();
 60→
 61→            Cat cache = new Cat("应用缓存", "各应用产生的临时文件");
 62→            File dataDir = new File(Fs.ROOT, "Android/data");
 63→            File[] apps = dataDir.listFiles();
 64→            if (apps != null) {
 65→                for (File app : apps) {
 66→                    for (String cd : new String[]{"cache", "code_cache"}) {
 67→                        File cd1 = new File(app, cd);
 68→                        collect(cd1, cache.files, 0);
 69→                    }
 70→                }
 71→            }
 72→            out.add(cache);
 73→
 74→            Cat thumb = new Cat("缩略图缓存", "DCIM/.thumbnails");
 75→            collect(new File(Fs.ROOT, "DCIM/.thumbnails"), thumb.files, 0);
 76→            out.add(thumb);
 77→
 78→            Cat logs = new Cat("日志文件", "存储里的 *.log");
 79→            collectByExt(Fs.root(), "log", logs.files, 0, 6);
 80→            out.add(logs);
 81→
 82→            Cat apk = new Cat("安装包", "Download 里的 *.apk");
 83→            collectByExt(new File(Fs.ROOT, "Download"), "apk", apk.files, 0, 5);
 84→            out.add(apk);
 85→
 86→            Cat big = new Cat("大文件", "超过 200MB，请自行确认");
 87→            big.info = true;
 88→            big.checked = false;
 89→            try {
 90→                for (File f : Fs.recent(Fs.root(), 400)) {
 91→                    if (f.length() >= 200L * 1024 * 1024) big.files.add(f);
 92→                }
 93→            } catch (Throwable ignored) {
 94→            }
 95→            out.add(big);
 96→
 97→            Cat empty = new Cat("空文件夹", "不占用空间，可顺手清掉");
 98→            empty.checked = false;
 99→            collectEmpty(Fs.root(), empty.files, 0, 6);
100→            out.add(empty);
101→
102→            for (Cat ct : out) {
103→                ct.count = ct.files.size();
104→                for (File f : ct.files) ct.size += f.length();
105→            }
106→
107→            act.ui(() -> {
108→                cats.clear();
109→                cats.addAll(out);
110→                scanning = false;
111→                sc.max = Math.max(0, cats.size() * (ROW_H + GAP) - (BOT - TOP));
112→                sc.clamp();
113→                invalidate();
114→            });
115→        });
116→    }
117→
118→    private static void collect(File dir, ArrayList<File> out, int depth) {
119→        if (depth > 8) return;
120→        File[] kids = dir.listFiles();
121→        if (kids == null) return;
122→        for (File k : kids) {
123→            if (k.isDirectory()) collect(k, out, depth + 1);
124→            else out.add(k);
125→        }
126→    }
127→
128→    private static void collectByExt(File dir, String ext, ArrayList<File> out,
129→                                     int depth, int maxDepth) {
130→        if (dir == null || depth > maxDepth) return;
131→        File[] kids = dir.listFiles();
132→        if (kids == null) return;
133→        for (File k : kids) {
134→            if (k.isDirectory()) {
135→                if (k.getName().startsWith(".")) continue;
136→                collectByExt(k, ext, out, depth + 1, maxDepth);
137→            } else if (Fs.ext(k.getName()).equals(ext)) {
138→                out.add(k);
139→            }
140→        }
141→    }
142→
143→    private static void collectEmpty(File dir, ArrayList<File> out, int depth, int maxDepth) {
144→        if (dir == null || depth > maxDepth || !dir.isDirectory()) return;
145→        String n = dir.getName();
146→        if (n.equals("data") || n.equals("obb")) {
147→            File p = dir.getParentFile();
148→            if (p != null && "Android".equals(p.getName())) return;
149→        }
150→        File[] kids = dir.listFiles();
151→        if (kids == null || kids.length == 0) {
152→            out.add(dir);
153→            return;
154→        }
155→        for (File k : kids) collectEmpty(k, out, depth + 1, maxDepth);
156→    }
157→
158→    private long checkedSize() {
159→        long s = 0;
160→        for (Cat ct : cats) if (ct.checked && !ct.info) s += ct.size;
161→        return s;
162→    }
163→
164→    private int checkedCount() {
165→        int n = 0;
166→        for (Cat ct : cats) if (ct.checked && !ct.info) n += ct.count;
167→        return n;
168→    }
169→
170→    @Override
171→    public void draw(Canvas c) {
172→        header(c, "空间清理", scanning ? "扫描中…" : null);
173→
174→        // 汇总卡片
175→        Ui.round(c, 60f, 124f, 406f, 190f, 22f, Ui.SURFACE);
176→        Ui.textL(c, "可清理", 86f, 154f, 15f, Ui.DIM);
177→        Ui.textLBold(c, scanning ? "…" : Fs.human(checkedSize()), 86f, 182f, 26f, Ui.OK);
178→        if (!scanning) {
179→            Ui.round(c, btnClean, 27f, Ui.OK);
180→            Ui.textC(c, "清理", btnClean.centerX(), btnClean.centerY() + 8f, 20f, 0xFF06281A);
181→        }
182→
183→        c.save();
184→        c.clipRect(L, TOP, R, BOT);
185→        c.translate(0, -sc.off);
186→        for (int i = 0; i < cats.size(); i++) {
187→            Cat ct = cats.get(i);
188→            float y = TOP + i * (ROW_H + GAP);
189→            if (y + ROW_H < TOP + sc.off || y > BOT + sc.off) continue;
190→            Ui.round(c, L, y, R, y + ROW_H, 14f, Ui.SURFACE);
191→            // 勾选圈
192→            float cx = L + 26f;
193→            if (ct.info) {
194→                Ui.circleStroke(c, cx, y + ROW_H / 2f, 11f, 2.5f, Ui.FAINT);
195→            } else if (ct.checked) {
196→                Ui.circle(c, cx, y + ROW_H / 2f, 11f, Ui.OK);
197→                Ui.textC(c, "✓", cx, y + ROW_H / 2f + 5f, 14f, 0xFF06281A);
198→            } else {
199→                Ui.circleStroke(c, cx, y + ROW_H / 2f, 11f, 2.5f, Ui.FAINT);
200→            }
201→            Ui.textLBold(c, ct.name, L + 48f, y + 20f, 16f, ct.info ? Ui.DIM : Ui.TEXT);
202→            Ui.textL(c, ct.desc, L + 48f, y + 38f, 12f, Ui.FAINT);
203→            String right = ct.count == 0 ? "—" : ct.count + " 项 · " + Fs.human(ct.size);
204→            Ui.textR(c, right, R - 14f, y + 28f, 13f, ct.info ? Ui.FAINT : Ui.DIM);
205→        }
206→        c.restore();
207→
208→        if (scanning) Ui.textC(c, "正在扫描存储…", 233f, 300f, 18f, Ui.FAINT);
209→
210→        if (confirmMode == 1) {
211→            Ui.fill(c, new RectF(0, 0, W, H), 0xB0000000);
212→            Ui.round(c, 62f, 180f, 404f, 320f, 22f, Ui.SURFACE2);
213→            Ui.textC(c, "确认清理所选内容？", 233f, 226f, 20f, Ui.TEXT);
214→            Ui.textC(c, "将删除 " + Fs.human(checkedSize()), 233f, 254f, 15f, Ui.WARN);
215→            Ui.round(c, 92f, 280f, 228f, 324f, 22f, Ui.DANGER);
216→            Ui.textC(c, "清理", 160f, 309f, 19f, 0xFFFFFFFF);
217→            Ui.round(c, 238f, 280f, 374f, 324f, 22f, Ui.SURFACE);
218→            Ui.textC(c, "取消", 306f, 309f, 19f, Ui.TEXT);
219→        }
220→    }
221→
222→    @Override
223→    public boolean touch(int action, float x, float y) {
224→        if (action == MotionEvent.ACTION_DOWN) {
225→            if (confirmMode != 0) return true;
226→            sc.begin(y);
227→            return true;
228→        }
229→        if (action == MotionEvent.ACTION_MOVE) {
230→            if (confirmMode != 0) return false;
231→            float before = sc.off;
232→            sc.move(y);
233→            if (sc.off != before) invalidate();
234→            return true;
235→        }
236→        if (action == MotionEvent.ACTION_UP) {
237→            if (confirmMode == 1) {
238→                if (x >= 92f && x <= 228f && y >= 280f && y <= 324f) {
239→                    confirmMode = 0;
240→                    doClean();
241→                } else {
242→                    confirmMode = 0;
243→                }
244→                invalidate();
245→                return true;
246→            }
247→            sc.end();
248→            if (sc.dragDist() > 12f) return true;
249→            if (hitBack(x, y)) {
250→                act.pop();
251→                return true;
252→            }
253→            if (btnClean.contains(x, y) && !scanning && checkedCount() > 0) {
254→                confirmMode = 1;
255→                invalidate();
256→                return true;
257→            }
258→            if (y >= TOP && y <= BOT) {
259→                int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
260→                if (idx >= 0 && idx < cats.size()) {
261→                    Cat ct = cats.get(idx);
262→                    if (!ct.info) {
263→                        ct.checked = !ct.checked;
264→                        invalidate();
265→                    }
266→                }
267→            }
268→            return true;
269→        }
270→        return false;
271→    }
272→
273→    private void doClean() {
274→        ArrayList<File> doomed = new ArrayList<>();
275→        for (Cat ct : cats) {
276→            if (ct.checked && !ct.info) doomed.addAll(ct.files);
277→        }
278→        if (doomed.isEmpty()) return;
279→        final long before = checkedSize();
280→        act.toast("清理中…");
281→        act.bg(() -> {
282→            int ok = 0;
283→            for (File f : doomed) {
284→                if (Fs.delete(f)) ok++;
285→            }
286→            final int n = ok;
287→            act.ui(() -> {
288→                act.toast("已清理 " + n + " 项 · " + Fs.human(before));
289→                scan();
290→            });
291→        });
292→    }
293→
294→    @Override
295→    public boolean back() {
296→        if (confirmMode != 0) {
297→            confirmMode = 0;
298→            invalidate();
299→            return true;
300→        }
301→        return false;
302→    }
303→}
