 21→/** 相册：三列缩略图网格（参考腕间图库的全出血风格）。 */
 22→public class GalleryScreen extends Screen {
 23→
 24→    private static final float L = 40f, R = 426f, TOP = 116f, BOT = 424f;
 25→    private static final int COLS = 3;
 26→    private static final float CELL = (R - L - 2 * 6f) / COLS; // 124.7
 27→    private static final float CELL_GAP = 6f, ROW_GAP = 6f;
 28→    private static final float ROW_H = CELL + ROW_GAP;
 29→
 30→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
 31→    private final Scroll sc = new Scroll();
 32→    private boolean loading = true;
 33→
 34→    public GalleryScreen(MainActivity a) {
 35→        super(a);
 36→    }
 37→
 38→    @Override
 39→    public void onEnter() {
 40→        act.bg(() -> {
 41→            ArrayList<MediaScan.Item> v = MediaScan.scanKind("图片");
 42→            act.ui(() -> {
 43→                items.clear();
 44→                items.addAll(v);
 45→                loading = false;
 46→                int rows = (items.size() + COLS - 1) / COLS;
 47→                sc.max = Math.max(0, rows * ROW_H - (BOT - TOP));
 48→                sc.clamp();
 49→                invalidate();
 50→            });
 51→        });
 52→    }
 53→
 54→    @Override
 55→    public void draw(Canvas c) {
 56→        header(c, "相册", items.size() + " 张");
 57→
 58→        c.save();
 59→        c.clipRect(L, TOP, R, BOT);
 60→        c.translate(0, -sc.off);
 61→        for (int i = 0; i < items.size(); i++) {
 62→            final int fi = i;
 63→            int r = i / COLS, col = i % COLS;
 64→            float x = L + col * (CELL + CELL_GAP);
 65→            float y = TOP + r * ROW_H;
 66→            if (y + CELL < TOP + sc.off || y > BOT + sc.off) continue;
 67→            RectF cell = new RectF(x, y, x + CELL, y + CELL);
 68→            Bitmap bm = ThumbCache.get(act, items.get(fi).path, () -> decode(items.get(fi).path));
 69→            if (bm != null) {
 70→                Ui.bitmapCrop(c, bm, cell);
 71→            } else {
 72→                Ui.round(c, cell, 8f, Ui.SURFACE);
 73→                Ui.textC(c, "图", cell.centerX(), cell.centerY() + 8f, 22f, Ui.FAINT);
 74→            }
 75→        }
 76→        c.restore();
 77→
 78→        if (loading) Ui.textC(c, "扫描图片中…", 233f, 270f, 20f, Ui.FAINT);
 79→        if (!loading && items.isEmpty()) {
 80→            Ui.textC(c, "没有找到图片", 233f, 260f, 20f, Ui.FAINT);
 81→        }
 82→    }
 83→
 84→    private static Bitmap decode(String path) {
 85→        try {
 86→            BitmapFactory.Options o = new BitmapFactory.Options();
 87→            o.inJustDecodeBounds = true;
 88→            BitmapFactory.decodeFile(path, o);
 89→            int sample = 1;
