 42→            act.ui(() -> {
 43→                items.clear();
 44→                items.addAll(v);
 45→                loading = false;
 46→                int rows = (items.size() + COLS - 1) / COLS;
 47→                sc.max = Math.max(0, rows * ROW_H - (BOT - TOP));
