 64→            float x = L + col * (CELL + CELL_GAP);
 65→            float y = TOP + r * ROW_H;
 66→            if (y + CELL < TOP + sc.off || y > BOT + sc.off) continue;
 67→            RectF cell = new RectF(x, y, x + CELL, y + CELL);
 68→            Bitmap bm = ThumbCache.get(act, items.get(fi).path, () -> decode(items.get(fi).path));
 69→            if (bm != null) {
 70→                Ui.bitmapCrop(c, bm, cell);
 71→            } else {
 72→                Ui.round(c, cell, 8f, Ui.SURFACE);
