 84→    private static Bitmap decode(String path) {
 85→        try {
 86→            BitmapFactory.Options o = new BitmapFactory.Options();
 87→            o.inJustDecodeBounds = true;
 88→            BitmapFactory.decodeFile(path, o);
 89→            int sample = 1;
 90→            while (o.outWidth / sample > 320 || o.outHeight / sample > 320) sample *= 2;
 91→            BitmapFactory.Options o2 = new BitmapFactory.Options();
 92→            o2.inSampleSize = sample;
 93→            return BitmapFactory.decodeFile(path, o2);
 94→        } catch (Throwable t) {
 95→            return null;
 96→        }
 97→    }
