119→            int col = (int) ((x - L) / (CELL + CELL_GAP));
120→            if (col >= COLS) col = COLS - 1;
121→            int row = (int) ((y + sc.off - TOP) / ROW_H);
122→            int idx = row * COLS + col;
123→            if (idx >= 0 && idx < items.size()) {
124→                ArrayList<File> fs = new ArrayList<>();
125→                for (MediaScan.Item it : items) fs.add(new File(it.path));
126→                act.push(new ViewerScreen(act, fs, idx));
