 19→/** 音乐：列表 + 底部正在播放卡片，支持后台播放。 */
 20→public class MusicScreen extends Screen {
 21→
 22→    private static final float L = 44f, R = 422f;
 23→    private static final float ROW_H = 56f, GAP = 6f;
 24→
 25→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
 26→    private final Scroll sc = new Scroll();
 27→    private final Handler h = new Handler(Looper.getMainLooper());
 28→    private boolean loading = true;
 29→
 30→    private final RectF bPrev = new RectF(96f, 372f, 152f, 424f);
 31→    private final RectF bPlay = new RectF(197f, 362f, 269f, 430f);
 32→    private final RectF bNext = new RectF(314f, 372f, 370f, 424f);
 33→
 34→    private final Runnable tick = new Runnable() {
 35→        @Override
 36→        public void run() {
 37→            invalidate();
 38→            h.postDelayed(this, 500);
 39→        }
 40→    };
 41→
 42→    public MusicScreen(MainActivity a) {
 43→        super(a);
 44→    }
 45→
 46→    @Override
 47→    public void onEnter() {
 48→        h.post(tick);
 49→        if (items.isEmpty()) {
 50→            act.bg(() -> {
 51→                ArrayList<MediaScan.Item> v = MediaScan.scanKind("音频");
 52→                act.ui(() -> {
 53→                    items.clear();
 54→                    items.addAll(v);
 55→                    loading = false;
 56→                    sc.max = Math.max(0, items.size() * (ROW_H + GAP) - (listBot() - 124f));
 57→                    sc.clamp();
 58→                    invalidate();
 59→                });
 60→            });
 61→        }
 62→    }
 63→
 64→    @Override
 65→    public void onLeave() {
 66→        h.removeCallbacks(tick);
 67→    }
 68→
 69→    private float listBot() {
 70→        return hasNow() ? 340f : 420f;
 71→    }
 72→
 73→    private boolean hasNow() {
 74→        return MusicService.index >= 0;
 75→    }
 76→
 77→    @Override
 78→    public void draw(Canvas c) {
 79→        header(c, "音乐", items.size() + " 首");
 80→
 81→        c.save();
 82→        c.clipRect(L, 124f, R, listBot());
 83→        c.translate(0, -sc.off);
 84→        float top = 124f;
 85→        for (int i = 0; i < items.size(); i++) {
 86→            MediaScan.Item it = items.get(i);
 87→            float y = top + i * (ROW_H + GAP);
 88→            if (y + ROW_H < top + sc.off || y > listBot() + sc.off) continue;
 89→            boolean cur = MusicService.index == i;
 90→            RectF r = new RectF(L, y, R, y + ROW_H);
 91→            Ui.round(c, r, 16f, cur ? Ui.alpha(Ui.ACCENT, 0x30) : Ui.SURFACE);
