109→        Ui.round(c, 40f, 350f, 426f, 432f, 22f, Ui.SURFACE2);
110→        Ui.textC(c, Ui.ellipsize(MusicService.curTitle(), 16f, 300f), 233f, 374f, 16f, Ui.TEXT);
