115→        float ratio = dur > 0 ? (float) pos / dur : 0f;
116→        RectF bar = new RectF(66f, 382f, 400f, 388f);
117→        Ui.bar(c, bar, ratio, Ui.ACCENT, Ui.SURFACE);
118→
