public static void ensure(Context ctx, boolean force, Callback cb) {
    final Context app = ctx.getApplicationContext();
    BUILD.execute(() -> {
        Snap s = cur;
        if (s == null) { s = loadDisk(app); cur = s; }
        if (s != null) cb.done(s);   // 先给旧数据
        boolean stale = s == null || force || System.currentTimeMillis() - s.builtAt > TTL;
        if (!stale) return;
        Snap fresh = build(app);
        cur = fresh;
        saveDisk(app, fresh);
        cb.done(fresh);
    });
}
```
