```java
private static void walk(File dir, int depth, Snap s) {
    if (depth > 12) return;
    String[] names = dir.list();
    if (names == null) return;
    boolean empty = true;
    StructStat st = new StructStat();
    for (String nm : names) {
        File f = new File(dir, nm);
        String p = f.getAbsolutePath();
        if (Os.stat(p, st) != 0) { empty = false; continue; }
        empty = false;
        if (OsConstants.S_ISDIR(st.st_mode)) {
            if (skipDir(nm, f)) continue;
            walk(f, depth + 1, s);
        } else {
            s.add(p, nm, st.st_size, st.st_mtime * 1000L);
        }
    }
    if (empty && depth > 0) s.addEmpty(dir);
}
```

