74→    @Override
75→    public boolean touch(int action, float x, float y) {
76→        if (action != MotionEvent.ACTION_UP) return false;
77→        for (int i = 0; i < 8; i++) {
78→            if (tiles[i].contains(x, y)) {
79→                open(i);
