 24→/**
 25→ * 一次遍历、全应用共用的一份存储索引。
 26→ *
 27→ * <p>以前 视频/音乐/相册/分析/清理 各自把整盘走一遍（5 次），每次都靠
 28→ * File.length()/isDirectory()/lastModified() 各触发一次 stat。现在改为：
 29→ * ① 单次遍历，用 Os.stat 一次拿全 inode 信息（stat 调用从 3 次降到 1 次）；
 30→ * ② 顶层目录 4 线程并行；
 31→ * ③ 结果落盘缓存，下次开应用先用缓存、再后台刷新。
 32→ */
 33→public final class Index {
 34→
 35→    public interface Callback {
 36→        /** 可能在主线程被调用两次：先旧缓存，后新结果。 */
 37→        void onIndex(Snap s);
 38→    }
 39→
 40→    /** 一份完整的存储快照。 */
 41→    public static final class Snap {
 42→        public final Fs.Stats stats = new Fs.Stats();
 43→        public final ArrayList<MediaScan.Item> videos = new ArrayList<>();
 44→        public final ArrayList<MediaScan.Item> audios = new ArrayList<>();
 45→        public final ArrayList<MediaScan.Item> images = new ArrayList<>();
 46→        public final ArrayList<File> logs = new ArrayList<>();
 47→        public final ArrayList<File> apks = new ArrayList<>();
 48→        public final ArrayList<File> big = new ArrayList<>();
 49→        public final ArrayList<File> emptyDirs = new ArrayList<>();
 50→        public final ArrayList<File> top = new ArrayList<>();
 51→        public long builtAt;
 52→
 53→        private static final long BIG = 200L * 1024 * 1024;
 54→
 55→        synchronized void add(String path, String name, long size, long mtime) {
 56→            stats.add(name, size);
 57→            String cat = Fs.cat(name);
 58→            if ("视频".equals(cat)) {
 59→                videos.add(item(path, name, size, mtime));
 60→            } else if ("音频".equals(cat)) {
 61→                audios.add(item(path, name, size, mtime));
 62→            } else if ("图片".equals(cat)) {
 63→                images.add(item(path, name, size, mtime));
 64→            }
 65→            String ext = Fs.ext(name);
 66→            if ("log".equals(ext)) {
 67→                if (logs.size() < 800) logs.add(new File(path));
 68→            } else if ("apk".equals(ext) && path.contains("/Download/") && apks.size() < 200) {
 69→                apks.add(new File(path));
 70→            }
 71→            if (size >= BIG && big.size() < 150) big.add(new File(path));
 72→            if (size > 4L * 1024 * 1024) {
 73→                top.add(new File(path));
 74→                if (top.size() > 24) {
 75→                    Collections.sort(top, (a, b) -> Long.compare(b.length(), a.length()));
 76→                    while (top.size() > 8) top.remove(top.size() - 1);
 77→                }
 78→            }
 79→        }
 80→
 81→        synchronized void empty(File dir) {
 82→            if (emptyDirs.size() < 400) emptyDirs.add(dir);
 83→        }
 84→
 85→        private static MediaScan.Item item(String path, String name, long size, long mtime) {
 86→            MediaScan.Item it = new MediaScan.Item();
 87→            it.path = path;
 88→            it.name = name;
 89→            it.size = size;
 90→            it.modified = mtime;
 91→            return it;
 92→        }
 93→
 94→        void finish() {
 95→            java.util.Comparator<MediaScan.Item> byTime =
 96→                    (a, b) -> Long.compare(b.modified, a.modified);
 97→            Collections.sort(videos, byTime);
 98→            Collections.sort(audios, byTime);
 99→            Collections.sort(images, byTime);
100→            Collections.sort(top, (a, b) -> Long.compare(b.length(), a.length()));
101→            while (top.size() > 8) top.remove(top.size() - 1);
102→            if (!top.isEmpty()) {
103→                stats.topSize = top.get(0).length();
104→                stats.topPath = top.get(0).getAbsolutePath();
105→            }
106→        }
107→    }
108→
109→    private static final long TTL = 20 * 60 * 1000L;
110→    private static volatile Snap cur;
111→
112→    private static final ExecutorService BUILD = Executors.newSingleThreadExecutor();
113→    private static final Handler MAIN = new Handler(Looper.getMainLooper());
114→
115→    private Index() {}
116→
117→    /** 内存里已有的快照，没有则返回 null（不会触发磁盘读取）。 */
118→    public static Snap get() {
119→        return cur;
120→    }
121→
122→    /**
123→     * 取索引：先回调旧缓存（秒开），需要时再后台重建并回调新结果。
124→     * 回调都在主线程。
125→     */
126→    public static void ensure(final Context ctx, final boolean force, final Callback cb) {
127→        final Context app = ctx.getApplicationContext();
128→        BUILD.execute(() -> {
129→            Snap s = cur;
130→            if (s == null) {
131→                s = loadDisk(app);
132→                if (s != null) cur = s;
133→            }
134→            if (s != null) post(cb, s);
135→            boolean stale = force || s == null
136→                    || System.currentTimeMillis() - s.builtAt > TTL;
137→            if (!stale) return;
138→            Snap fresh = build();
139→            cur = fresh;
140→            saveDisk(app, fresh);
141→            post(cb, fresh);
142→        });
143→    }
144→
145→    private static void post(final Callback cb, final Snap s) {
146→        MAIN.post(() -> cb.onIndex(s));
147→    }
148→
149→    // ---------------- 遍历 ----------------
150→
151→    private static Snap build() {
152→        long t0 = System.currentTimeMillis();
153→        final Snap s = new Snap();
154→        File[] tops = Fs.root().listFiles();
155→        if (tops != null && tops.length > 0) {
156→            ExecutorService pool = Executors.newFixedThreadPool(4);
157→            List<Future<?>> jobs = new ArrayList<>();
158→            for (final File f : tops) {
159→                String n = f.getName();
160→                if (n.equals("Android") || n.startsWith(".")) continue;
161→                try {
162→                    jobs.add(pool.submit(() -> walk(f, 0, s)));
163→                } catch (Throwable ignored) {
164→                }
165→            }
166→            for (Future<?> j : jobs) {
167→                try {
168→                    j.get();
169→                } catch (Throwable ignored) {
170→                }
171→            }
172→            pool.shutdown();
173→        }
174→        s.builtAt = System.currentTimeMillis();
175→        s.finish();
176→        android.util.Log.i("WatchSuite", "index built: " + s.stats.files + " files, "
177→                + (s.builtAt - t0) + " ms");
178→        return s;
179→    }
180→
181→    private static void walk(File dir, int depth, Snap s) {
182→        if (depth > 12) return;
183→        String[] names;
184→        try {
185→            names = dir.list();
186→        } catch (Throwable t) {
187→            return;
188→        }
189→        if (names == null) return;
190→        if (names.length == 0) {
191→            if (depth > 0) s.empty(dir);
192→            return;
193→        }
194→        for (String nm : names) {
195→            String p = new File(dir, nm).getAbsolutePath();
196→            StructStat st;
197→            try {
198→                st = Os.stat(p);
199→            } catch (Throwable t) {
200→                continue;
201→            }
202→            if (OsConstants.S_ISDIR(st.st_mode)) {
203→                if (nm.equals("data") || nm.equals("obb")) {
204→                    if ("Android".equals(dir.getName())) continue;
205→                }
206→                if (nm.startsWith(".") && !nm.equals(".thumbnails")) continue;
207→                walk(new File(dir, nm), depth + 1, s);
208→            } else {
209→                s.add(p, nm, st.st_size, st.st_mtime * 1000L);
210→            }
211→        }
212→    }
213→
214→    // ---------------- 磁盘缓存 ----------------
215→
216→    private static File cacheFile(Context c) {
217→        return new File(c.getFilesDir(), "storage.idx");
218→    }
219→
220→    private static void saveDisk(Context c, Snap s) {
221→        BufferedWriter w = null;
222→        try {
223→            w = new BufferedWriter(new OutputStreamWriter(
224→                    new FileOutputStream(cacheFile(c)), "UTF-8"), 1 << 16);
225→            StringBuilder sb = new StringBuilder(256);
226→            sb.append("S|").append(s.builtAt).append('|').append(s.stats.total)
227→                    .append('|').append(s.stats.files);
228→            for (long v : s.stats.byCat) sb.append('|').append(v);
229→            for (int v : s.stats.filesByCat) sb.append('|').append(v);
230→            w.write(sb.toString());
231→            w.write('\n');
232→            for (MediaScan.Item it : s.images) w.write("U|" + it.size + "|" + it.modified + "|" + it.path + "\n");
233→            for (MediaScan.Item it : s.videos) w.write("V|" + it.size + "|" + it.modified + "|" + it.path + "\n");
234→            for (MediaScan.Item it : s.audios) w.write("A|" + it.size + "|" + it.modified + "|" + it.path + "\n");
235→            for (File f : s.logs) w.write("G|" + f.length() + "|" + f.getAbsolutePath() + "\n");
236→            for (File f : s.apks) w.write("P|" + f.length() + "|" + f.getAbsolutePath() + "\n");
237→            for (File f : s.big) w.write("B|" + f.length() + "|" + f.getAbsolutePath() + "\n");
238→            for (File f : s.emptyDirs) w.write("E|" + f.getAbsolutePath() + "\n");
239→            for (File f : s.top) w.write("T|" + f.length() + "|" + f.getAbsolutePath() + "\n");
240→        } catch (Throwable ignored) {
241→        } finally {
242→            if (w != null) try {
243→                w.close();
244→            } catch (Throwable ignored) {
245→            }
246→        }
247→    }
248→
249→    private static Snap loadDisk(Context c) {
250→        File f = cacheFile(c);
251→        if (!f.exists()) return null;
252→        BufferedReader r = null;
253→        try {
254→            r = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"), 1 << 16);
255→            Snap s = new Snap();
256→            String line = r.readLine();
257→            if (line == null || !line.startsWith("S|")) return null;
258→            String[] p = line.split("\\|");
259→            s.builtAt = Long.parseLong(p[1]);
260→            s.stats.total = Long.parseLong(p[2]);
261→            s.stats.files = Integer.parseInt(p[3]);
262→            int cats = Fs.CATS.length;
263→            for (int i = 0; i < cats; i++) s.stats.byCat[i] = Long.parseLong(p[4 + i]);
264→            for (int i = 0; i < cats; i++) s.stats.filesByCat[i] = Integer.parseInt(p[4 + cats + i]);
265→            while ((line = r.readLine()) != null) {
266→                int a = line.indexOf('|');
267→                if (a < 0) continue;
268→                char t = line.charAt(0);
269→                String rest = line.substring(a + 1);
270→                switch (t) {
271→                    case 'U':
272→                    case 'V':
273→                    case 'A': {
274→                        int b1 = rest.indexOf('|');
275→                        int b2 = rest.indexOf('|', b1 + 1);
276→                        if (b2 < 0) break;
277→                        long size = Long.parseLong(rest.substring(0, b1));
278→                        long mt = Long.parseLong(rest.substring(b1 + 1, b2));
279→                        String path = rest.substring(b2 + 1);
280→                        String name = path.substring(path.lastIndexOf('/') + 1);
281→                        MediaScan.Item it = Snap.item(path, name, size, mt);
282→                        if (t == 'U') s.images.add(it);
283→                        else if (t == 'V') s.videos.add(it);
284→                        else s.audios.add(it);
285→                        break;
286→                    }
287→                    case 'G':
288→                    case 'P':
289→                    case 'B':
290→                    case 'T': {
291→                        int b1 = rest.indexOf('|');
292→                        if (b1 < 0) break;
293→                        File ff = new File(rest.substring(b1 + 1));
294→                        if (t == 'G') s.logs.add(ff);
295→                        else if (t == 'P') s.apks.add(ff);
296→                        else if (t == 'B') s.big.add(ff);
297→                        else s.top.add(ff);
298→                        break;
299→                    }
300→                    case 'E':
301→                        s.emptyDirs.add(new File(rest));
302→                        break;
303→                    default:
304→                        break;
305→                }
306→            }
307→            if (!s.top.isEmpty()) {
308→                s.stats.topSize = s.top.get(0).length();
309→                s.stats.topPath = s.top.get(0).getAbsolutePath();
310→            }
311→            return s;
312→        } catch (Throwable t) {
313→            return null;
314→        } finally {
315→            if (r != null) try {
316→                r.close();
317→            } catch (Throwable ignored) {
318→            }
319→        }
320→    }
321→}
