182→    @Override
183→    public boolean touch(int action, float x, float y) {
184→        if (action == MotionEvent.ACTION_DOWN) {
185→            if (mode != 0) return overlayTouch(action, x, y);
186→            sc.begin(y);
187→            return true;
188→        }
189→        if (action == MotionEvent.ACTION_MOVE) {
190→            if (mode != 0) return false;
191→            float before = sc.off;
192→            sc.move(y);
193→            if (sc.off != before) invalidate();
194→            return true;
195→        }
196→        if (action == MotionEvent.ACTION_UP) {
197→            if (mode != 0) return overlayTouch(action, x, y);
198→            sc.end();
199→            if (Math.abs(sc.dragDist()) > 12f) return true; // 拖动不算点击
200→            if (hitBack(x, y)) {
201→                if (!goUp()) act.pop();
202→                return true;
203→            }
204→            if (y < TOP || y > BOT) return false;
205→            int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
206→            if (idx < 0 || idx >= items.size()) return false;
207→            File f = items.get(idx);
208→            if (x > R - 56f) {
209→                sheetIdx = idx;
210→                mode = 1;
211→                invalidate();
212→                return true;
213→            }
214→            open(f);
215→            return true;
216→        }
217→        return false;
218→    }
219→
220→    private boolean overlayTouch(int action, float x, float y) {
221→        if (action != MotionEvent.ACTION_UP) return true;
222→        if (mode == 1) {
223→            float top = 200f, h = 60f;
224→            int i = (int) ((y - top) / h);
225→            File f = items.get(sheetIdx);
226→            if (x < 52f || x > 414f || i < 0 || i >= SHEET.length) {
227→                mode = 0;
228→                invalidate();
229→                return true;
230→            }
231→            mode = 0;
232→            switch (SHEET[i]) {
233→                case "打开": open(f); break;
234→                case "详情": mode = 2; break;
235→                case "分享":
236→                    act.toast(Openers.share(act, f) ? "已唤起分享" : "无法分享");
237→                    break;
238→                case "删除": mode = 3; break;
239→            }
240→            invalidate();
241→            return true;
242→        }
243→        if (mode == 2) {
244→            mode = 0;
245→            invalidate();
246→            return true;
247→        }
248→        if (mode == 3) {
249→            File f = items.get(sheetIdx);
250→            if (x >= 92f && x <= 228f && y >= 268f && y <= 312f) {
251→                final File target = f;
252→                final int idx = sheetIdx;
253→                mode = 0;
254→                act.toast("删除中…");
255→                act.bg(() -> {
256→                    Fs.delete(target);
257→                    act.ui(() -> {
258→                        act.toast("已删除");
259→                        load();
260→                    });
261→                });
262→            } else {
263→                mode = 0;
264→            }
265→            invalidate();
266→            return true;
267→        }
268→        return true;
269→    }
270→
271→    private void open(File f) {
272→        if (f.isDirectory()) {
273→            go(f);
274→            return;
275→        }
276→        String name = f.getName().toLowerCase();
277→        if (name.endsWith(".apk")) {
278→            Openers.install(act, f);
279→            return;
280→        }
281→        String cat = Fs.cat(name);
282→        switch (cat) {
283→            case "视频":
284→                com.watchsuite.VideoPlayerActivity.play(act, f);
285→                break;
286→            case "音频":
287→                com.watchsuite.MusicService.playFile(act, f);
288→                act.push(new MusicScreen(act));
289→                break;
290→            case "图片":
291→                ArrayList<File> one = new ArrayList<>();
292→                one.add(f);
293→                act.push(new ViewerScreen(act, one, 0));
294→                break;
295→            default:
296→                if (!Openers.view(act, f)) act.toast("没有能打开此文件的应用");
297→                break;
298→        }
299→    }
300→
301→    @Override
302→    public boolean back() {
303→        if (mode != 0) {
304→            mode = 0;
305→            invalidate();
306→            return true;
307→        }
308→        if (hist.size() > 1) {
309→            hist.remove(hist.size() - 1);
310→            dir = hist.get(hist.size() - 1);
311→            load();
312→            return true;
313→        }
314→        return false;
315→    }
316→}
