  3→import android.annotation.SuppressLint;
  4→import android.os.StatFs;
  5→
  6→import java.io.File;
  7→import java.text.SimpleDateFormat;
  8→import java.util.ArrayList;
  9→import java.util.Arrays;
 10→import java.util.Date;
 11→import java.util.Locale;
 12→
 13→/** 文件系统小工具：体积换算、分类、扫描、删除。 */
 14→public final class Fs {
 15→
 16→    public static final String ROOT = "/storage/emulated/0";
 17→
 18→    public static final String[] CATS = {"视频", "图片", "音频", "文档", "安装包", "压缩包", "其他"};
 19→
 20→    private static final String[] VIDEO = {"mp4", "mkv", "avi", "mov", "3gp", "webm", "flv", "ts", "m4v", "rmvb", "wmv"};
 21→    private static final String[] IMAGE = {"jpg", "jpeg", "png", "gif", "webp", "bmp", "heic", "heif"};
 22→    private static final String[] AUDIO = {"mp3", "m4a", "wav", "ogg", "aac", "flac", "amr", "opus", "wma", "mid"};
 23→    private static final String[] DOC = {"pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "txt", "md", "epub", "csv"};
 24→    private static final String[] ZIP = {"zip", "rar", "7z", "tar", "gz", "bz2", "xz"};
 25→
 26→    private Fs() {}
 27→
 28→    public static File root() {
 29→        return new File(ROOT);
 30→    }
 31→
 32→    public static String human(long b) {
 33→        if (b < 1024) return b + " B";
 34→        double k = b / 1024.0;
 35→        if (k < 1024) return String.format(Locale.US, "%.0f KB", k);
 36→        double m = k / 1024.0;
 37→        if (m < 1024) return String.format(Locale.US, "%.1f MB", m);
 38→        double g = m / 1024.0;
 39→        return String.format(Locale.US, "%.2f GB", g);
 40→    }
 41→
 42→    public static String date(long ms) {
 43→        return new SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.CHINA).format(new Date(ms));
 44→    }
 45→
 46→    /** 毫秒 → m:ss / h:mm:ss。 */
 47→    public static String humanMs(long ms) {
 48→        long s = ms / 1000;
 49→        if (s >= 3600) return String.format(Locale.US, "%d:%02d:%02d", s / 3600, s / 60 % 60, s % 60);
 50→        return String.format(Locale.US, "%d:%02d", s / 60, s % 60);
 51→    }
 52→
 53→    public static String ext(String name) {
 54→        int i = name.lastIndexOf('.');
 55→        return i < 0 ? "" : name.substring(i + 1).toLowerCase(Locale.US);
 56→    }
 57→
 58→    public static String cat(String name) {
 59→        String e = ext(name);
 60→        if (in(e, VIDEO)) return "视频";
 61→        if (in(e, IMAGE)) return "图片";
 62→        if (in(e, AUDIO)) return "音频";
 63→        if (e.equals("apk")) return "安装包";
 64→        if (in(e, DOC)) return "文档";
 65→        if (in(e, ZIP)) return "压缩包";
 66→        return "其他";
 67→    }
 68→
 69→    private static boolean in(String e, String[] arr) {
 70→        for (String s : arr) if (s.equals(e)) return true;
 71→        return false;
 72→    }
 73→
 74→    public static int catColor(String cat) {
 75→        switch (cat) {
 76→            case "视频": return 0xFF4DA3FF;
 77→            case "图片": return 0xFF3DDC84;
 78→            case "音频": return 0xFF9B7BFF;
 79→            case "文档": return 0xFFFFB454;
 80→            case "安装包": return 0xFF58D6C9;
 81→            case "压缩包": return 0xFFFF8FA3;
 82→            default: return 0xFF8CA0B4;
 83→        }
 84→    }
 85→
 86→    public static String glyph(String name, boolean dir) {
 87→        if (dir) return "夹";
 88→        switch (cat(name)) {
 89→            case "视频": return "播";
 90→            case "图片": return "图";
 91→            case "音频": return "音";
 92→            case "文档": return "文";
 93→            case "安装包": return "装";
 94→            case "压缩包": return "压";
 95→            default: return "件";
 96→        }
 97→    }
 98→
 99→    public static String mime(String name) {
100→        String e = ext(name);
101→        if (e.equals("apk")) return "application/vnd.android.package-archive";
102→        if (in(e, VIDEO)) return "video/*";
103→        if (in(e, IMAGE)) return "image/*";
104→        if (in(e, AUDIO)) return "audio/*";
105→        if (e.equals("pdf")) return "application/pdf";
106→        if (e.equals("txt") || e.equals("md") || e.equals("csv") || e.equals("log")) return "text/plain";
107→        if (e.equals("zip")) return "application/zip";
108→        return "application/octet-stream";
109→    }
110→
111→    /** 目录优先、再按名称排序。 */
112→    public static File[] list(File dir, boolean showHidden) {
113→        File[] fs = dir.listFiles();
114→        if (fs == null) return new File[0];
115→        ArrayList<File> out = new ArrayList<>();
116→        for (File f : fs) {
117→            if (!showHidden && f.getName().startsWith(".")) continue;
118→            out.add(f);
119→        }
120→        File[] arr = out.toArray(new File[0]);
121→        Arrays.sort(arr, (a, b) -> {
122→            if (a.isDirectory() != b.isDirectory()) return a.isDirectory() ? -1 : 1;
123→            return a.getName().compareToIgnoreCase(b.getName());
124→        });
125→        return arr;
126→    }
127→
128→    public static long size(File f) {
129→        if (f == null) return 0;
130→        if (f.isFile()) return f.length();
131→        long total = 0;
132→        File[] kids = f.listFiles();
133→        if (kids == null) return 0;
134→        for (File k : kids) total += size(k);
135→        return total;
136→    }
137→
138→    public static boolean delete(File f) {
139→        if (f == null || !f.exists()) return true;
140→        if (f.isDirectory()) {
141→            File[] kids = f.listFiles();
142→            if (kids != null) for (File k : kids) delete(k);
143→        }
144→        return f.delete();
145→    }
146→
147→    /** 递归计数目录内文件数量。 */
148→    public static int count(File f) {
149→        if (f == null || !f.exists()) return 0;
150→        if (f.isFile()) return 1;
151→        int n = 0;
152→        File[] kids = f.listFiles();
153→        if (kids != null) for (File k : kids) n += count(k);
154→        return n;
155→    }
156→
157→    /** 存储总容量/可用空间（字节）。 */
158→    @SuppressLint("UsableSpace")
159→    public static long[] space() {
160→        try {
161→            StatFs s = new StatFs(ROOT);
162→            return new long[]{s.getTotalBytes(), s.getAvailableBytes()};
163→        } catch (Throwable t) {
164→            return new long[]{0, 0};
165→        }
166→    }
167→
168→    /** 扫描过程中的统计容器。 */
169→    public static final class Stats {
170→        public final long[] byCat = new long[CATS.length];
171→        public final int[] filesByCat = new int[CATS.length];
172→        public long total = 0;
173→        public int files = 0;
174→        public String topPath;
175→        public long topSize = 0;
176→
177→        public void add(File f) {
178→            add(f.getName(), f.length());
179→        }
180→
181→        /** 直接按名字与体积入库，避免为了统计再创建 File 对象。 */
182→        public void add(String name, long sz) {
183→            String c = cat(name);
184→            int idx = 0;
185→            for (int i = 0; i < CATS.length; i++) if (CATS[i].equals(c)) idx = i;
186→            byCat[idx] += sz;
187→            filesByCat[idx]++;
188→            total += sz;
189→            files++;
190→        }
191→    }
192→
193→    public interface Progress {
194→        /** @return false 表示中止 */
195→        boolean onProgress(int visited);
196→    }
197→
198→    /** 扫描整盘（跳过 Android/obb 与 Android/data，避免巨量缓存拖慢）。 */
199→    public static Stats scan(File root, Progress p) {
200→        Stats st = new Stats();
201→        walk(root, st, 0, p, new int[]{0});
202→        return st;
203→    }
204→
205→    private static void walk(File dir, Stats st, int depth, Progress p, int[] visited) {
206→        if (depth > 12) return;
207→        File[] kids;
208→        try {
209→            kids = dir.listFiles();
210→        } catch (Throwable t) {
211→            return;
212→        }
213→        if (kids == null) return;
214→        for (File f : kids) {
215→            if (f.isDirectory()) {
216→                String n = f.getName();
217→                if (n.equals("obb") && f.getParentFile() != null
218→                        && "Android".equals(f.getParentFile().getName())) continue;
219→                if (n.equals("data") && f.getParentFile() != null
220→                        && "Android".equals(f.getParentFile().getName())) continue;
221→                walk(f, st, depth + 1, p, visited);
222→            } else {
223→                st.add(f);
224→                visited[0]++;
225→                if (p != null && visited[0] % 400 == 0 && !p.onProgress(visited[0])) return;
226→            }
227→        }
228→    }
229→
230→    /** 最近修改时间排序的文件列表。 */
231→    public static ArrayList<File> recent(File dir, int limit) {
232→        ArrayList<File> all = new ArrayList<>();
233→        collect(dir, all, 0);
234→        all.sort((a, b) -> Long.compare(b.lastModified(), a.lastModified()));
235→        while (all.size() > limit) all.remove(all.size() - 1);
236→        return all;
237→    }
238→
239→    private static void collect(File dir, ArrayList<File> out, int depth) {
240→        if (depth > 5) return;
241→        File[] kids = dir.listFiles();
242→        if (kids == null) return;
243→        for (File f : kids) {
244→            if (f.getName().startsWith(".")) continue;
245→            if (f.isDirectory()) collect(f, out, depth + 1);
246→            else if (f.length() > 1024 * 1024) out.add(f);
247→        }
248→    }
249→}
