 71→            Bitmap bm = ThumbCache.get(act, it.path, () ->
 72→                    ThumbnailUtils.createVideoThumbnail(it.path, MediaStore.Video.Thumbnails.MINI_KIND));
 73→            if (bm != null) {
 74→                Ui.bitmapCrop(c, bm, th);
