 80→            if (it.duration > 0) {
 81→                String d = MediaScan.dur(it.duration);
 82→                RectF tag = new RectF(th.right - 52f, th.bottom - 24f, th.right - 4f, th.bottom - 4f);
 83→                Ui.round(c, tag, 6f, 0xAA000000);
 84→                Ui.textC(c, d, tag.centerX(), tag.centerY() + 5f, 12f, 0xFFFFFFFF);
 85→            }
 86→
 87→            String name = Ui.ellipsize(it.name, 18f, 240f);
