 95→            Ui.textC(c, "没有找到视频", 233f, 270f, 20f, Ui.FAINT);
 96→            Ui.textC(c, "可先用快传把视频传到手表", 233f, 300f, 15f, Ui.FAINT);
 97→        }
 98→    }
