100→    @Override
101→    public boolean touch(int action, float x, float y) {
102→        if (action == MotionEvent.ACTION_DOWN) {
103→            sc.begin(y);
104→            return true;
105→        }
106→        if (action == MotionEvent.ACTION_MOVE) {
107→            float before = sc.off;
108→            sc.move(y);
109→            if (sc.off != before) invalidate();
110→            return true;
111→        }
112→        if (action == MotionEvent.ACTION_UP) {
