116→                act.pop();
117→                return true;
118→            }
119→            if (y < TOP || y > BOT) return false;
120→            int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
121→            if (idx < 0 || idx >= items.size()) return false;
122→            MediaScan.Item it = items.get(idx);
