 21→/** 相册：三列缩略图网格（参考腕间图库的全出血风格）。 */
 22→public class GalleryScreen extends Screen {
 23→
 24→    private static final float L = 40f, R = 426f, TOP = 116f, BOT = 424f;
 25→    private static final int COLS = 3;
 26→    private static final float CELL = (R - L - 2 * 6f) / COLS; // 124.7
 27→    private static final float CELL_GAP = 6f, ROW_GAP = 6f;
 28→    private static final float ROW_H = CELL + ROW_GAP;
 29→
 30→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
