 66→            final int fi = i;
 67→            int r = i / COLS, col = i % COLS;
 68→            float x = L + col * (CELL + CELL_GAP);
 69→            float y = TOP + r * ROW_H;
 70→            if (y + CELL < TOP + sc.off || y > BOT + sc.off) continue;
 71→            RectF cell = new RectF(x, y, x + CELL, y + CELL);
 72→            Bitmap bm = ThumbCache.get(act, items.get(fi).path, () -> decode(items.get(fi).path));
 73→            if (bm != null) {
