 93→            int sample = 1;
 94→            while (o.outWidth / sample > 320 || o.outHeight / sample > 320) sample *= 2;
 95→            BitmapFactory.Options o2 = new BitmapFactory.Options();
 96→            o2.inSampleSize = sample;
 97→            return BitmapFactory.decodeFile(path, o2);
 98→        } catch (Throwable t) {
