  9→
 10→import com.watchsuite.MainActivity;
 11→import com.watchsuite.Screen;
 12→import com.watchsuite.Scroll;
 13→import com.watchsuite.Ui;
 14→import com.watchsuite.core.Index;
 15→import com.watchsuite.core.MediaScan;
 16→import com.watchsuite.core.ThumbCache;
 17→
 18→import java.io.File;
 19→import java.util.ArrayList;
 20→
 21→/** 相册：三列缩略图网格（参考腕间图库的全出血风格）。 */
 22→public class GalleryScreen extends Screen {
 23→
 24→    private static final float L = 40f, R = 426f, TOP = 116f, BOT = 424f;
 25→    private static final int COLS = 3;
 26→    private static final float CELL = (R - L - 2 * 6f) / COLS; // 124.7
 27→    private static final float CELL_GAP = 6f, ROW_GAP = 6f;
 28→    private static final float ROW_H = CELL + ROW_GAP;
 29→
 30→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
 31→    private final Scroll sc = new Scroll();
 32→    private boolean loading = true;
 33→
 34→    public GalleryScreen(MainActivity a) {
 35→        super(a);
 36→    }
 37→
 38→    @Override
 39→    public void onEnter() {
 40→        Index.Snap s0 = Index.get();
 41→        if (s0 != null) apply(s0.images);
 42→        Index.ensure(act, false, s -> apply(s.images));
 43→    }
 44→
 45→    private void apply(ArrayList<MediaScan.Item> v) {
 46→        if (v.size() != items.size()) {
 47→            items.clear();
 48→            items.addAll(v);
 49→            sc.reset();
 50→            int rows = (items.size() + COLS - 1) / COLS;
 51→            sc.max = Math.max(0, rows * ROW_H - (BOT - TOP));
 52→            sc.clamp();
 53→        }
 54→        loading = false;
 55→        invalidate();
 56→    }
 57→
 58→    @Override
 59→    public void draw(Canvas c) {
 60→        header(c, "相册", items.size() + " 张");
 61→
 62→        c.save();
 63→        c.clipRect(L, TOP, R, BOT);
 64→        c.translate(0, -sc.off);
 65→        for (int i = 0; i < items.size(); i++) {
 66→            final int fi = i;
 67→            int r = i / COLS, col = i % COLS;
 68→            float x = L + col * (CELL + CELL_GAP);
 69→            float y = TOP + r * ROW_H;
 70→            if (y + CELL < TOP + sc.off || y > BOT + sc.off) continue;
 71→            RectF cell = new RectF(x, y, x + CELL, y + CELL);
 72→            Bitmap bm = ThumbCache.get(act, items.get(fi).path, () -> decode(items.get(fi).path));
 73→            if (bm != null) {
 74→                Ui.bitmapCrop(c, bm, cell);
 75→            } else {
 76→                Ui.round(c, cell, 8f, Ui.SURFACE);
 77→                Ui.textC(c, "图", cell.centerX(), cell.centerY() + 8f, 22f, Ui.FAINT);
 78→            }
 79→        }
 80→        c.restore();
 81→
 82→        if (loading) Ui.textC(c, "扫描图片中…", 233f, 270f, 20f, Ui.FAINT);
 83→        if (!loading && items.isEmpty()) {
 84→            Ui.textC(c, "没有找到图片", 233f, 260f, 20f, Ui.FAINT);
 85→        }
 86→    }
 87→
 88→    private static Bitmap decode(String path) {
 89→        try {
 90→            BitmapFactory.Options o = new BitmapFactory.Options();
 91→            o.inJustDecodeBounds = true;
 92→            BitmapFactory.decodeFile(path, o);
 93→            int sample = 1;
 94→            while (o.outWidth / sample > 320 || o.outHeight / sample > 320) sample *= 2;
 95→            BitmapFactory.Options o2 = new BitmapFactory.Options();
 96→            o2.inSampleSize = sample;
 97→            return BitmapFactory.decodeFile(path, o2);
 98→        } catch (Throwable t) {
 99→            return null;
100→        }
101→    }
102→
103→    @Override
104→    public boolean touch(int action, float x, float y) {
105→        if (action == MotionEvent.ACTION_DOWN) {
106→            sc.begin(y);
107→            return true;
108→        }
109→        if (action == MotionEvent.ACTION_MOVE) {
110→            float before = sc.off;
111→            sc.move(y);
112→            if (sc.off != before) invalidate();
113→            return true;
114→        }
115→        if (action == MotionEvent.ACTION_UP) {
116→            sc.end();
117→            if (sc.dragDist() > 12f) return true;
118→            if (hitBack(x, y)) {
119→                act.pop();
120→                return true;
121→            }
122→            if (y < TOP || y > BOT || x < L || x > R) return false;
123→            int col = (int) ((x - L) / (CELL + CELL_GAP));
124→            if (col >= COLS) col = COLS - 1;
125→            int row = (int) ((y + sc.off - TOP) / ROW_H);
126→            int idx = row * COLS + col;
127→            if (idx >= 0 && idx < items.size()) {
128→                ArrayList<File> fs = new ArrayList<>();
129→                for (MediaScan.Item it : items) fs.add(new File(it.path));
130→                act.push(new ViewerScreen(act, fs, idx));
131→            }
132→            return true;
133→        }
134→        return false;
135→    }
136→}
