  1→package com.watchsuite.ui;
  2→
  3→import android.graphics.Canvas;
  4→import android.graphics.RectF;
  5→import android.view.MotionEvent;
  6→
  7→import com.watchsuite.MainActivity;
  8→import com.watchsuite.Screen;
  9→import com.watchsuite.Scroll;
 10→import com.watchsuite.Ui;
