 13→
 14→import java.io.File;
 15→import java.util.ArrayList;
 16→
 17→/** 空间清理：分类扫描垃圾文件，勾选后一键清理（OPPO 风格）。 */
 18→public class CleanScreen extends Screen {
 19→
 20→    private static class Cat {
 21→        String name;
 22→        String desc;
 23→        String glyph;
 24→        int color;
 25→        long size;
 26→        int count;
 27→        boolean checked = true;
 28→        boolean info;          // 仅展示，不可清理
 29→        ArrayList<File> files = new ArrayList<>();
 30→
 31→        Cat(String n, String d, String g, int c) {
 32→            name = n;
 33→            desc = d;
 34→            glyph = g;
 35→            color = c;
 36→        }
 37→    }
 38→
 39→    private static final float L = 52f, R = 414f, TOP = 200f, BOT = 420f;
 40→    private static final float ROW_H = 46f, GAP = 5f;
 41→
 42→    private final ArrayList<Cat> cats = new ArrayList<>();
 43→    private final Scroll sc = new Scroll();
 44→    private boolean scanning = false;
 45→    private int confirmMode = 0; // 0 无 1 确认
 46→
 47→    private final RectF btnClean = new RectF(262f, 130f, 372f, 184f);
 48→
 49→    public CleanScreen(MainActivity a) {
 50→        super(a);
 51→    }
 52→
 53→    @Override
 54→    public void onEnter() {
 55→        scan();
 56→    }
 57→
 58→    private void scan() {
 59→        scanning = true;
 60→        cats.clear();
 61→        sc.reset();
 62→        invalidate();
 63→        Index.Snap mem = Index.get();
 64→        if (mem != null) act.bg(() -> build(mem));
 65→        Index.ensure(act, false, s -> act.bg(() -> build(s)));
 66→    }
 67→
 68→    /** 索引给出了全盘分类，这里只补两个索引没管的目录（缩略图、应用缓存）。 */
 69→    private void build(Index.Snap s) {
 70→        ArrayList<File> thumbs = new ArrayList<>();
 71→        collect(new File(Fs.ROOT, "DCIM/.thumbnails"), thumbs, 0);
 72→
 73→        ArrayList<File> cache = new ArrayList<>();
 74→        File[] apps = new File(Fs.ROOT, "Android/data").listFiles();
 75→        if (apps != null) {
 76→            for (File app : apps) {
 77→                collect(new File(app, "cache"), cache, 0);
 78→                collect(new File(app, "code_cache"), cache, 0);
 79→            }
 80→        }
 81→
 82→        ArrayList<Cat> out = new ArrayList<>();
 83→        out.add(mk("应用缓存", "各应用临时文件", "缓", 0xFFFFC46B, cache));
 84→        out.add(mk("缩略图", "DCIM/.thumbnails", "图", 0xFF58D6C9, thumbs));
 85→        out.add(mk("日志文件", "存储里的 *.log", "志", 0xFF8CA0B4, s.logs));
 86→        out.add(mk("安装包", "Download 里的 *.apk", "装", 0xFF3DDC84, s.apks));
 87→
 88→        Cat big = mk("大文件", "超过 200MB，请自行确认", "大", 0xFFFF8FA3, s.big);
 89→        big.info = true;
 90→        big.checked = false;
 91→        out.add(big);
 92→
 93→        Cat empty = mk("空文件夹", "不占空间，可顺手清掉", "空", 0xFF66B3FF, s.emptyDirs);
 94→        empty.checked = false;
 95→        out.add(empty);
 96→
 97→        act.ui(() -> {
 98→            cats.clear();
 99→            cats.addAll(out);
100→            scanning = false;
101→            sc.max = Math.max(0, cats.size() * (ROW_H + GAP) - (BOT - TOP));
102→            sc.clamp();
103→            invalidate();
104→        });
105→    }
106→
107→    private static Cat mk(String name, String desc, String glyph, int color, ArrayList<File> files) {
108→        Cat ct = new Cat(name, desc, glyph, color);
109→        ct.files.addAll(files);
110→        ct.count = ct.files.size();
111→        for (File f : ct.files) ct.size += f.length();
112→        return ct;
113→    }
114→
115→    private static void collect(File dir, ArrayList<File> out, int depth) {
116→        if (depth > 8) return;
117→        File[] kids = dir.listFiles();
118→        if (kids == null) return;
119→        for (File k : kids) {
120→            if (k.isDirectory()) collect(k, out, depth + 1);
121→            else out.add(k);
122→        }
123→    }
124→
125→    private long checkedSize() {
126→        long s = 0;
127→        for (Cat ct : cats) if (ct.checked && !ct.info) s += ct.size;
128→        return s;
129→    }
130→
131→    private int checkedCount() {
132→        int n = 0;
133→        for (Cat ct : cats) if (ct.checked && !ct.info) n += ct.count;
134→        return n;
135→    }
136→
137→    @Override
138→    public void draw(Canvas c) {
139→        header(c, "空间清理", scanning ? "扫描中…" : null);
140→
141→        // 汇总卡片
142→        Ui.round(c, 60f, 124f, 406f, 190f, 22f, Ui.SURFACE);
143→        Ui.textL(c, "可清理", 86f, 154f, 15f, Ui.DIM);
144→        Ui.textLBold(c, scanning ? "…" : Fs.human(checkedSize()), 86f, 182f, 26f, Ui.TEXT);
145→        if (!scanning) {
146→            Ui.round(c, btnClean, 27f, Ui.ACCENT);
147→            Ui.textC(c, "清理", btnClean.centerX(), btnClean.centerY() + 8f, 20f, Ui.ON_ACCENT);
148→        }
149→
150→        c.save();
151→        c.clipRect(L, TOP, R, BOT);
152→        c.translate(0, -sc.off);
153→        for (int i = 0; i < cats.size(); i++) {
154→            Cat ct = cats.get(i);
155→            float y = TOP + i * (ROW_H + GAP);
156→            if (y + ROW_H < TOP + sc.off || y > BOT + sc.off) continue;
157→            Ui.round(c, L, y, R, y + ROW_H, 14f, Ui.SURFACE);
158→            float cy = y + ROW_H / 2f;
159→            // 勾选圈
160→            if (ct.info || !ct.checked) {
161→                Ui.circleStroke(c, L + 20f, cy, 10f, 2.2f, Ui.FAINT);
162→            } else {
163→                Ui.circle(c, L + 20f, cy, 10f, Ui.ACCENT);
164→                Ui.textC(c, "✓", L + 20f, cy + 4.5f, 13f, Ui.ON_ACCENT);
165→            }
166→            // 彩色分类图标
167→            RectF g = new RectF(L + 38f, cy - 14f, L + 66f, cy + 14f);
168→            Ui.round(c, g, 9f, Ui.alpha(ct.color, 0x30));
169→            Ui.textC(c, ct.glyph, g.centerX(), g.centerY() + 5.5f, 15f, ct.color);
170→
171→            Ui.textLBold(c, ct.name, L + 76f, y + 20f, 16f, ct.info ? Ui.DIM : Ui.TEXT);
172→            Ui.textL(c, Ui.ellipsize(ct.desc, 12f, 150f), L + 76f, y + 38f, 12f, Ui.FAINT);
173→            String right = ct.count == 0 ? "—" : ct.count + " 项 · " + Fs.human(ct.size);
174→            Ui.textR(c, right, R - 12f, cy + 5f, 13f, ct.info ? Ui.FAINT : Ui.DIM);
175→        }
176→        c.restore();
177→
178→        if (scanning) Ui.textC(c, "正在扫描存储…", 233f, 300f, 18f, Ui.FAINT);
179→
180→        if (confirmMode == 1) {
181→            Ui.fill(c, new RectF(0, 0, W, H), 0xB0000000);
182→            Ui.round(c, 62f, 180f, 404f, 320f, 22f, Ui.SURFACE2);
183→            Ui.textC(c, "确认清理所选内容？", 233f, 226f, 20f, Ui.TEXT);
184→            Ui.textC(c, "将删除 " + Fs.human(checkedSize()), 233f, 254f, 15f, Ui.WARN);
185→            Ui.round(c, 92f, 280f, 228f, 324f, 22f, Ui.DANGER);
186→            Ui.textC(c, "清理", 160f, 309f, 19f, 0xFFFFFFFF);
187→            Ui.round(c, 238f, 280f, 374f, 324f, 22f, Ui.SURFACE);
188→            Ui.textC(c, "取消", 306f, 309f, 19f, Ui.TEXT);
189→        }
190→    }
191→
192→    @Override
193→    public boolean touch(int action, float x, float y) {
194→        if (action == MotionEvent.ACTION_DOWN) {
195→            if (confirmMode != 0) return true;
196→            sc.begin(y);
197→            return true;
198→        }
199→        if (action == MotionEvent.ACTION_MOVE) {
200→            if (confirmMode != 0) return false;
201→            float before = sc.off;
202→            sc.move(y);
203→            if (sc.off != before) invalidate();
204→            return true;
205→        }
206→        if (action == MotionEvent.ACTION_UP) {
207→            if (confirmMode == 1) {
208→                if (x >= 92f && x <= 228f && y >= 280f && y <= 324f) {
209→                    confirmMode = 0;
210→                    doClean();
211→                } else {
212→                    confirmMode = 0;
213→                }
214→                invalidate();
215→                return true;
216→            }
217→            sc.end();
218→            if (sc.dragDist() > 12f) return true;
219→            if (hitBack(x, y)) {
220→                act.pop();
221→                return true;
222→            }
223→            if (btnClean.contains(x, y) && !scanning && checkedCount() > 0) {
224→                confirmMode = 1;
225→                invalidate();
226→                return true;
227→            }
228→            if (y >= TOP && y <= BOT) {
229→                int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
230→                if (idx >= 0 && idx < cats.size()) {
231→                    Cat ct = cats.get(idx);
232→                    if (!ct.info) {
233→                        ct.checked = !ct.checked;
234→                        invalidate();
235→                    }
236→                }
237→            }
238→            return true;
239→        }
240→        return false;
241→    }
242→
243→    private void doClean() {
244→        ArrayList<File> doomed = new ArrayList<>();
245→        for (Cat ct : cats) {
246→            if (ct.checked && !ct.info) doomed.addAll(ct.files);
247→        }
248→        if (doomed.isEmpty()) return;
249→        final long before = checkedSize();
250→        act.toast("清理中…");
251→        act.bg(() -> {
252→            int ok = 0;
253→            for (File f : doomed) {
254→                if (Fs.delete(f)) ok++;
255→            }
256→            final int n = ok;
257→            act.ui(() -> {
258→                act.toast("已清理 " + n + " 项 · " + Fs.human(before));
259→                // 存储变了，后台重建索引（各页面共用）
260→                Index.ensure(act, true, s -> {
261→                });
262→                scan();
263→            });
264→        });
265→    }
266→
267→    @Override
268→    public boolean back() {
269→        if (confirmMode != 0) {
270→            confirmMode = 0;
271→            invalidate();
272→            return true;
273→        }
274→        return false;
275→    }
276→}
