 21→public class MainActivity extends Activity {
 22→
 23→    public static MainActivity I;
 24→
 25→    public ShellView shell;
 26→
 27→    private final ExecutorService pool = Executors.newFixedThreadPool(3);
 28→    private boolean askedPerm = false;
 29→
 30→    @Override
 31→    protected void onCreate(Bundle b) {
 32→        super.onCreate(b);
 33→        I = this;
 34→        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
