 44→                | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
 45→                | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
 46→                | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
 47→                | View.SYSTEM_UI_FLAG_FULLSCREEN
 48→                | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);
 49→    }
 50→
 51→    @Override
 52→    protected void onResume() {
 53→        super.onResume();
 54→        hideSystemUi();
 55→        if (!Perm.has(this) && !askedPerm) {
 56→            askedPerm = true;
 57→            shell.push(new PermScreen(this), true);
 58→        }
 59→    }
 60→
 61→    public void bg(Runnable r) {
 62→        pool.execute(r);
 63→    }
 64→
 65→    public void ui(Runnable r) {
 66→        runOnUiThread(r);
 67→    }
 68→
 69→    public void push(Screen s) {
 70→        shell.push(s, true);
 71→    }
