 79→    }
 80→
 81→    @Override
 82→    public void onBackPressed() {
 83→        if (!shell.popTop()) super.onBackPressed();
 84→    }
 85→
 86→    /** 页面栈 + 触摸分发 + 轻提示。 */
 87→    public static class ShellView extends View {
 88→
 89→        private final List<Screen> stack = new ArrayList<>();
 90→        private final Handler h = new Handler(Looper.getMainLooper());
 91→
 92→        private String toastMsg;
 93→        private long toastAt;
 94→
 95→        private float downX, downY;
 96→        private boolean edgeSwipe;
 97→
 98→        public ShellView(Context c) {
 99→            super(c);
100→            setBackgroundColor(Ui.BG);
101→        }
102→
103→        public void push(Screen s, boolean anim) {
104→            stack.add(s);
105→            s.onEnter();
106→            invalidate();
107→        }
108→
109→        public boolean popTop() {
110→            if (stack.size() <= 1) {
111→                if (!stack.isEmpty() && stack.get(0).back()) {
112→                    invalidate();
113→                    return true;
114→                }
115→                return false;
116→            }
117→            Screen s = stack.remove(stack.size() - 1);
118→            s.onLeave();
119→            invalidate();
120→            return true;
121→        }
122→
123→        public Screen top() {
124→            return stack.isEmpty() ? null : stack.get(stack.size() - 1);
125→        }
126→
127→        public void toast(String msg) {
128→            toastMsg = msg;
129→            toastAt = System.currentTimeMillis();
130→            invalidate();
131→            h.postDelayed(this::invalidate, 1900);
132→        }
133→
134→        @Override
135→        protected void onDraw(android.graphics.Canvas c) {
136→            super.onDraw(c);
137→            Screen s = top();
138→            if (s != null) s.draw(c);
139→
140→            if (toastMsg != null) {
141→                long dt = System.currentTimeMillis() - toastAt;
142→                if (dt < 1900) {
143→                    float a = dt < 1600 ? 1f : (1900 - dt) / 300f;
144→                    int col = ((int) (a * 235) << 24) | 0x0A0E13;
145→                    float w = Ui.measure(toastMsg, 18f) + 44f;
146→                    if (w > 400f) w = 400f;
147→                    float l = 233f - w / 2f, t = 372f, r = 233f + w / 2f, b = t + 46f;
148→                    Ui.round(c, l, t, r, b, 23f, col);
149→                    Ui.textC(c, Ui.ellipsize(toastMsg, 18f, w - 24f), 233f, t + 30f, 18f, 0xFFEAF1F8);
150→                } else {
151→                    toastMsg = null;
152→                }
153→            }
154→        }
155→
156→        @Override
157→        public boolean onTouchEvent(MotionEvent e) {
158→            Screen s = top();
159→            if (s == null) return true;
160→            if (s.rawTouch()) {
161→                s.touchEvent(e);
162→                return true;
163→            }
164→            float x = e.getX(), y = e.getY();
165→            switch (e.getActionMasked()) {
166→                case MotionEvent.ACTION_DOWN:
167→                    downX = x;
168→                    downY = y;
169→                    edgeSwipe = x < 62f;
170→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_DOWN, x, y);
171→                    return true;
172→                case MotionEvent.ACTION_MOVE:
173→                    if (edgeSwipe) {
174→                        if (x - downX > 60f) invalidate();
175→                    } else {
176→                        s.touch(MotionEvent.ACTION_MOVE, x, y);
177→                    }
178→                    return true;
179→                case MotionEvent.ACTION_UP:
180→                    if (edgeSwipe) {
181→                        if (x - downX > 90f && Math.abs(y - downY) < 80f) {
182→                            popTop();
183→                        } else if (Math.abs(x - downX) < 20f && Math.abs(y - downY) < 20f) {
184→                            s.touch(MotionEvent.ACTION_UP, x, y);
185→                        }
186→                    } else {
187→                        s.touch(MotionEvent.ACTION_UP, x, y);
188→                    }
189→                    return true;
190→                case MotionEvent.ACTION_CANCEL:
191→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_CANCEL, x, y);
192→                    return true;
193→            }
194→            return true;
195→        }
196→    }
197→}
