120→    public static String ellipsize(String s, float size, float maxW) {
121→        if (s == null) return "";
122→        if (measure(s, size) <= maxW) return s;
123→        String ell = "…";
124→        float ew = measure(ell, size);
125→        int lo = 0, hi = s.length();
126→        while (lo < hi) {
127→            int mid = (lo + hi + 1) / 2;
128→            if (measure(s.substring(0, mid), size) + ew <= maxW) lo = mid;
129→            else hi = mid - 1;
130→        }
131→        return s.substring(0, lo) + ell;
