168→        int a = (color >>> 24) & 0xFF;
169→        int r = (int) (((color >> 16) & 0xFF) * k);
170→        int g = (int) (((color >> 8) & 0xFF) * k);
171→        int b = (int) ((color & 0xFF) * k);
172→        return (a << 24) | (Math.min(255, r) << 16) | (Math.min(255, g) << 8) | Math.min(255, b);
173→    }
