193→        float bw = b.getWidth(), bh = b.getHeight();
194→        float scale = Math.max(dst.width() / bw, dst.height() / bh);
195→        float sw = dst.width() / scale, sh = dst.height() / scale;
196→        SR.set((int) ((bw - sw) / 2f), (int) ((bh - sh) / 2f),
197→                (int) ((bw + sw) / 2f), (int) ((bh + sh) / 2f));
198→        DR.set((int) dst.left, (int) dst.top, (int) dst.right, (int) dst.bottom);
