```java
/** 递归统计目录体积（用 Os.stat，跳过隐藏目录与 Android/data|obb）。 */
public static long dirSize(File dir) {
    long[] acc = new long[1];
    dirSize(dir, acc, 0);
    return acc[0];
}

private static void dirSize(File dir, long[] acc, int depth) {
    if (depth > 10) return;
    String[] ns;
    try { ns = dir.list(); } catch (Throwable t) { return; }
    if (ns == null) return;
    for (String n : ns) {
        if (n.startsWith(".")) continue;
        String p = new File(dir, n).getAbsolutePath();
        try {
            android.system.StructStat st = android.system.Os.stat(p);
            if (android.system.OsConstants.S_ISDIR(st.st_mode)) {
                if (n.equals("data") || n.equals("obb")) {
                    File par = dir;
                    if ("Android".equals(par.getName())) continue;
                }
                dirSize(new File(p), acc, depth + 1);
            } else {
                acc[0] += st.st_size;
            }
        } catch (Throwable ignored) { }
    }
}
```

