private void fling(float v) {
    if (onFrame == null) return;
    stopFling();
    flinging = true;
    final long start = SystemClock.uptimeMillis();
    long last = start;
    float vel = v;
    while-loop 用 Handler:
    postRunnable:
    Runnable r = new Runnable() {
        long lastT = SystemClock.uptimeMillis();
        float vv = v;
        public void run() {
            long now = SystemClock.uptimeMillis();
            float dt = (now - lastT) / 1000f; lastT = now;
            if (dt > 0.05f) dt = 0.05f;
            off += vv * dt;
            vv *= Math.pow(0.90f, dt * 60f);
            boolean edge = off <= 0 || off >= max;
            clamp();
            onFrame.run();
            if (edge || Math.abs(vv) < 40f) { flinging = false; return; }
            H.postDelayed(this, 16);
        }
    };
    H.post(r);
}
```

