```java
private final Handler H = new Handler(Looper.getMainLooper());
private Runnable flingTask;

public void fling(float v, Runnable onFrame) {
    stopFling();
    if (Math.abs(v) < 300f) return;
    final long t0 = SystemClock.uptimeMillis();
    long last = t0;
    final float[] vel = {v};
    flingTask = new Runnable() {
        @Override public void run() {
            long now = SystemClock.uptimeMillis();
            float dt = (now - last) / 1000f;
            last = now;
            if (dt > 0.05f) dt = 0.05f;
            off += vel[0] * dt;
            vel[0] *= Math.pow(0.94f, dt * 60f);
            boolean hitEdge = off <= 0 || off >= max;
            clamp();
            onFrame.run();
            if (hitEdge || Math.abs(vel[0]) < 60f) { flingTask = null; return; }
            H.postDelayed(this, 16);
        }
    };
    H.post(flingTask);
}
```
