package com.watchsuite;

/** 简易拖拽滚动：只处理位移，不做惯性，够用且不容易出错。 */
public final class Scroll {

    public float off = 0f;
    public float max = 0f;
    private float lastY = 0f;
    private float downY = 0f;
    private boolean dragging = false;

    public void begin(float y) {
        lastY = y;
        downY = y;
        dragging = true;
    }

    /** 本次按下后累计拖动距离。 */
    public float dragDist() {
        return Math.abs(downY - lastY);
    }

    public void move(float y) {
        if (!dragging) return;
        off -= (y - lastY);
        lastY = y;
        clamp();
    }

    public void end() {
        dragging = false;
    }

    public boolean isDragging() {
        return dragging;
    }

    public void clamp() {
        if (max < 0f) max = 0f;
        if (off < 0f) off = 0f;
        if (off > max) off = max;
    }

    public void reset() {
        off = 0f;
        max = 0f;
    }
}

