                off += v * dt;
                v *= Math.pow(0.90f, dt * 60f);          // 约每帧 ×0.9
                boolean atEdge = off <= 0f || off >= max;
                clamp();
                onFrame.run();
                if (atEdge || Math.abs(v) < 40f) return;
                H.postDelayed(this, 16);
            }
        });
    }

    private void stopFling() {
        token++;
    }

    public void clamp() {
        if (max < 0f) max = 0f;
        if (off < 0f) off = 0f;
        if (off > max) off = max;
    }

    public void reset() {
        stopFling();
        off = 0f;
        max = 0f;
        vy = 0f;
    }
