128→                animating = false;
129→                animFrom = null;
130→                invalidate();
131→            }
132→        }
133→
134→        public boolean popTop() {
135→            if (stack.size() <= 1) {
136→                if (!stack.isEmpty() && stack.get(0).back()) {
137→                    invalidate();
138→                    return true;
139→                }
140→                return false;
141→            }
142→            Screen gone = stack.remove(stack.size() - 1);
143→            gone.onLeave();
144→            Screen next = top();
145→            if (next != null) next.onResume();
146→            startTransition(gone, false);
147→            return true;
148→        }
149→
150→        public Screen top() {
151→            return stack.isEmpty() ? null : stack.get(stack.size() - 1);
152→        }
153→
154→        public void toast(String msg) {
155→            toastMsg = msg;
156→            toastAt = System.currentTimeMillis();
157→            invalidate();
158→            h.postDelayed(this::invalidate, 1900);
159→        }
160→
161→        // ---------------- 转场 ----------------
162→
163→        private void startTransition(final Screen from, final boolean isPush) {
164→            if (anim != null) anim.cancel();
165→            animFrom = from;
166→            animPush = isPush;
167→            animP = 0f;
168→            animating = true;
169→            anim = ValueAnimator.ofFloat(0f, 1f);
170→            anim.setDuration(isPush ? 260 : 230);
171→            anim.setInterpolator(new DecelerateInterpolator(1.7f));
172→            anim.addUpdateListener(a -> {
173→                animP = (float) a.getAnimatedValue();
174→                invalidate();
175→            });
176→            anim.addListener(new AnimatorListenerAdapter() {
177→                @Override
178→                public void onAnimationEnd(Animator a) {
179→                    // 只处理「当前正在用的那个」动画结束；被新动画顶掉的旧动画直接忽略
180→                    if (a == anim && animating) {
181→                        animating = false;
182→                        animFrom = null;
183→                        invalidate();
184→                    }
185→                }
186→            });
187→            anim.start();
188→        }
189→
190→        /** 单层绘制：先按屏幕像素平移，再以屏幕中心缩放。 */
191→        private void drawLayer(Canvas c, Screen s, float dx, float scale) {
192→            if (s == null) return;
193→            if (dx == 0f && scale == 1f) {
194→                s.draw(c);
195→                return;
196→            }
197→            int save = c.save();
198→            c.translate(dx, 0f);
199→            c.scale(scale, scale, CX, CY);
200→            s.draw(c);
201→            c.restoreToCount(save);
202→        }
203→
204→        @Override
205→        protected void onDraw(Canvas c) {
206→            super.onDraw(c);
207→            Screen cur = top();
208→            if (cur == null) return;
209→
210→            if (animating && animFrom != null) {
211→                float p = animP;
212→                if (animPush) {
213→                    // 旧页轻微左移缩小，新页从右侧滑入
214→                    drawLayer(c, animFrom, -0.18f * W * p, 1f - 0.05f * p);
215→                    drawLayer(c, cur, 0.32f * W * (1f - p), 0.95f + 0.05f * p);
216→                } else {
217→                    // 返回：上层页向右滑出，下一层从左边回到原位
218→                    drawLayer(c, cur, -0.18f * W * (1f - p), 0.95f + 0.05f * p);
219→                    drawLayer(c, animFrom, 0.32f * W * p, 1f - 0.05f * p);
220→                }
221→            } else if (popDx > 0f && stack.size() > 1) {
222→                // 手指拖着返回：下一层同步露出
223→                float p = Math.min(1f, popDx / (W * 0.34f));
224→                drawLayer(c, stack.get(stack.size() - 2), -0.18f * W * (1f - p), 0.95f + 0.05f * p);
225→                drawLayer(c, cur, popDx, 1f - 0.03f * p);
226→            } else {
227→                cur.draw(c);
228→            }
229→
230→            if (toastMsg != null) {
231→                long dt = System.currentTimeMillis() - toastAt;
232→                if (dt < 1900) {
233→                    float a = dt < 1600 ? 1f : (1900 - dt) / 300f;
234→                    int col = ((int) (a * 235) << 24) | 0x0A0E13;
235→                    float w = Ui.measure(toastMsg, 18f) + 44f;
236→                    if (w > 400f) w = 400f;
237→                    float l = 233f - w / 2f, t = 372f, r = 233f + w / 2f, b = t + 46f;
238→                    Ui.round(c, l, t, r, b, 23f, col);
239→                    Ui.textC(c, Ui.ellipsize(toastMsg, 18f, w - 24f), 233f, t + 30f, 18f, 0xFFEAF1F8);
240→                } else {
241→                    toastMsg = null;
242→                }
243→            }
244→        }
245→
246→        // ---------------- 触摸 ----------------
247→
248→        @Override
249→        public boolean onTouchEvent(MotionEvent e) {
250→            Screen s = top();
251→            if (s == null) return true;
252→            if (animating || anim != null && anim.isRunning()) return true;   // 转场中不响应，免得点错
253→            if (s.rawTouch()) {
254→                s.touchEvent(e);
255→                return true;
256→            }
257→            float x = e.getX(), y = e.getY();
258→            switch (e.getActionMasked()) {
259→                case MotionEvent.ACTION_DOWN:
260→                    downX = x;
261→                    downY = y;
262→                    popDx = 0f;
263→                    edgeSwipe = x < 62f && stack.size() > 1;
264→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_DOWN, x, y);
265→                    return true;
266→                case MotionEvent.ACTION_MOVE:
267→                    if (edgeSwipe) {
268→                        float dx = x - downX;
269→                        if (dx > 8f) {
270→                            popDx = dx;
271→                            invalidate();
272→                        }
273→                    } else {
274→                        s.touch(MotionEvent.ACTION_MOVE, x, y);
275→                    }
276→                    return true;
277→                case MotionEvent.ACTION_UP:
278→                    if (edgeSwipe) {
279→                        if (popDx > W * 0.22f) {
280→                            finishPopGesture();
281→                        } else if (popDx > 8f) {
282→                            springBack();
283→                        } else if (Math.abs(x - downX) < 20f && Math.abs(y - downY) < 20f) {
284→                            s.touch(MotionEvent.ACTION_UP, x, y);
285→                        }
286→                        // popDx 的归零交给动画结束回调，避免中间闪一帧
287→                        return true;
288→                    }
289→                    s.touch(MotionEvent.ACTION_UP, x, y);
290→                    return true;
291→                case MotionEvent.ACTION_CANCEL:
292→                    if (edgeSwipe) {
293→                        springBack();
294→                    } else {
295→                        s.touch(MotionEvent.ACTION_CANCEL, x, y);
296→                    }
297→                    return true;
298→            }
299→            return true;
300→        }
301→
302→        /** 手势滑够了：接着滑完剩下的 1/3，然后真正出栈。 */
303→        private void finishPopGesture() {
304→            final float from = popDx;
305→            final float to = W * 0.55f;
306→            startFloatAnim(from, to, 170, () -> {
307→                popDx = 0f;
308→                popTopNoAnim();
309→            });
310→        }
311→
312→        private void springBack() {
313→            final float from = popDx;
314→            startFloatAnim(from, 0f, 220, () -> popDx = 0f);
315→        }
316→
317→        private void startFloatAnim(final float from, final float to, int dur, final Runnable done) {
318→            if (anim != null) anim.cancel();
319→            final ValueAnimator a = ValueAnimator.ofFloat(from, to);
320→            anim = a;
321→            a.setDuration(dur);
322→            a.setInterpolator(new DecelerateInterpolator(1.6f));
323→            a.addUpdateListener(v -> {
324→                popDx = (float) v.getAnimatedValue();
325→                invalidate();
326→            });
327→            a.addListener(new AnimatorListenerAdapter() {
328→                @Override
329→                public void onAnimationEnd(Animator an) {
330→                    if (an == anim) done.run();
331→                    invalidate();
332→                }
333→            });
334→            a.start();
335→        }
336→
337→        /** 手势返回专用：不再播放转场（画面已经跟着手指走完了）。 */
338→        private void popTopNoAnim() {
339→            if (stack.size() <= 1) return;
340→            Screen gone = stack.remove(stack.size() - 1);
341→            gone.onLeave();
342→            Screen next = top();
343→            if (next != null) next.onResume();
344→            animating = false;
345→            animFrom = null;
346→            invalidate();
347→        }
348→    }
349→}
