 22→/** 视频列表（参考腕凉播放器的全宽条目风格）。 */
 23→public class VideosScreen extends Screen {
 24→
 25→    private static final float L = 40f, R = 426f, TOP = 118f, BOT = 424f;
 26→    private static final float ROW_H = 84f, GAP = 8f;
 27→
 28→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
 29→    private final Scroll sc = new Scroll(this::invalidate);
 30→    private boolean loading = true;
 31→
 32→    public VideosScreen(MainActivity a) {
 33→        super(a);
 34→    }
 35→
 36→    @Override
 37→    public void onEnter() {
 38→        Index.Snap s0 = Index.get();
 39→        if (s0 != null) apply(s0.videos);
 40→        Index.ensure(act, false, s -> apply(s.videos));
 41→    }
 42→
 43→    private void apply(ArrayList<MediaScan.Item> v) {
 44→        items.clear();
 45→        items.addAll(v);
