 65→
 66→            // 缩略图
 67→            RectF th = new RectF(r.left + 10f, r.centerY() - 32f, r.left + 118f, r.centerY() + 32f);
 68→            Bitmap bm = ThumbCache.get(act, it.path, () ->
 69→                    ThumbnailUtils.createVideoThumbnail(it.path, MediaStore.Video.Thumbnails.MINI_KIND));
 70→            if (bm != null) {
 71→                Ui.bitmapCrop(c, bm, th);
 72→            } else {
 73→                Ui.round(c, th, 12f, Ui.SURFACE2);
 74→                Ui.textC(c, "▶", th.centerX(), th.centerY() + 8f, 22f, Ui.FAINT);
 75→            }
