 77→            if (it.duration > 0) {
 78→                String d = MediaScan.dur(it.duration);
 79→                RectF tag = new RectF(th.right - 52f, th.bottom - 24f, th.right - 4f, th.bottom - 4f);
 80→                Ui.round(c, tag, 6f, 0xAA000000);
 81→                Ui.textC(c, d, tag.centerX(), tag.centerY() + 5f, 12f, 0xFFFFFFFF);
 82→            }
