 87→        }
 88→        c.restore();
 89→
 90→        if (loading) Ui.textC(c, "扫描视频中…", 233f, 280f, 20f, Ui.FAINT);
 91→        if (!loading && items.isEmpty()) {
 92→            Ui.textC(c, "没有找到视频", 233f, 270f, 20f, Ui.FAINT);
 93→            Ui.textC(c, "可先用快传把视频传到手表", 233f, 300f, 15f, Ui.FAINT);
 94→        }
 95→    }
