 99→        if (action == MotionEvent.ACTION_DOWN) {
100→            sc.begin(y);
101→            return true;
102→        }
103→        if (action == MotionEvent.ACTION_MOVE) {
104→            float before = sc.off;
105→            sc.move(y);
106→            if (sc.off != before) invalidate();
107→            return true;
108→        }
109→        if (action == MotionEvent.ACTION_UP) {
110→            sc.end();
111→            if (sc.dragDist() > 12f) return true;
112→            if (hitBack(x, y)) {
