 22→/** 应用占用：每个已安装应用占了多少空间、占全盘的百分比，从大到小。 */
 23→public class AppsScreen extends Screen {
 24→
 25→    private static final float L = 44f, R = 422f, TOP = 180f, BOT = 428f;
 26→    private static final float ROW_H = 60f, GAP = 6f;
 27→
 28→    private final List<Apps.App> items = new ArrayList<>();
 29→    private final Scroll sc = new Scroll(this::invalidate);
 30→    private boolean loading = true;
