158→    private void row(Canvas c, float y, String label, long v, int lc, int vc) {
159→        Ui.textL(c, label, 86f, y, 14f, lc);
160→        Ui.textR(c, v < 0 ? "—" : Fs.human(v), 380f, y, 14f, vc);
