163→    private String percent(long size) {
164→        if (size < 0) return "—";
165→        if (totalSpace <= 0) return Fs.human(size);
166→        float p = size * 100f / totalSpace;
167→        if (p >= 10f) return String.format(Locale.US, "%.0f%%", p);
168→        if (p >= 0.1f) return String.format(Locale.US, "%.1f%%", p);
