177→    @Override
178→    public boolean touch(int action, float x, float y) {
179→        if (sel >= 0) return detailTouch(action, x, y);
180→        if (action == MotionEvent.ACTION_DOWN) {
181→            sc.begin(y);
182→            return true;
183→        }
184→        if (action == MotionEvent.ACTION_MOVE) {
185→            float before = sc.off;
186→            sc.move(y);
187→            if (sc.off != before) invalidate();
188→            return true;
189→        }
190→        if (action == MotionEvent.ACTION_UP) {
191→            sc.end();
192→            if (sc.dragDist() > 12f) return true;
193→            if (hitBack(x, y)) {
194→                act.pop();
195→                return true;
196→            }
197→            if (y < TOP || y > BOT) return false;
198→            int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
199→            if (idx < 0 || idx >= items.size()) return false;
200→            sel = idx;
201→            invalidate();
202→            return true;
203→        }
204→        return false;
205→    }
206→
207→    private boolean detailTouch(int action, float x, float y) {
208→        if (action != MotionEvent.ACTION_UP) return true;
209→        Apps.App a = items.get(sel);
210→        float by = detailBtnTop(a);
211→        if (y >= by && y <= by + 34f) {
212→            if (x >= 92f && x <= 228f) {
213→                sel = -1;
214→                invalidate();
215→                openDetails(a);
216→                return true;
217→            }
218→            if (x >= 238f && x <= 374f) {
219→                sel = -1;
220→                invalidate();
221→                return true;
222→            }
223→        }
224→        sel = -1;
225→        invalidate();
226→        return true;
227→    }
228→
229→    @Override
230→    public boolean back() {
231→        if (sel >= 0) {
232→            sel = -1;
233→            invalidate();
234→            return true;
235→        }
236→        return false;
237→    }
238→
239→    private void openDetails(Apps.App a) {
240→        try {
241→            Intent i = new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
242→                    Uri.parse("package:" + a.pkg));
243→            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
244→            act.startActivity(i);
245→        } catch (Throwable t) {
246→            act.toast("打不开系统应用信息");
247→        }
248→    }
249→}
