172→        return (a << 24) | (Math.min(255, r) << 16) | (Math.min(255, g) << 8) | Math.min(255, b);
173→    }
174→
175→    public static int alpha(int color, int a) {
176→        return (color & 0x00FFFFFF) | ((a & 0xFF) << 24);
177→    }
178→
179→    private static final android.graphics.Rect SR = new android.graphics.Rect();
180→    private static final android.graphics.Rect DR = new android.graphics.Rect();
181→
182→    /** 整图绘制到目标矩形（拉伸）。 */
183→    public static void bitmap(Canvas c, Bitmap b, RectF dst) {
184→        if (b == null || b.isRecycled()) return;
185→        SR.set(0, 0, b.getWidth(), b.getHeight());
186→        DR.set((int) dst.left, (int) dst.top, (int) dst.right, (int) dst.bottom);
187→        c.drawBitmap(b, SR, DR, null);
188→    }
189→
190→    /** 裁剪填充绘制（保持比例，居中裁掉超出的部分）。 */
191→    public static void bitmapCrop(Canvas c, Bitmap b, RectF dst) {
192→        if (b == null || b.isRecycled()) return;
193→        float bw = b.getWidth(), bh = b.getHeight();
194→        float scale = Math.max(dst.width() / bw, dst.height() / bh);
195→        float sw = dst.width() / scale, sh = dst.height() / scale;
196→        SR.set((int) ((bw - sw) / 2f), (int) ((bh - sh) / 2f),
197→                (int) ((bw + sw) / 2f), (int) ((bh + sh) / 2f));
198→        DR.set((int) dst.left, (int) dst.top, (int) dst.right, (int) dst.bottom);
199→        c.drawBitmap(b, SR, DR, null);
200→    }
201→}
