{"content":"<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<title>腕上管家 · 卡片流预览</title>
<style>
  html,body{margin:0;height:100%;background:#0d0f12;display:flex;align-items:center;justify-content:center;font-family:"Microsoft YaHei",sans-serif;flex-direction:column;gap:18px}
  .tabs{display:flex;gap:10px}
  .tab{padding:8px 22px;border-radius:20px;border:1px solid #2c2c2c;background:#161616;color:#a9a9a9;cursor:pointer;font-size:14px}
  .tab.on{background:#fff;color:#000;border-color:#fff}
  #wrap{position:relative;width:466px;height:466px;border-radius:50%;overflow:hidden;box-shadow:0 0 0 3px #222,0 12px 60px #000;cursor:grab;touch-action:none}
  #wrap:active{cursor:grabbing}
  canvas{display:block}
  .tip{color:#6a6a6a;font-size:13px}
</style>
</head>
<body>
<div class="tabs">
  <div class="tab on" id="tVideos" onclick="setPage(0)">视频</div>
  <div class="tab" id="tApps" onclick="setPage(1)">应用</div>
</div>
<div id="wrap"><canvas id="cv" width="466" height="466"></canvas></div>
<div class="tip">鼠标按住拖动滚动（模拟手指），松手带惯性 · 中间的卡片大，往两端逐级变小</div>
<script>
const cv = document.getElementById('cv'), ctx = cv.getContext('2d');
const W=466,H=466,CX=233,CY=233;
// 与 Java 端一致的颜色
const BG='#000000',SURFACE='#121212',SURFACE2='#1f1f1f',TEXT='#ffffff',DIM='#a9a9a9',FAINT='#6a6a6a';
const CATE_COLORS=['#4DA3FF','#58D6C9','#9B7BFF','#3DDC84','#FFB454','#FF8FA3','#66B3FF','#8CA0B4','#D98CB3','#8FBF6F'];

// 假数据
const videos=[];
const vnames=['环游太空日记','蜜雪冰城主题曲','凌晨四点的洛杉矶','如何给手表装软件','猫咪踩奶实录','一加手表开箱','周游记·川西','代码重构指南','城市夜景延时','ergonomics 键盘评测','手冲咖啡入门','黑胶唱片修复'];
vnames.forEach((n,i)=>videos.push({n,s:(0.12+((i*37)%23)/10)+'GB',d:`${(i%9)+1}:${String((i*13)%60).padStart(2,'0')}`,h:((i*97)%360)}));
const apps=[];
const anames=['微信','QQ','抖音','哔哩哔哩','王者荣耀','原神','淘宝','支付宝','高德地图','网易云音乐','美团','小红书','WPS','迅雷','百度地图','腾讯视频'];
anames.forEach((n,i)=>apps.push({n,s:(1.2+((i*53)%40)/4).toFixed(2)+'GB',p:(2+((i*29)%40))}));

let page=0;
let off=0, vel=0, dragging=false, lastY=0, lastT=0, downY=0, moved=false;
const ROW_H=page=>page===0?96:68, GAP=page=>page===0?10:8;
const TOP=()=>page===0?112:176, BOT=()=>page===0?430:434;
const L=34,R=432;
const items=()=>page===0?videos:apps;
const maxOff=()=>Math.max(0,items().length*(ROW_H(page)+GAP(page))-(BOT()-TOP()));

function setPage(p){page=p;off=0;vel=0;
  document.getElementById('tVideos').className='tab'+(p===0?' on':'');
  document.getElementById('tApps').className='tab'+(p===1?' on':'');}

// 卡片流缩放：与 Ui.flow 相同公式（平方衰减，边缘最小 0.66）
function flow(slotT,slotB,viewT,viewB){
  const cy=(slotT+slotB)/2, mid=(viewT+viewB)/2, half=(viewB-viewT)/2;
  const d=Math.min(1,Math.abs(cy-mid)/half);
  const s=1-0.34*d*d;
  const w=(R-L)*s, h=(slotB-slotT)*s, cx=CX;
  return [cx-w/2, cy-h/2, cx+w/2, cy+h/2, s];
}

function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function drawHeader(){
  ctx.fillStyle=BG;ctx.fillRect(0,0,W,H);
  ctx.fillStyle=TEXT;ctx.font='600 20px "Microsoft YaHei"';ctx.textAlign='left';
  ctx.fillText(page===0?'视频':(items().length+' 个应用').slice(0,0)||'应用占用',64,80);
  ctx.textAlign='left';
  ctx.fillText(page===0?'视频':'应用占用',64,80);
  ctx.fillStyle=FAINT;ctx.font='13px "Microsoft YaHei"';ctx.textAlign='right';
  ctx.fillText(page===0?videos.length+' 个':'共 '+apps.length+' 个',404,80);
  // 顶部存储条（应用页）
  if(page===1){
    ctx.fillStyle=TEXT;ctx.font='600 24px "Microsoft YaHei"';ctx.textAlign='left';
    ctx.fillText('9.69 GB',66,144);
    ctx.fillStyle=DIM;ctx.font='14px "Microsoft YaHei"';ctx.textAlign='right';
    ctx.fillText('占存储 41%',404,142);
    ctx.fillStyle=SURFACE2;rr(66,150,338,8,4);ctx.fill();
    ctx.fillStyle='#fff';rr(66,150,338*0.41,8,4);ctx.fill();
  }
}
function drawBack(){ctx.strokeStyle=TEXT;ctx.lineWidth=2.4;ctx.lineCap='round';
  ctx.beginPath();ctx.moveTo(52,66);ctx.lineTo(40,73.5);ctx.lineTo(52,81);ctx.stroke();}

function draw(){
  drawHeader();drawBack();
  const viewT=TOP()+off, viewB=BOT()+off;
  ctx.save();
  ctx.beginPath();ctx.rect(0,TOP(),W,BOT()-TOP());ctx.clip();
  ctx.translate(0,-off);
  const arr=items();
  for(let i=0;i<arr.length;i++){
