      const g=ctx.createLinearGradient(l+pad,t+pad,l+pad+thW,b-pad);
      g.addColorStop(0,`hsl(${it.h} 45% 42%)`);g.addColorStop(1,`hsl(${(it.h+60)%360} 55% 24%)`);
      ctx.fillStyle=g;ctx.fillRect(l+pad,t+pad,thW,b-t-2*pad);
      ctx.restore();
      // 时长角标
      ctx.fillStyle='rgba(0,0,0,.72)';rr(l+pad+thW-56,b-pad-24,52,22,8);ctx.fill();
      ctx.fillStyle='#fff';ctx.font='11px "Microsoft YaHei"';ctx.textAlign='center';
      ctx.fillText(it.d,l+pad+thW-30,b-pad-8);
      // 名字 + 大小
      ctx.fillStyle=TEXT;ctx.font='600 17px "Microsoft YaHei"';ctx.textAlign='left';
      ctx.fillText(ellip(it.n,17,r2-(l+pad+thW)-24),l+pad+thW+12,t+(b-t)*.42+6);
      ctx.fillStyle=FAINT;ctx.font='13px "Microsoft YaHei"';
      ctx.fillText(it.s,l+pad+thW+12,t+(b-t)*.68+5);
    }else{
