      ctx.save();ctx.beginPath();ctx.roundRect(ix,iy,icS,icS,rad);ctx.clip();
      ctx.fillStyle=CATE_COLORS[i%CATE_COLORS.length]+'38';ctx.fillRect(ix,iy,icS,icS);
      ctx.fillStyle=CATE_COLORS[i%CATE_COLORS.length];ctx.font=`600 ${icS*.46}px "Microsoft YaHei"`;
