      ctx.fillStyle=FAINT;ctx.font='14px "Microsoft YaHei"';ctx.textAlign='right';
      ctx.fillText(it.s,r2-12,t+28);
      // 占比细条
      const bw=(r2-12)-(ix+icS+12);
      ctx.fillStyle=SURFACE2;rr(ix+icS+12,b-10,bw,3,1.5);ctx.fill();
      ctx.fillStyle='rgba(255,255,255,.67)';rr(ix+icS+12,b-10,bw*Math.min(1,it.p/42),3,1.5);ctx.fill();
    }
  }
  ctx.restore();
}
function ellip(s,size,maxW){
  ctx.font=`600 ${size}px "Microsoft YaHei"`;
  if(ctx.measureText(s).width<=maxW)return s;
  let lo=0,hi=s.length;
  while(lo<hi){const m=(lo+hi+1)>>1;
    if(ctx.measureText(s.slice(0,m)+'…').width<=maxW)lo=m;else hi=m-1;}
  return s.slice(0,lo)+'…';
}
function loop(){
  if(!dragging){
    off+=vel;vel*=0.92;
    if(Math.abs(vel)<0.1)vel=0;
    if(off<0){off=0;vel=0;}
    if(off>maxOff()){off=maxOff();vel=0;}
  }
  draw();requestAnimationFrame(loop);
}
