  const now=performance.now(),dt=now-lastT;
  if(dt>0)vel=-dy/dt*16*0.6+vel*0.4;
  lastY=e.clientY;lastT=now;
  if(off<0)off=0;if(off>maxOff())off=maxOff();
  e.preventDefault();
}
function up(e){
  if(!dragging)return;dragging=false;
  if(!moved&&e.clientY>TOP()&&e.clientY<BOT()){
    const i=Math.floor((e.clientY+off-TOP())/(ROW_H(page)+GAP(page)));
    if(i>=0&&i<items().length)flash(i);
  }
}
