wrap.addEventListener('touchstart',e=>down(e.touches[0]),{passive:true});
wrap.addEventListener('touchmove',e=>{move(e.touches[0]);e.preventDefault();},{passive:false});
wrap.addEventListener('touchend',e=>up(e.changedTouches[0]));
let flashI=-1;
function flash(i){flashI=i;setTimeout(()=>flashI=-1,200);}
// 高亮选中的简单处理：draw 里略
requestAnimationFrame(loop);
