 88→        collect(new File(Fs.ROOT, "DCIM/.thumbnails"), thumbs, 0);
 89→
 90→        ArrayList<File> cache = new ArrayList<>();
 91→        File[] apps = new File(Fs.ROOT, "Android/data").listFiles();
 92→        if (apps != null) {
 93→            for (File app : apps) {
 94→                collect(new File(app, "cache"), cache, 0);
 95→                collect(new File(app, "code_cache"), cache, 0);
 96→            }
 97→        }
 98→
 99→        ArrayList<Cat> out = new ArrayList<>();
100→        out.add(mk("应用缓存", "各应用临时文件", "缓", 0xFFFFC46B, cache));
101→        out.add(mk("缩略图", "DCIM/.thumbnails", "图", 0xFF58D6C9, thumbs));
102→        out.add(mk("日志文件", "存储里的 *.log", "志", 0xFF8CA0B4, s.logs));
103→        out.add(mk("安装包", "Download 里的 *.apk", "装", 0xFF3DDC84, s.apks));
104→
105→        Cat big = mk("大文件", "超过 200MB，请自行确认", "大", 0xFFFF8FA3, s.big);
106→        big.info = true;
107→        big.checked = false;
108→        out.add(big);
109→
110→        Cat empty = mk("空文件夹", "不占空间，可顺手清掉", "空", 0xFF66B3FF, s.emptyDirs);
111→        empty.checked = false;
112→        out.add(empty);
113→
114→        // 分类也按体积从大到小，最占地方的一眼可见
115→        out.sort((a, b) -> Long.compare(b.size, a.size));
116→
117→        act.ui(() -> {
118→            cats.clear();
119→            cats.addAll(out);
120→            scanning = false;
121→            sc.max = Math.max(0, cats.size() * (ROW_H + GAP) - (BOT - TOP));
122→            sc.clamp();
123→            invalidate();
124→        });
125→    }
