127→    private static Cat mk(String name, String desc, String glyph, int color, ArrayList<File> files) {
128→        Cat ct = new Cat(name, desc, glyph, color);
129→        ct.files.addAll(files);
130→        ct.count = ct.files.size();
131→        for (File f : ct.files) ct.size += f.length();
132→        return ct;
