135→    private static void collect(File dir, ArrayList<File> out, int depth) {
136→        if (depth > 8) return;
137→        File[] kids = dir.listFiles();
138→        if (kids == null) return;
139→        for (File k : kids) {
140→            if (k.isDirectory()) collect(k, out, depth + 1);
141→            else out.add(k);
142→        }
143→    }
