213→    @Override
214→    public boolean touch(int action, float x, float y) {
215→        if (action == MotionEvent.ACTION_DOWN) {
216→            if (confirmMode != 0) return true;
217→            sc.begin(y);
218→            return true;
219→        }
220→        if (action == MotionEvent.ACTION_MOVE) {
221→            if (confirmMode != 0) return false;
222→            float before = sc.off;
223→            sc.move(y);
224→            if (sc.off != before) invalidate();
225→            return true;
226→        }
227→        if (action == MotionEvent.ACTION_UP) {
228→            if (confirmMode == 1) {
229→                if (x >= 92f && x <= 228f && y >= 280f && y <= 324f) {
230→                    confirmMode = 0;
231→                    doClean();
232→                } else {
233→                    confirmMode = 0;
234→                }
235→                invalidate();
236→                return true;
237→            }
238→            sc.end();
239→            if (sc.dragDist() > 12f) return true;
240→            if (hitBack(x, y)) {
241→                act.pop();
242→                return true;
243→            }
244→            if (btnClean.contains(x, y) && !scanning && checkedCount() > 0) {
245→                confirmMode = 1;
246→                invalidate();
247→                return true;
248→            }
249→            if (y >= TOP && y <= BOT) {
250→                int idx = (int) ((y + sc.off - TOP) / (ROW_H + GAP));
251→                if (idx >= 0 && idx < cats.size()) {
252→                    Cat ct = cats.get(idx);
253→                    if (!ct.info) {
254→                        ct.checked = !ct.checked;
255→                        invalidate();
256→                    }
257→                }
258→            }
259→            return true;
260→        }
261→        return false;
262→    }
263→
264→    private void doClean() {
265→        ArrayList<File> doomed = new ArrayList<>();
266→        for (Cat ct : cats) {
267→            if (ct.checked && !ct.info) doomed.addAll(ct.files);
268→        }
269→        if (doomed.isEmpty()) return;
270→        final long before = checkedSize();
271→        act.toast("清理中…");
272→        act.bg(() -> {
273→            int ok = 0;
274→            for (File f : doomed) {
275→                if (Fs.delete(f)) ok++;
276→            }
277→            // 删完立刻同步重建索引：这样重扫时拿到的是清理后的真实数据，
278→            // 各页面（分析/视频/相册/清理）不用退出应用就能看到新数字
279→            Index.rebuild(act);
280→            final int n = ok;
281→            act.ui(() -> {
282→                act.toast("已清理 " + n + " 项 · " + Fs.human(before));
283→                loadSpace();
284→                scan();
285→            });
286→        });
287→    }
