 21→import java.util.concurrent.Executors;
 22→import java.util.concurrent.Future;
 23→
 24→/**
 25→ * 一次遍历、全应用共用的一份存储索引。
 26→ *
 27→ * <p>以前 视频/音乐/相册/分析/清理 各自把整盘走一遍（5 次），每次都靠
 28→ * File.length()/isDirectory()/lastModified() 各触发一次 stat。现在改为：
 29→ * ① 单次遍历，用 Os.stat 一次拿全 inode 信息（stat 调用从 3 次降到 1 次）；
 30→ * ② 顶层目录 4 线程并行；
 31→ * ③ 结果落盘缓存，下次开应用先用缓存、再后台刷新。
 32→ */
 33→public final class Index {
 34→
 35→    public interface Callback {
 36→        /** 可能在主线程被调用两次：先旧缓存，后新结果。 */
 37→        void onIndex(Snap s);
 38→    }
 39→
 40→    /** 一份完整的存储快照。 */
 41→    public static final class Snap {
 42→        public final Fs.Stats stats = new Fs.Stats();
 43→        public final ArrayList<MediaScan.Item> videos = new ArrayList<>();
 44→        public final ArrayList<MediaScan.Item> audios = new ArrayList<>();
 45→        public final ArrayList<MediaScan.Item> images = new ArrayList<>();
 46→        public final ArrayList<File> logs = new ArrayList<>();
 47→        public final ArrayList<File> apks = new ArrayList<>();
 48→        public final ArrayList<File> big = new ArrayList<>();
 49→        public final ArrayList<File> emptyDirs = new ArrayList<>();
 50→        public final ArrayList<File> top = new ArrayList<>();
 51→        public long builtAt;
 52→
 53→        private static final long BIG = 200L * 1024 * 1024;
 54→
 55→        synchronized void add(String path, String name, long size, long mtime) {
 56→            stats.add(name, size);
 57→            String cat = Fs.cat(name);
 58→            if ("视频".equals(cat)) {
 59→                videos.add(item(path, name, size, mtime));
 60→            } else if ("音频".equals(cat)) {
 61→                audios.add(item(path, name, size, mtime));
 62→            } else if ("图片".equals(cat)) {
 63→                images.add(item(path, name, size, mtime));
 64→            }
 65→            String ext = Fs.ext(name);
 66→            if ("log".equals(ext)) {
 67→                if (logs.size() < 800) logs.add(new File(path));
 68→            } else if ("apk".equals(ext) && path.contains("/Download/") && apks.size() < 200) {
 69→                apks.add(new File(path));
 70→            }
 71→            if (size >= BIG && big.size() < 150) big.add(new File(path));
 72→            if (size > 4L * 1024 * 1024) {
 73→                top.add(new File(path));
 74→                if (top.size() > 24) {
 75→                    Collections.sort(top, (a, b) -> Long.compare(b.length(), a.length()));
 76→                    while (top.size() > 8) top.remove(top.size() - 1);
 77→                }
 78→            }
 79→        }
 80→
 81→        synchronized void empty(File dir) {
 82→            if (emptyDirs.size() < 400) emptyDirs.add(dir);
 83→        }
 84→
 85→        private static MediaScan.Item item(String path, String name, long size, long mtime) {
 86→            MediaScan.Item it = new MediaScan.Item();
 87→            it.path = path;
 88→            it.name = name;
 89→            it.size = size;
 90→            it.modified = mtime;
 91→            return it;
 92→        }
 93→
 94→        void finish() {
 95→            // 所有媒体列表统一按「体积从大到小」，一眼看到最占地方的东西
 96→            java.util.Comparator<MediaScan.Item> bySize =
 97→                    (a, b) -> Long.compare(b.size, a.size);
 98→            Collections.sort(videos, bySize);
 99→            Collections.sort(audios, bySize);
100→            Collections.sort(images, bySize);
101→            Collections.sort(top, (a, b) -> Long.compare(b.length(), a.length()));
102→            while (top.size() > 8) top.remove(top.size() - 1);
103→            if (!top.isEmpty()) {
104→                stats.topSize = top.get(0).length();
105→                stats.topPath = top.get(0).getAbsolutePath();
106→            }
107→        }
108→    }
109→
110→    private static final long TTL = 20 * 60 * 1000L;
111→    private static volatile Snap cur;
112→
113→    private static final ExecutorService BUILD = Executors.newSingleThreadExecutor();
114→    private static final Handler MAIN = new Handler(Looper.getMainLooper());
115→
116→    private Index() {}
117→
118→    /** 内存里已有的快照，没有则返回 null（不会触发磁盘读取）。 */
119→    public static Snap get() {
120→        return cur;
121→    }
122→
123→    /**
124→     * 取索引：先回调旧缓存（秒开），需要时再后台重建并回调新结果。
125→     * 回调都在主线程。
126→     */
127→    public static void ensure(final Context ctx, final boolean force, final Callback cb) {
128→        final Context app = ctx.getApplicationContext();
129→        BUILD.execute(() -> {
130→            Snap s = cur;
131→            if (s == null) {
132→                s = loadDisk(app);
133→                if (s != null) cur = s;
134→            }
135→            if (s != null) post(cb, s);
136→            boolean stale = force || s == null
137→                    || System.currentTimeMillis() - s.builtAt > TTL;
138→            if (!stale) return;
139→            Snap fresh = build();
140→            cur = fresh;
141→            saveDisk(app, fresh);
142→            post(cb, fresh);
143→        });
144→    }
145→
146→    private static void post(final Callback cb, final Snap s) {
147→        MAIN.post(() -> cb.onIndex(s));
148→    }
149→
150→    /**
151→     * 同步重建（清理完垃圾后立刻要新数据时用）：返回时 cur 与磁盘缓存都已是新快照。
152→     * 只能在后台线程调用。
153→     */
154→    public static synchronized Snap rebuild(Context ctx) {
155→        Snap s = build();
156→        cur = s;
157→        saveDisk(ctx.getApplicationContext(), s);
158→        return s;
159→    }
160→
161→    // ---------------- 遍历 ----------------
162→
163→    private static Snap build() {
164→        long t0 = System.currentTimeMillis();
165→        final Snap s = new Snap();
166→        File[] tops = Fs.root().listFiles();
167→        if (tops != null && tops.length > 0) {
168→            ExecutorService pool = Executors.newFixedThreadPool(4);
169→            List<Future<?>> jobs = new ArrayList<>();
170→            for (final File f : tops) {
171→                String n = f.getName();
172→                if (n.equals("Android") || n.startsWith(".")) continue;
173→                try {
174→                    jobs.add(pool.submit(() -> walk(f, 0, s)));
175→                } catch (Throwable ignored) {
176→                }
177→            }
178→            for (Future<?> j : jobs) {
179→                try {
180→                    j.get();
181→                } catch (Throwable ignored) {
182→                }
183→            }
184→            pool.shutdown();
185→        }
186→        s.builtAt = System.currentTimeMillis();
187→        s.finish();
188→        android.util.Log.i("WatchSuite", "index built: " + s.stats.files + " files, "
189→                + (s.builtAt - t0) + " ms");
190→        return s;
191→    }
192→
193→    private static void walk(File dir, int depth, Snap s) {
194→        if (depth > 12) return;
195→        String[] names;
196→        try {
197→            names = dir.list();
198→        } catch (Throwable t) {
199→            return;
200→        }
201→        if (names == null) return;
202→        if (names.length == 0) {
203→            if (depth > 0) s.empty(dir);
204→            return;
205→        }
206→        for (String nm : names) {
207→            String p = new File(dir, nm).getAbsolutePath();
208→            StructStat st;
209→            try {
210→                st = Os.stat(p);
211→            } catch (Throwable t) {
212→                continue;
213→            }
214→            if (OsConstants.S_ISDIR(st.st_mode)) {
215→                if (nm.equals("data") || nm.equals("obb")) {
216→                    if ("Android".equals(dir.getName())) continue;
217→                }
218→                if (nm.startsWith(".") && !nm.equals(".thumbnails")) continue;
219→                walk(new File(dir, nm), depth + 1, s);
220→            } else {
221→                s.add(p, nm, st.st_size, st.st_mtime * 1000L);
222→            }
223→        }
224→    }
225→
226→    // ---------------- 磁盘缓存 ----------------
227→
228→    private static File cacheFile(Context c) {
229→        return new File(c.getFilesDir(), "storage.idx");
230→    }
231→
232→    private static void saveDisk(Context c, Snap s) {
233→        BufferedWriter w = null;
234→        try {
235→            w = new BufferedWriter(new OutputStreamWriter(
236→                    new FileOutputStream(cacheFile(c)), "UTF-8"), 1 << 16);
237→            StringBuilder sb = new StringBuilder(256);
238→            sb.append("S|").append(s.builtAt).append('|').append(s.stats.total)
239→                    .append('|').append(s.stats.files);
240→            for (long v : s.stats.byCat) sb.append('|').append(v);
241→            for (int v : s.stats.filesByCat) sb.append('|').append(v);
