264→        BufferedReader r = null;
265→        try {
266→            r = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"), 1 << 16);
267→            Snap s = new Snap();
268→            String line = r.readLine();
269→            if (line == null || !line.startsWith("S|")) return null;
270→            String[] p = line.split("\\|");
