private void fetchDurs() {
    DUR_POOL.execute(() -> {
        android.media.MediaMetadataRetriever mm = new android.media.MediaMetadataRetriever();
        int n = 0;
        for (MediaScan.Item it : items) {
            if (DUR.containsKey(it.path)) continue;
            long d = 0;
            try { mm.setDataSource(it.path); d = Long.parseLong(mm.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION)); } catch (Throwable ignored) {}
            DUR.put(it.path, d);
            if (++n % 6 == 0) { act.ui(this::invalidate); }
        }
        try { mm.release(); } catch (Throwable ignored) {}
        act.ui(this::invalidate);
    });
}
