 73→    /** 帧率自适配：在保持当前分辨率的前提下，请求这块表支持的最高刷新率。 */
 74→    private void boostRefreshRate() {
 75→        try {
 76→            android.view.Display d = getWindowManager().getDefaultDisplay();
 77→            android.view.Display.Mode cur = d.getMode();
 78→            android.view.Display.Mode best = cur;
 79→            for (android.view.Display.Mode m : d.getSupportedModes()) {
 80→                if (m.getPhysicalWidth() == cur.getPhysicalWidth()
 81→                        && m.getPhysicalHeight() == cur.getPhysicalHeight()
 82→                        && m.getRefreshRate() > best.getRefreshRate()) {
 83→                    best = m;
 84→                }
 85→            }
 86→            WindowManager.LayoutParams lp = getWindow().getAttributes();
 87→            if (best.getRefreshRate() > cur.getRefreshRate() + 0.1f) {
 88→                lp.preferredDisplayModeId = best.getModeId();
 89→                getWindow().setAttributes(lp);
 90→            } else {
 91→                lp.preferredRefreshRate = best.getRefreshRate();
 92→                getWindow().setAttributes(lp);
 93→            }
 94→        } catch (Throwable ignored) {
 95→        }
 96→    }
