140→    /** 页面栈 + 转场动效 + 触摸分发 + 轻提示。 */
141→    public static class ShellView extends View {
142→
143→        private static final float W = 466f, CX = 233f, CY = 233f;
144→
145→        private final List<Screen> stack = new ArrayList<>();
146→        private final Handler h = new Handler(Looper.getMainLooper());
147→
148→        private String toastMsg;
149→        private long toastAt;
150→
151→        private float downX, downY;
152→        private boolean edgeSwipe;
153→        /** 边缘右滑时当前页的实时位移，0 表示没有手势。 */
154→        private float popDx;
155→
156→        // 通用适配：UI 全部按 466×466 逻辑坐标绘制，整体缩放到实际分辨率
157→        private float k = 1f, offX = 0f, offY = 0f;
158→
159→        @Override
160→        protected void onSizeChanged(int w, int h, int ow, int oh) {
161→            super.onSizeChanged(w, h, ow, oh);
162→            k = Math.min(w, h) / 466f;
163→            offX = (w - 466f * k) / 2f;
164→            offY = (h - 466f * k) / 2f;
165→        }
166→
167→        // 转场：animFrom 是「旧页面」，圆形揭示动画的进度与圆心
168→        private Screen animFrom;
169→        private boolean animPush = true;
170→        private float animP = 1f;
171→        private boolean animating;
172→        private ValueAnimator anim;
173→        /** 转场圆心：进入时取按下点，默认屏幕中心。 */
174→        private float circX = CX, circY = CY;
175→
176→        public ShellView(Context c) {
177→            super(c);
178→            setBackgroundColor(Ui.BG);
179→            // 整页常驻硬件层：每一帧都是完整合成后上屏，避免脏区/开关层造成的闪帧
180→            setLayerType(LAYER_TYPE_HARDWARE, null);
181→            // 提前建好转场离屏位图：首次点击进页面时不再触发分配（那一下会造成闪屏）
182→            circBm = android.graphics.Bitmap.createBitmap(466, 466, android.graphics.Bitmap.Config.ARGB_8888);
183→            circCv = new android.graphics.Canvas(circBm);
184→            circPaint = new android.graphics.Paint(android.graphics.Paint.FILTER_BITMAP_FLAG);
185→            circPaint.setShader(new android.graphics.BitmapShader(
186→                    circBm, android.graphics.Shader.TileMode.CLAMP, android.graphics.Shader.TileMode.CLAMP));
187→        }
188→
189→        public void push(Screen s, boolean animate) {
190→            Screen prev = top();
191→            stack.add(s);
192→            s.onEnter();
193→            if (animate && prev != null) startTransition(prev, true);
194→            else {
195→                animating = false;
196→                animFrom = null;
197→                invalidate();
198→            }
199→        }
200→
201→        public boolean popTop() {
202→            if (stack.size() <= 1) {
203→                if (!stack.isEmpty() && stack.get(0).back()) {
204→                    invalidate();
205→                    return true;
206→                }
207→                return false;
208→            }
209→            Screen gone = stack.remove(stack.size() - 1);
210→            gone.onLeave();
211→            Screen next = top();
212→            if (next != null) next.onResume();
213→            startTransition(gone, false);
214→            return true;
215→        }
216→
217→        public Screen top() {
218→            return stack.isEmpty() ? null : stack.get(stack.size() - 1);
219→        }
220→
221→        public void toast(String msg) {
222→            toastMsg = msg;
223→            toastAt = System.currentTimeMillis();
224→            invalidate();
225→            h.postDelayed(this::invalidate, 1900);
226→        }
227→
228→        // ---------------- 转场 ----------------
229→
230→        private void startTransition(final Screen from, final boolean isPush) {
231→            // 先把字段摘下来再 cancel：cancel 会同步回调 onAnimationEnd，
232→            // 若字段还指向旧动画，会被误认为「刚正常结束」而误触 done 逻辑
233→            if (anim != null) {
234→                Animator old = anim;
235→                anim = null;
236→                old.cancel();
237→            }
238→            animFrom = from;
239→            animPush = isPush;
240→            animP = 0f;
241→            animating = true;
242→            // hwLayer 已常驻
243→            anim = ValueAnimator.ofFloat(0f, 1f);
244→            anim.setDuration(isPush ? 300 : 280);
245→            anim.setInterpolator(new DecelerateInterpolator(1.7f));
246→            anim.addUpdateListener(a -> {
247→                animP = (float) a.getAnimatedValue();
248→                invalidate();
249→            });
250→            anim.addListener(new AnimatorListenerAdapter() {
251→                @Override
252→                public void onAnimationEnd(Animator a) {
253→                    // 只处理「当前正在用的那个」动画结束；被新动画顶掉的旧动画直接忽略
254→                    if (a == anim && animating) {
255→                        animating = false;
256→                        animFrom = null;
257→                        invalidate();
258→                    }
259→                }
260→            });
261→            anim.start();
262→        }
263→
264→        /** 单层绘制：先按屏幕像素平移，再以屏幕中心缩放。 */
265→        private final android.graphics.Paint layerBg = new android.graphics.Paint();
266→
267→        private void drawLayer(Canvas c, Screen s, float dx, float scale) {
268→            if (s == null) return;
269→            if (dx == 0f && scale == 1f) {
270→                s.draw(c);
271→                return;
272→            }
273→            int save = c.save();
274→            c.translate(dx, 0f);
275→            c.scale(scale, scale, CX, CY);
276→            // 层底色：页面本身只画元素不铺底，转场时若不补一块不透明整屏矩形，
277→            // 上层没画到的像素会透出下层旧页面（残影）。四周多留 8px 防锯齿缝。
278→            layerBg.setColor(Ui.BG);
279→            c.drawRect(-8f, -8f, W + 8f, 474f, layerBg);
280→            s.draw(c);
281→            c.restoreToCount(save);
282→        }
283→
284→        /** 圆心到四角的最远距离：圆形揭示需要铺满全屏的半径。 */
285→        private static float maxR(float cx, float cy) {
286→            float m = 0f;
287→            m = Math.max(m, (float) Math.hypot(cx, cy));
288→            m = Math.max(m, (float) Math.hypot(W - cx, cy));
289→            m = Math.max(m, (float) Math.hypot(cx, 466f - cy));
290→            m = Math.max(m, (float) Math.hypot(W - cx, 466f - cy));
291→            return m;
292→        }
293→
294→        /**
295→         * 以「实心圆形面板」绘制一层页面：页面（含黑底）整体随圆盘平移 dx，
296→         * 像一块圆形卡片从侧面滑入/滑出，内容与黑底同步移动。
297→         */
298→        private android.graphics.Bitmap circBm;
299→        private android.graphics.Canvas circCv;
300→        private android.graphics.Paint circPaint;
301→
302→        private void drawCircled(Canvas c, Screen s, float dx) {
303→            circBm.eraseColor(Ui.BG);   // 黑底铺进面板，和元素一起滑过来
304→            s.draw(circCv);
305→            int save = c.save();
306→            c.translate(dx, 0f);
307→            if (SQUARE) c.drawRoundRect(0f, 0f, 466f, 466f, 56f, 56f, circPaint);
308→            else c.drawCircle(CX, CY, CY, circPaint);
309→            c.restoreToCount(save);
310→        }
311→
312→        @Override
313→        protected void onDraw(Canvas c) {
314→            super.onDraw(c);
315→            int sv = c.save();
316→            c.translate(offX, offY);
317→            c.scale(k, k);
318→            draw466(c);
319→            c.restoreToCount(sv);
320→        }
321→
322→        /** 466×466 逻辑坐标下的全部绘制。 */
323→        private void draw466(Canvas c) {
324→            Screen cur = top();
325→            if (cur == null) return;
326→
327→            if (animating && animFrom != null) {
328→                float p = animP;
329→                if (animPush) {
330→                    // 进入：主页面原地不动，子页面是实心圆形面板从右滑入，黑底与内容一起移动
331→                    drawLayer(c, animFrom, 0f, 1f);
332→                    drawCircled(c, cur, W * (1f - p));
333→                } else {
334→                    // 返回：下一层原地不动，子页面圆盘向右滑出揭出下层
335→                    drawLayer(c, cur, 0f, 1f);
336→                    drawCircled(c, animFrom, W * p);
337→                }
338→            } else if (popDx > 0f && stack.size() > 1) {
339→                // 手指拖着返回：下一层原地露出，当前页作为圆盘跟手滑出
340→                drawLayer(c, stack.get(stack.size() - 2), 0f, 1f);
341→                drawCircled(c, cur, popDx);
342→            } else {
343→                cur.draw(c);
344→            }
345→
346→            if (toastMsg != null) {
347→                long dt = System.currentTimeMillis() - toastAt;
348→                if (dt < 1900) {
349→                    float a = dt < 1600 ? 1f : (1900 - dt) / 300f;
350→                    int col = ((int) (a * 235) << 24) | 0x0A0E13;
351→                    float w = Ui.measure(toastMsg, 18f) + 44f;
352→                    if (w > 400f) w = 400f;
353→                    float l = 233f - w / 2f, t = 372f, r = 233f + w / 2f, b = t + 46f;
354→                    Ui.round(c, l, t, r, b, 23f, col);
355→                    Ui.textC(c, Ui.ellipsize(toastMsg, 18f, w - 24f), 233f, t + 30f, 18f, 0xFFEAF1F8);
356→                } else {
357→                    toastMsg = null;
358→                }
359→            }
360→        }
361→
362→        // ---------------- 触摸 ----------------
363→
364→        /** 把原始触摸事件从屏幕像素坐标变换到 466 逻辑坐标。 */
365→        private MotionEvent scaleTouch(MotionEvent e) {
366→            MotionEvent m = MotionEvent.obtain(e);
367→            if (android.os.Build.VERSION.SDK_INT >= 29) {
368→                android.graphics.Matrix m4 = new android.graphics.Matrix();
369→                m4.setScale(1f / k, 1f / k);
370→                m4.postTranslate(-offX / k, -offY / k);
371→                m.transform(m4);
372→            } else {
373→                m.offsetLocation(-offX, -offY);
374→            }
375→            return m;
376→        }
377→
378→        @Override
379→        public boolean onTouchEvent(MotionEvent e) {
380→            Screen s = top();
381→            if (s == null) return true;
382→            if (animating || anim != null && anim.isRunning()) return true;   // 转场中不响应，免得点错
383→            if (s.rawTouch()) {
384→                s.touchEvent(scaleTouch(e));
385→                return true;
386→            }
387→            float x = (e.getX() - offX) / k, y = (e.getY() - offY) / k;
388→            switch (e.getActionMasked()) {
389→                case MotionEvent.ACTION_DOWN:
390→                    downX = x;
391→                    downY = y;
392→                    circX = x;
393→                    circY = y;
394→                    popDx = 0f;
395→                    edgeSwipe = x < 62f && stack.size() > 1;
396→                    if (!edgeSwipe) s.touch(MotionEvent.ACTION_DOWN, x, y);
397→                    return true;
398→                case MotionEvent.ACTION_MOVE:
399→                    if (edgeSwipe) {
400→                        float dx = x - downX;
401→                        if (dx > 8f) {
402→                            popDx = dx;
403→                            invalidate();
404→                        }
405→                    } else {
406→                        s.touch(MotionEvent.ACTION_MOVE, x, y);
407→                    }
408→                    return true;
409→                case MotionEvent.ACTION_UP:
410→                    if (edgeSwipe) {
411→                        if (popDx > W * 0.22f) {
412→                            finishPopGesture();
413→                        } else if (popDx > 8f) {
414→                            springBack();
415→                        } else if (Math.abs(x - downX) < 20f && Math.abs(y - downY) < 20f) {
416→                            s.touch(MotionEvent.ACTION_UP, x, y);
417→                        }
418→                        // popDx 的归零交给动画结束回调，避免中间闪一帧
419→                        return true;
420→                    }
421→                    s.touch(MotionEvent.ACTION_UP, x, y);
422→                    return true;
423→                case MotionEvent.ACTION_CANCEL:
424→                    if (edgeSwipe) {
425→                        springBack();
426→                    } else {
427→                        s.touch(MotionEvent.ACTION_CANCEL, x, y);
428→                    }
429→                    return true;
430→            }
431→            return true;
432→        }
433→
434→        /** 转场/手势期间把整页合成进硬件层，避免脏区重绘造成的闪帧。 */
435→        private void hwLayer(boolean on) {
436→            setLayerType(on ? LAYER_TYPE_HARDWARE : LAYER_TYPE_NONE, null);
437→        }
438→
439→        /** 手势滑够了：接着滑完剩下的 1/3，然后真正出栈。 */
440→        private void finishPopGesture() {
441→            final float from = popDx;
442→            final float to = W * 0.55f;
443→            // hwLayer 已常驻
444→            startFloatAnim(from, to, 170, () -> {
445→                popDx = 0f;
446→                popTopNoAnim();
447→            });
448→        }
449→
450→        private void springBack() {
451→            final float from = popDx;
452→            // hwLayer 已常驻
453→            startFloatAnim(from, 0f, 220, () -> popDx = 0f);
454→        }
455→
456→        private void startFloatAnim(final float from, final float to, int dur, final Runnable done) {
457→            if (anim != null) {
458→                Animator old = anim;
459→                anim = null;
460→                old.cancel();
461→            }
462→            final ValueAnimator a = ValueAnimator.ofFloat(from, to);
463→            anim = a;
464→            a.setDuration(dur);
465→            a.setInterpolator(new DecelerateInterpolator(1.6f));
466→            a.addUpdateListener(v -> {
467→                popDx = (float) v.getAnimatedValue();
468→                invalidate();
469→            });
470→            a.addListener(new AnimatorListenerAdapter() {
471→                @Override
472→                public void onAnimationEnd(Animator an) {
473→                    if (an == anim) done.run();
474→                    invalidate();
475→                }
476→            });
477→            a.start();
478→        }
479→
480→        /** 手势返回专用：不再播放转场（画面已经跟着手指走完了）。 */
481→        private void popTopNoAnim() {
482→            if (stack.size() <= 1) return;
483→            Screen gone = stack.remove(stack.size() - 1);
484→            gone.onLeave();
485→            Screen next = top();
486→            if (next != null) next.onResume();
487→            animating = false;
488→            animFrom = null;
489→            invalidate();
490→        }
491→    }
492→}
