 21→/** 相册：三列缩略图网格（参考腕间图库的全出血风格）。 */
 22→public class GalleryScreen extends Screen {
 23→
 24→    private static final float L = 40f, R = 426f, TOP = 116f, BOT = 424f;
 25→    private static final int COLS = 3;
 26→    private static final float CELL = (R - L - 2 * 6f) / COLS; // 124.7
 27→    private static final float CELL_GAP = 10f, ROW_GAP = 10f;
 28→    private static final float ROW_H = CELL + ROW_GAP;
 29→
 30→    private final ArrayList<MediaScan.Item> items = new ArrayList<>();
 31→    private final Scroll sc = new Scroll(this::invalidate);
 32→    private boolean loading = true;
 33→
 34→    public GalleryScreen(MainActivity a) {
 35→        super(a);
 36→    }
 37→
 38→    @Override
 39→    public void onEnter() {
 40→        Index.Snap s0 = Index.get();
 41→        if (s0 != null) apply(s0.images);
 42→        Index.ensure(act, false, s -> apply(s.images));
 43→    }
 44→
 45→    private void apply(ArrayList<MediaScan.Item> v) {
 46→        items.clear();
 47→        items.addAll(v);
 48→        int rows = (items.size() + COLS - 1) / COLS;
 49→        sc.max = Math.max(0, rows * ROW_H - (BOT - TOP));
 50→        sc.clamp();
 51→        loading = false;
 52→        invalidate();
 53→    }
 54→
 55→    @Override
 56→    public void draw(Canvas c) {
 57→        header(c, "相册", items.size() + " 张");
 58→
 59→        c.save();
 60→        c.clipRect(L, TOP, R, BOT);
 61→        c.translate(0, -sc.off);
 62→        for (int i = 0; i < items.size(); i++) {
 63→            final int fi = i;
 64→            int r = i / COLS, col = i % COLS;
 65→            float x = L + col * (CELL + CELL_GAP);
 66→            float y = TOP + r * ROW_H;
 67→            if (y + CELL < TOP + sc.off || y > BOT + sc.off) continue;
 68→            RectF cell = new RectF(x, y, x + CELL, y + CELL);
 69→            Bitmap bm = ThumbCache.get(act, items.get(fi).path, () -> decode(items.get(fi).path));
 70→            if (bm != null) {
 71→                Ui.roundBitmap(c, bm, cell, 18f);
 72→            } else {
 73→                Ui.round(c, cell, 18f, Ui.SURFACE);
 74→                Ui.textC(c, "图", cell.centerX(), cell.centerY() + 8f, 22f, Ui.FAINT);
 75→            }
 76→        }
 77→        c.restore();
 78→
 79→        if (loading) Ui.textC(c, "扫描图片中…", 233f, 270f, 20f, Ui.FAINT);
 80→        if (!loading && items.isEmpty()) {
 81→            Ui.textC(c, "没有找到图片", 233f, 260f, 20f, Ui.FAINT);
 82→        }
 83→    }
 84→
 85→    private static Bitmap decode(String path) {
 86→        try {
 87→            BitmapFactory.Options o = new BitmapFactory.Options();
 88→            o.inJustDecodeBounds = true;
 89→            BitmapFactory.decodeFile(path, o);
 90→            int sample = 1;
 91→            while (o.outWidth / sample > 320 || o.outHeight / sample > 320) sample *= 2;
 92→            BitmapFactory.Options o2 = new BitmapFactory.Options();
 93→            o2.inSampleSize = sample;
 94→            return BitmapFactory.decodeFile(path, o2);
 95→        } catch (Throwable t) {
 96→            return null;
 97→        }
 98→    }
 99→
100→    @Override
101→    public boolean touch(int action, float x, float y) {
102→        if (action == MotionEvent.ACTION_DOWN) {
103→            sc.begin(y);
104→            return true;
105→        }
106→        if (action == MotionEvent.ACTION_MOVE) {
107→            float before = sc.off;
108→            sc.move(y);
109→            if (sc.off != before) invalidate();
110→            return true;
111→        }
112→        if (action == MotionEvent.ACTION_UP) {
113→            sc.end();
114→            if (sc.dragDist() > 12f) return true;
115→            if (hitBack(x, y)) {
116→                act.pop();
117→                return true;
118→            }
119→            if (y < TOP || y > BOT || x < L || x > R) return false;
