 5→import com.watchsuite.MainActivity;
 6→
 7→import java.util.Set;
 8→import java.util.concurrent.ConcurrentHashMap;
 9→import java.util.concurrent.ExecutorService;
10→import java.util.concurrent.Executors;
11→
12→/** 后台解码缩略图，带字节上限的 LRU 缓存（避免相册刷图把内存吃穿）。 */
13→public final class ThumbCache {
14→
15→    public interface Loader {
16→        Bitmap load();
17→    }
18→
19→    private static final int MAX_BYTES = 40 * 1024 * 1024;
20→
21→    private static final android.util.LruCache<String, Bitmap> MAP =
22→            new android.util.LruCache<String, Bitmap>(MAX_BYTES) {
23→                @Override
24→                protected int sizeOf(String key, Bitmap value) {
25→                    return Math.max(1, value.getByteCount());
26→                }
27→            };
28→
29→    private static final Set<String> PENDING = ConcurrentHashMap.newKeySet();
30→    /** 解码失败过的文件不再反复重试。 */
31→    private static final Set<String> FAILED = ConcurrentHashMap.newKeySet();
32→    private static final ExecutorService POOL = Executors.newFixedThreadPool(3);
33→
34→    private ThumbCache() {}
35→
36→    /** 命中返回图；未命中发起后台解码并返回 null，完成后自动刷新界面。 */
37→    public static Bitmap get(MainActivity act, String key, Loader loader) {
38→        Bitmap b = MAP.get(key);
39→        if (b != null) return b;
40→        if (FAILED.contains(key)) return null;
41→        if (PENDING.add(key)) {
42→            POOL.execute(() -> {
43→                Bitmap r = null;
44→                try {
45→                    r = loader.load();
46→                } catch (Throwable ignored) {
47→                }
48→                if (r != null) MAP.put(key, r);
49→                else FAILED.add(key);
50→                PENDING.remove(key);
51→                act.ui(() -> {
52→                    if (act.shell != null) act.shell.invalidate();
53→                });
54→            });
55→        }
56→        return null;
57→    }
58→
59→    public static void clear() {
60→        MAP.evictAll();
61→        FAILED.clear();
62→    }
63→}
