        Ui.textL(c, "2176974735@qq.com", 86f, 314f, 14f, Ui.DIM);
        Ui.textL(c, "QQ：2176974735", 86f, 336f, 14f, Ui.DIM);
        Ui.textL(c, "微信：shiMuQiuY", 86f, 358f, 14f, Ui.DIM);

